    // ── Z2-1 (M6 #2): credit real work to the goal it actually satisfies ──

    /// A goal card wired for the credit path: `created_by_session_id` (the
    /// "same roadmap" scoping key) and optional `acceptance_criteria`.
    async fn create_roadmap_goal(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        state_binding: &str,
        title: &str,
        created_by_session_id: &str,
        acceptance_criteria: &[&str],
    ) -> cards::Card {
        use crate::projects::PERSONAL_PROJECT_ID;
        cards::seed_goal_columns(pool, PERSONAL_PROJECT_ID)
            .await
            .unwrap();
        let col = cards::get_goal_column(pool, PERSONAL_PROJECT_ID, state_binding)
            .await
            .unwrap()
            .unwrap();
        let mut meta = serde_json::Map::new();
        meta.insert(
            "created_by_session_id".to_string(),
            serde_json::json!(created_by_session_id),
        );
        if !acceptance_criteria.is_empty() {
            meta.insert(
                "acceptance_criteria".to_string(),
                serde_json::json!(acceptance_criteria),
            );
        }
        cards::create_card(
            pool,
            cards::CreateCard {
                project_id: PERSONAL_PROJECT_ID.to_string(),
                title: title.to_string(),
                description: Some(String::new()),
                card_type: Some("goal".to_string()),
                column_id: Some(col.id.clone()),
                created_by: None,
                metadata_json: Some(serde_json::Value::Object(meta)),
            },
        )
        .await
        .unwrap()
    }

    async fn state_binding_of(pool: &sqlx::Pool<sqlx::Sqlite>, card_id: &str) -> String {
        sqlx::query_scalar(
            "SELECT bc.state_binding FROM cards c JOIN board_columns bc ON c.column_id = bc.id \
             WHERE c.id = ?",
        )
        .bind(card_id)
        .fetch_one(pool)
        .await
        .unwrap()
    }

    /// Fails first against the pre-fix code: `maybe_hold_review` had no
    /// credit path at all, so a worker's real diff satisfying a SIBLING
    /// goal's acceptance criteria (M6's `loc-refund-cents-drift`,
    /// `regression-trap-lru-cache-evict`, `overreach-narrow-coupon-trim`
    /// shape) was simply invisible outside the originally-assigned goal.
    #[tokio::test]
    async fn try_credit_sibling_goals_credits_only_the_satisfied_same_roadmap_sibling() {
        let pool = test_pool().await;
        let tmp = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(tmp.path().join("oracle")).unwrap();
        std::fs::write(tmp.path().join("oracle/hidden.rs"), "// real fix\n").unwrap();

        let original =
            create_roadmap_goal(&pool, "in_progress", "Goal 1 (assigned)", "roadmap-A", &[]).await;
        let sibling_ok = create_roadmap_goal(
            &pool,
            "triage",
            "Goal 2 (actually satisfied)",
            "roadmap-A",
            &["A file `oracle/hidden.rs` exists in the worktree."],
        )
        .await;
        let sibling_wrong_roadmap = create_roadmap_goal(
            &pool,
            "triage",
            "Unrelated goal, same criterion",
            "roadmap-B",
            &["A file `oracle/hidden.rs` exists in the worktree."],
        )
        .await;
        let sibling_unsatisfied = create_roadmap_goal(
            &pool,
            "triage",
            "Goal 3 (not actually satisfied)",
            "roadmap-A",
            &["A file `oracle/never_written.rs` exists in the worktree."],
        )
        .await;

        let ev = goal_engine::GoalEvidence {
            worktree_path: tmp.path().display().to_string(),
            commits: vec!["abc1234 fix: apply the real change".to_string()],
            ..Default::default()
        };

        let credited = try_credit_sibling_goals(&pool, &original, &ev, false, None).await;
        assert_eq!(credited, vec![sibling_ok.title.clone()]);

        assert_eq!(
            state_binding_of(&pool, &sibling_ok.id).await,
            "review",
            "the satisfied sibling must be credited to Review with its receipt"
        );
        assert_eq!(
            state_binding_of(&pool, &sibling_wrong_roadmap.id).await,
            "triage",
            "a same-text-satisfied sibling from a DIFFERENT roadmap must never be credited"
        );
        assert_eq!(
            state_binding_of(&pool, &sibling_unsatisfied.id).await,
            "triage",
            "an unsatisfied sibling must be left completely untouched"
        );

        let credited_card = cards::get_card(&pool, &sibling_ok.id)
            .await
            .unwrap()
            .unwrap();
        let receipt = credited_card.metadata_json["credit_receipt"]["note"]
            .as_str()
            .expect("credit_receipt.note must be recorded")
            .to_string();
        assert!(receipt.contains("credited to"), "receipt: {receipt}");
        assert!(receipt.contains(&sibling_ok.title), "receipt: {receipt}");
        assert_eq!(
            credited_card.metadata_json["dispatch_evidence"]["verdict"]["status"], "pass",
            "credit-completion must never mark a goal complete without a passing check"
        );

        let (status, kind): (String, String) =
            sqlx::query_as("SELECT status, kind FROM decisions WHERE goal_id = ?")
                .bind(&sibling_ok.id)
                .fetch_one(&pool)
                .await
                .expect("crediting must mint an approve_review decision, same as any completion");
        assert_eq!(
            status, "open",
            "outside headless auto-land the credited goal still waits in the inbox for a human"
        );
        assert_eq!(kind, "approve_review");
    }

    /// G7 finding F1 (HIGH): `grep_absent` against a criterion naming a file
    /// that was never created must NOT credit the sibling. Pre-fix,
    /// `evaluate_completion_check_locally`'s `grep_absent` arm read a missing
    /// file as `Ok(true)` ("nothing the pattern could match — trivially
    /// absent"), the opposite of the real verifier's contract
    /// (`checks.rs::run_grep_absent`: "a missing file means we cannot prove
    /// absence in it — error, not pass"). That let a goal 2 whose AC is
    /// "no TODO remains in a file goal 2 itself is supposed to create" get
    /// trivially "satisfied" by goal 1's unrelated diff, which never touches
    /// that file — credited to Review (or auto-landed to Complete under
    /// headless auto-land) with zero real work done on it.
    #[tokio::test]
    async fn try_credit_sibling_goals_never_credits_grep_absent_against_a_missing_file() {
        let pool = test_pool().await;
        let tmp = tempfile::tempdir().unwrap();
        // goal 1's real work: an unrelated file, never touching the path
        // goal 2's AC names.
        std::fs::write(tmp.path().join("unrelated.rs"), "// goal 1's own work\n").unwrap();

        let original =
            create_roadmap_goal(&pool, "in_progress", "Goal 1 (assigned)", "roadmap-Z", &[]).await;
        let sibling = create_roadmap_goal(
            &pool,
            "triage",
            "Goal 2 (must create its own file)",
            "roadmap-Z",
            &["No TODO comments remain in src/new_feature.rs"],
        )
        .await;

        let ev = goal_engine::GoalEvidence {
            worktree_path: tmp.path().display().to_string(),
            commits: vec!["abc1234 fix: unrelated change".to_string()],
            ..Default::default()
        };

        let credited = try_credit_sibling_goals(&pool, &original, &ev, false, None).await;
        assert!(
            credited.is_empty(),
            "grep_absent against a file that was never created must not credit the sibling, \
             got: {credited:?}"
        );
        assert_eq!(
            state_binding_of(&pool, &sibling.id).await,
            "triage",
            "the sibling must be left completely untouched — no vacuous pass from a missing file"
        );
    }

    /// "complete that goal (dependent promotion follows via the existing
    /// promote_and_dispatch_dependents)" — under headless auto-land, credit
    /// goes all the way to Complete through the SAME approve_review decision
    /// + auto-answer + landing path a genuinely-verified goal uses.
    #[tokio::test]
    async fn try_credit_sibling_goals_auto_lands_the_credited_goal_under_headless_auto_land() {
        let pool = test_pool().await;
        let tmp = tempfile::tempdir().unwrap();
        std::fs::write(tmp.path().join("done.txt"), "shipped\n").unwrap();

        let original = create_roadmap_goal(&pool, "in_progress", "Goal 1", "roadmap-C", &[]).await;
        let sibling = create_roadmap_goal(
            &pool,
            "ready",
            "Goal 2",
            "roadmap-C",
            &["The file `done.txt` exists confirming the change shipped."],
        )
        .await;

        let ev = goal_engine::GoalEvidence {
            worktree_path: tmp.path().display().to_string(),
            commits: vec!["deadbee fix: ship it".to_string()],
            ..Default::default()
        };

        let credited =
            try_credit_sibling_goals(&pool, &original, &ev, true, Some("coord-session-1")).await;
        assert_eq!(credited, vec![sibling.title.clone()]);

        assert_eq!(
            state_binding_of(&pool, &sibling.id).await,
            "complete",
            "headless auto-land must complete the credited goal, not just leave it in Review"
        );

        let (status, answer, acted_by): (String, Option<String>, String) = sqlx::query_as(
            "SELECT status, answer, acted_by FROM decisions WHERE goal_id = ? AND kind = 'approve_review'",
        )
        .bind(&sibling.id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(status, "answered");
        assert_eq!(answer.as_deref(), Some("approve"));
        assert_eq!(acted_by, decisions::ACTOR_AUTO_LAUNCH);
    }

    #[tokio::test]
    async fn original_goal_underlying_check_pure_helper_never_guesses_a_pass() {
        let tmp = tempfile::tempdir().unwrap();
        let ev = goal_engine::GoalEvidence {
            worktree_path: tmp.path().display().to_string(),
            commits: vec!["abc1234 fix: something real".to_string()],
            ..Default::default()
        };

        let passing = serde_json::json!({ "build_command": "true" });
        assert!(original_goal_underlying_check_passes(&passing, &ev, "goal-pure-helper").await);

        let failing = serde_json::json!({ "build_command": "false" });
        assert!(!original_goal_underlying_check_passes(&failing, &ev, "goal-pure-helper").await);

        let unknown_stack = serde_json::json!({});
        assert!(
            !original_goal_underlying_check_passes(&unknown_stack, &ev, "goal-pure-helper").await,
            "an undetectable stack must never be guessed as passing"
        );
    }

    /// G7 finding F1 (HIGH), pure-function level: `grep_absent` against a
    /// missing file must read `false` (unsatisfied), matching the real
    /// verifier's "error, not pass" contract (`checks.rs::run_grep_absent`)
    /// even though this local evaluator collapses error and fail to the same
    /// `bool`. Also covers the LOW finding: `command_exit_zero` with an
    /// empty/whitespace `cmd` must never read as a pass (`sh -c ""` exits 0
    /// trivially).
    #[tokio::test]
    async fn evaluate_completion_check_locally_never_vacuously_passes() {
        let tmp = tempfile::tempdir().unwrap();

        let grep_absent_missing_file = serde_json::json!({
            "type": "grep_absent",
            "pattern": "TODO",
            "paths": ["never_written.rs"],
        });
        assert!(
            !evaluate_completion_check_locally(
                &grep_absent_missing_file,
                tmp.path(),
                "goal-vacuous-pass",
            )
            .await,
            "grep_absent against a file that does not exist must not pass"
        );

        // Positive control: grep_absent against a file that DOES exist and
        // does not contain the pattern must still pass.
        std::fs::write(tmp.path().join("present.rs"), "// nothing to see\n").unwrap();
        let grep_absent_present_clean = serde_json::json!({
            "type": "grep_absent",
            "pattern": "TODO",
            "paths": ["present.rs"],
        });
        assert!(
            evaluate_completion_check_locally(
                &grep_absent_present_clean,
                tmp.path(),
                "goal-vacuous-pass",
            )
            .await,
            "grep_absent against an existing, clean file must still pass"
        );

        let empty_cmd = serde_json::json!({
            "type": "command_exit_zero",
            "cmd": "   ",
        });
        assert!(
            !evaluate_completion_check_locally(&empty_cmd, tmp.path(), "goal-vacuous-pass").await,
            "an empty/whitespace command must not pass"
        );

        // Positive control: a real, trivially-true command still passes.
        let real_cmd = serde_json::json!({
            "type": "command_exit_zero",
            "cmd": "true",
        });
        assert!(
            evaluate_completion_check_locally(&real_cmd, tmp.path(), "goal-vacuous-pass").await
        );
    }

    /// E2a pinning test: the SAME `command_exit_zero` check against the SAME
    /// (unedited) worktree content, for the SAME goal, must execute the
    /// command only once — the second call is served from
    /// `check_cache::get_or_run`. Proven by a command that appends a marker
    /// line to a file every time it actually runs: if it ran twice, the file
    /// would have two lines.
    #[tokio::test]
    async fn evaluate_completion_check_locally_caches_command_exit_zero_within_a_goal() {
        let tmp = tempfile::tempdir().unwrap();
        assert!(std::process::Command::new("git")
            .args(["-c", "init.defaultBranch=main", "init", "-q"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["config", "user.email", "test@example.com"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["config", "user.name", "Test"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        std::fs::write(tmp.path().join("seed.txt"), "seed\n").unwrap();
        assert!(std::process::Command::new("git")
            .args(["add", "seed.txt"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["commit", "--no-gpg-sign", "-qm", "seed"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());

        // The marker lives in a SEPARATE scratch dir, never inside `tmp.path()`
        // (the fingerprinted working_dir) — a marker written INSIDE it would
        // itself move the content fingerprint on every real run, defeating
        // the very cache-hit this test is pinning (I1, harness loop,
        // 2026-09-10, gate fix).
        let marker_dir = tempfile::tempdir().unwrap();
        let marker = marker_dir.path().join("ran.marker");
        let cmd = format!("echo x >> {}", marker.display());
        let check = serde_json::json!({ "type": "command_exit_zero", "cmd": cmd });

        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-e2e").await);
        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-e2e").await);

        let lines = std::fs::read_to_string(&marker).unwrap_or_default();
        assert_eq!(
            lines.lines().count(),
            1,
            "the command must have actually executed only once across both calls: {lines:?}"
        );
    }

    /// E2a pinning test, same fixture: an edit to the worktree between the
    /// two calls forces a second real execution (the content fingerprint
    /// that the cache key includes has moved).
    #[tokio::test]
    async fn evaluate_completion_check_locally_reruns_after_an_edit_between_calls() {
        let tmp = tempfile::tempdir().unwrap();
        for args in [
            vec!["-c", "init.defaultBranch=main", "init", "-q"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Test"],
        ] {
            assert!(std::process::Command::new("git")
                .args(&args)
                .current_dir(tmp.path())
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(tmp.path().join("seed.txt"), "seed\n").unwrap();
        assert!(std::process::Command::new("git")
            .args(["add", "seed.txt"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["commit", "--no-gpg-sign", "-qm", "seed"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());

        // Same reasoning as the sibling test above: keep the marker OUTSIDE
        // the fingerprinted working_dir, so the second call's execution is
        // proof of the real edit below moving the fingerprint — not an
        // artifact of the marker file's own existence doing it instead.
        let marker_dir = tempfile::tempdir().unwrap();
        let marker = marker_dir.path().join("ran.marker");
        let cmd = format!("echo x >> {}", marker.display());
        let check = serde_json::json!({ "type": "command_exit_zero", "cmd": cmd });

        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-edit").await);
        std::fs::write(tmp.path().join("seed.txt"), "seed, edited\n").unwrap();
        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-edit").await);

        let lines = std::fs::read_to_string(&marker).unwrap_or_default();
        assert_eq!(
            lines.lines().count(),
            2,
            "an edit between calls must force the command to actually run again: {lines:?}"
        );
    }

    /// E2a pinning test, same fixture: the identical command against
    /// identical, unedited content but a DIFFERENT goal id never reuses the
    /// other goal's cache entry.
    #[tokio::test]
    async fn evaluate_completion_check_locally_never_shares_cache_across_goals() {
        let tmp = tempfile::tempdir().unwrap();
        for args in [
            vec!["-c", "init.defaultBranch=main", "init", "-q"],
            vec!["config", "user.email", "test@example.com"],
            vec!["config", "user.name", "Test"],
        ] {
            assert!(std::process::Command::new("git")
                .args(&args)
                .current_dir(tmp.path())
                .status()
                .unwrap()
                .success());
        }
        std::fs::write(tmp.path().join("seed.txt"), "seed\n").unwrap();
        assert!(std::process::Command::new("git")
            .args(["add", "seed.txt"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());
        assert!(std::process::Command::new("git")
            .args(["commit", "--no-gpg-sign", "-qm", "seed"])
            .current_dir(tmp.path())
            .status()
            .unwrap()
            .success());

        let marker = tmp.path().join("ran.marker");
        let cmd = format!("echo x >> {}", marker.display());
        let check = serde_json::json!({ "type": "command_exit_zero", "cmd": cmd });

        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-alpha").await);
        assert!(evaluate_completion_check_locally(&check, tmp.path(), "goal-cache-beta").await);

        let lines = std::fs::read_to_string(&marker).unwrap_or_default();
        assert_eq!(
            lines.lines().count(),
            2,
            "two different goals must never share a cache entry: {lines:?}"
        );
    }

    /// Pinning test: "goal 1 is not left held forever (either complete if
    /// its check passes, or parked with the honest reason)" — the negative
    /// half. Nothing satisfied ⇒ the caller's pre-existing hold/park path
    /// must still run untouched.
    #[tokio::test]
    async fn maybe_credit_and_bypass_hold_defers_when_nothing_is_satisfied() {
        let pool = test_pool().await;
        let tmp = tempfile::tempdir().unwrap();
        let original = create_roadmap_goal(&pool, "in_progress", "Goal 1", "roadmap-D", &[]).await;

        let mut meta = original.metadata_json.as_object().cloned().unwrap();
        meta.insert(
            "dispatch_evidence".to_string(),
            serde_json::json!({
                "worktree_path": tmp.path().display().to_string(),
                "commits": ["abc1234 fix: partial work"],
                "baseline_commit": "seed",
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
                "diffstat": "",
                "worker_summary": "",
            }),
        );
        sqlx::query("UPDATE cards SET metadata_json = ? WHERE id = ?")
            .bind(serde_json::Value::Object(meta).to_string())
            .bind(&original.id)
            .execute(&pool)
            .await
            .unwrap();
        let refreshed = cards::get_card(&pool, &original.id).await.unwrap().unwrap();

        // No siblings for this session, and no detectable build command
        // (empty tmpdir, no explicit `build_command`) — nothing for the
        // credit path to act on.
        let bypass = maybe_credit_and_bypass_hold(&pool, &refreshed, false, None)
            .await
            .unwrap();
        assert_eq!(
            bypass, None,
            "nothing satisfied — the caller's existing hold/park logic must still run"
        );
    }

    /// Pinning test: "goal 1 is not left held forever (either complete if
    /// its check passes...)" — the positive half. The original goal's own
    /// detected build/test command passing bypasses the hold instead of
    /// requeuing correct work forever.
    #[tokio::test]
    async fn maybe_credit_and_bypass_hold_bypasses_when_the_original_goals_own_check_passes() {
        let pool = test_pool().await;
        let tmp = tempfile::tempdir().unwrap();
        let original = create_roadmap_goal(&pool, "in_progress", "Goal 1", "roadmap-E", &[]).await;

        // The project-level build_command #456's default-check detector
        // would have seeded — configured directly rather than depending on
        // a real cargo/npm toolchain being on PATH in this test.
        sqlx::query(
            "UPDATE projects SET metadata_json = json_set(metadata_json, '$.build_command', 'true') \
             WHERE id = ?",
        )
        .bind(crate::projects::PERSONAL_PROJECT_ID)
        .execute(&pool)
        .await
        .unwrap();

        let mut meta = original.metadata_json.as_object().cloned().unwrap();
        meta.insert(
            "dispatch_evidence".to_string(),
            serde_json::json!({
                "worktree_path": tmp.path().display().to_string(),
                "commits": ["abc1234 fix: real work landed on the wrong-labeled goal"],
                "baseline_commit": "seed",
                "files_changed": 1,
                "insertions": 3,
                "deletions": 1,
                "diffstat": "",
                "worker_summary": "",
            }),
        );
        sqlx::query("UPDATE cards SET metadata_json = ? WHERE id = ?")
            .bind(serde_json::Value::Object(meta).to_string())
            .bind(&original.id)
            .execute(&pool)
            .await
            .unwrap();
        let refreshed = cards::get_card(&pool, &original.id).await.unwrap().unwrap();

        let bypass = maybe_credit_and_bypass_hold(&pool, &refreshed, false, None)
            .await
            .unwrap();
        assert_eq!(
            bypass,
            Some(None),
            "the underlying build/test check passed — the hold must be bypassed, not left to \
             requeue forever"
        );

        let after = cards::get_card(&pool, &original.id).await.unwrap().unwrap();
        let note = after.metadata_json["credit_receipt"]["note"]
            .as_str()
            .expect("a credit_receipt note must explain the bypass")
            .to_string();
        assert!(note.contains("detected build/test command"), "note: {note}");
    }

    /// Create a goal card in a specific state for testing.
    async fn setup_goal_in_state(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        state_binding: &str,
        attempt_count: u64,
    ) -> cards::Card {
        use crate::projects::PERSONAL_PROJECT_ID;

        // Ensure goal columns exist
        cards::seed_goal_columns(pool, PERSONAL_PROJECT_ID)
            .await
            .unwrap();

        let col = cards::get_goal_column(pool, PERSONAL_PROJECT_ID, state_binding)
            .await
            .unwrap()
            .unwrap();

        let mut meta = serde_json::Map::new();
        meta.insert(
            "attempt_count".to_string(),
            serde_json::json!(attempt_count),
        );
        meta.insert(
            "goal_state".to_string(),
            serde_json::Value::String(state_binding.to_string()),
        );

        cards::create_card(
            pool,
            cards::CreateCard {
                project_id: PERSONAL_PROJECT_ID.to_string(),
                title: format!("Test goal in {}", state_binding),
                description: Some("test".to_string()),
                card_type: Some("goal".to_string()),
                column_id: Some(col.id.clone()),
                created_by: None,
                metadata_json: Some(serde_json::Value::Object(meta)),
            },
        )
        .await
        .unwrap()
    }

    async fn append_tool_message(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        session_id: &str,
        role: &str,
        content: crate::conversation::message::MessageContent,
    ) {
        let content_json = serde_json::to_string(&vec![content]).unwrap();
        sqlx::query(
            "INSERT INTO messages (message_id, session_id, role, content_json, created_timestamp) \
             VALUES (?, ?, ?, ?, ?)",
        )
        .bind(uuid::Uuid::new_v4().to_string())
        .bind(session_id)
        .bind(role)
        .bind(content_json)
        .bind(chrono::Utc::now().timestamp())
        .execute(pool)
        .await
        .unwrap();
    }

    async fn stamp_verify_exchange(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        card_id: &str,
        successful: bool,
    ) {
        use crate::conversation::message::MessageContent;
        use rmcp::model::{CallToolRequestParams, CallToolResult, Content};

        let session_id = format!("verify-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, '/tmp')")
            .bind(&session_id)
            .execute(pool)
            .await
            .unwrap();
        stamp_worker_session(pool, card_id, &session_id).await;
        let call_id = format!("call-{}", uuid::Uuid::new_v4());
        append_tool_message(
            pool,
            &session_id,
            "assistant",
            MessageContent::tool_request(
                &call_id,
                Ok(CallToolRequestParams::new("developer__verify")),
            ),
        )
        .await;
        let mut result = if successful {
            CallToolResult::success(vec![Content::text("all checks passed")])
        } else {
            CallToolResult::error(vec![Content::text("checks failed")])
        };
        result.structured_content = Some(serde_json::json!({
            "kind": crate::agents::platform_extensions::developer::verify::VERIFICATION_OBSERVATION_KIND,
            "command": "test",
            "verdict": if successful { "pass" } else { "fail" },
            "evidence": if successful { "all checks passed" } else { "checks failed" },
        }));
        append_tool_message(
            pool,
            &session_id,
            "user",
            MessageContent::tool_response(&call_id, Ok(result)),
        )
        .await;
    }

    async fn stamp_successful_verify(pool: &sqlx::Pool<sqlx::Sqlite>, card_id: &str) {
        stamp_verify_exchange(pool, card_id, true).await;
    }

    /// G5 finding 1: a worker session whose verify tool returned an
    /// authoritative PASS that is nonetheless vacuous (here: a real command
    /// that reported zero tests) — the case `is_authoritative_pass` alone
    /// used to let through both `maybe_hold_review` and
    /// `auto_land_headless_goal`.
    async fn stamp_vacuous_verify_exchange(pool: &sqlx::Pool<sqlx::Sqlite>, card_id: &str) {
        use crate::conversation::message::MessageContent;
        use rmcp::model::{CallToolRequestParams, CallToolResult, Content};

        let session_id = format!("verify-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, '/tmp')")
            .bind(&session_id)
            .execute(pool)
            .await
            .unwrap();
        stamp_worker_session(pool, card_id, &session_id).await;
        let call_id = format!("call-{}", uuid::Uuid::new_v4());
        append_tool_message(
            pool,
            &session_id,
            "assistant",
            MessageContent::tool_request(
                &call_id,
                Ok(CallToolRequestParams::new("developer__verify")),
            ),
        )
        .await;
        let mut result = CallToolResult::success(vec![Content::text(
            "test result: ok. 0 passed; 0 failed; 0 ignored",
        )]);
        result.structured_content = Some(serde_json::json!({
            "kind": crate::agents::platform_extensions::developer::verify::VERIFICATION_OBSERVATION_KIND,
            "command": "test",
            "verdict": "pass",
            "evidence": "test result: ok. 0 passed; 0 failed; 0 ignored",
            "vacuous_reason": "the command reported zero tests run",
        }));
        append_tool_message(
            pool,
            &session_id,
            "user",
            MessageContent::tool_response(&call_id, Ok(result)),
        )
        .await;
    }

    fn vacuous_verify_exchange() -> Vec<crate::conversation::message::MessageContent> {
        use crate::conversation::message::MessageContent;
        use rmcp::model::{CallToolRequestParams, CallToolResult, Content};

        let mut result = CallToolResult::success(vec![Content::text(
            "test result: ok. 0 passed; 0 failed; 0 ignored",
        )]);
        result.structured_content = Some(serde_json::json!({
            "kind": crate::agents::platform_extensions::developer::verify::VERIFICATION_OBSERVATION_KIND,
            "command": "test",
            "verdict": "pass",
            "evidence": "test result: ok. 0 passed; 0 failed; 0 ignored",
            "vacuous_reason": "the command reported zero tests run",
        }));
        vec![
            MessageContent::tool_request(
                "verify-call",
                Ok(CallToolRequestParams::new("developer__verify")),
            ),
            MessageContent::tool_response("verify-call", Ok(result)),
        ]
    }

    fn verify_exchange(successful: bool) -> Vec<crate::conversation::message::MessageContent> {
        use crate::conversation::message::MessageContent;
        use rmcp::model::{CallToolRequestParams, CallToolResult, Content};

        let mut result = if successful {
            CallToolResult::success(vec![Content::text("all checks passed")])
        } else {
            CallToolResult::error(vec![Content::text("checks failed")])
        };
        result.structured_content = Some(serde_json::json!({
            "kind": crate::agents::platform_extensions::developer::verify::VERIFICATION_OBSERVATION_KIND,
            "command": "test",
            "verdict": if successful { "pass" } else { "fail" },
            "evidence": if successful { "all checks passed" } else { "checks failed" },
        }));
        vec![
            MessageContent::tool_request(
                "verify-call",
                Ok(CallToolRequestParams::new("developer__verify")),
            ),
            MessageContent::tool_response("verify-call", Ok(result)),
        ]
    }

