    /// Only an empty baseline range holds verified work; tracked edits are
    /// informational and untracked build artifacts are ignored.
    #[tokio::test]
    async fn hold_verified_goal_until_work_is_committed_uncommitted_status_is_informational() {
        fn git(repo: &std::path::Path, args: &[&str]) -> String {
            let output = std::process::Command::new("git")
                .arg("-C")
                .arg(repo)
                .args(["-c", "commit.gpgsign=false"])
                .args(args)
                .env("GIT_AUTHOR_NAME", "Test")
                .env("GIT_AUTHOR_EMAIL", "test@example.com")
                .env("GIT_COMMITTER_NAME", "Test")
                .env("GIT_COMMITTER_EMAIL", "test@example.com")
                .output()
                .unwrap();
            assert!(output.status.success(), "{args:?}: {output:?}");
            String::from_utf8(output.stdout).unwrap().trim().to_string()
        }

        for (committed, dirty) in [(false, true), (true, false), (true, true), (false, false)] {
            let tmp = tempfile::tempdir().unwrap();
            git(tmp.path(), &["init", "-q", "-b", "goal/test"]);
            std::fs::write(tmp.path().join("tracked.txt"), "baseline\n").unwrap();
            git(tmp.path(), &["add", "tracked.txt"]);
            git(tmp.path(), &["commit", "-qm", "baseline"]);
            let baseline = git(tmp.path(), &["rev-parse", "HEAD"]);
            if committed {
                std::fs::write(tmp.path().join("work.txt"), "verified work\n").unwrap();
                git(tmp.path(), &["add", "work.txt"]);
                git(tmp.path(), &["commit", "-qm", "work"]);
            }
            if dirty {
                std::fs::write(tmp.path().join("tracked.txt"), "verified edits\n").unwrap();
            }
            for dir in ["target", "__pycache__"] {
                std::fs::create_dir(tmp.path().join(dir)).unwrap();
                std::fs::write(tmp.path().join(dir).join("artifact"), "cache\n").unwrap();
            }
            let pool = test_pool().await;
            let card = setup_goal_in_state(&pool, "in_progress", 1).await;
            stamp_successful_verify(&pool, &card.id).await;
            persist_card_meta(&pool, &card.id, |meta| {
                meta.insert("baseline_commit".into(), serde_json::json!(baseline));
                meta.insert(
                    "dispatch_evidence".into(),
                    serde_json::json!({"worktree_path": tmp.path().to_str().unwrap()}),
                );
            })
            .await
            .unwrap();
            let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
            let held = maybe_hold_review(&pool, &card, false, None).await.unwrap();
            if committed {
                assert!(held.is_none());
            } else {
                let plan = held.unwrap();
                assert!(plan.contains(
                    "verified but uncommitted: commit your work on the goal branch, then declare done"
                ));
                assert_eq!(plan.contains("tracked.txt"), dirty);
                assert!(!plan.contains("artifact"));
                let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
                assert_eq!(updated.metadata_json["hold_done"]["count"], 1);
                assert_eq!(updated.metadata_json["goal_state"], "ready");
            }
        }
    }

    #[tokio::test]
    async fn hold_inspection_error_once_then_park_with_unblock() {
        let pool = test_pool().await;
        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        stamp_successful_verify(&pool, &card.id).await;
        let tmp = tempfile::tempdir().unwrap();
        // Inject a missing worktree so the real git inspection returns an error.
        let missing = tmp.path().join("missing-worktree");
        persist_card_meta(&pool, &card.id, |meta| {
            meta.insert("baseline_commit".into(), serde_json::json!("HEAD"));
            meta.insert(
                "dispatch_evidence".into(),
                serde_json::json!({"worktree_path": missing.to_str().unwrap()}),
            );
        })
        .await
        .unwrap();
        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();
        let held = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(held.metadata_json["hold_done"]["count"], 1);
        assert_eq!(held.metadata_json["goal_state"], "ready");
        let plan = held.metadata_json["hold_done"]["last_plan"]
            .as_str()
            .unwrap();
        assert!(plan.contains("could not inspect the goal worktree:"));
        assert!(plan.contains("missing-worktree"));
        assert!(plan.ends_with("; commit and declare done again"));
        assert_eq!(held.metadata_json["last_error"], plan);
        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
                .await
                .unwrap()
                .is_none()
        );

        force_goal_in_progress(&pool, &card.id).await;
        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();
        let parked = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(parked.metadata_json["goal_state"], "failed");
        assert_eq!(parked.metadata_json["needs_human_attention"], true);
        let unblock = decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
            .await
            .unwrap()
            .unwrap();
        assert!(unblock.detail.contains(plan));
    }

