    /// Y16a: shared Hold-pin setup — a 400s cap, `remaining_secs` left, a
    /// `last_attempt_secs`-long last attempt.
    async fn setup_hold_with_wall_budget(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        remaining_secs: i64,
        last_attempt_secs: i64,
    ) -> cards::Card {
        let card = setup_goal_in_state(pool, "in_progress", 1).await;
        let now = chrono::Utc::now();
        sqlx::query(
            "UPDATE cards SET metadata_json = json_set(metadata_json, '$.budget', \
             json('{\"wallclock_cap_secs\": 400}')) WHERE id = ?",
        )
        .bind(&card.id)
        .execute(pool)
        .await
        .unwrap();
        cards::merge_card_metadata(
            pool,
            &card.id,
            serde_json::json!({
                "first_dispatched_at":
                    (now - chrono::Duration::seconds(400 - remaining_secs)).to_rfc3339(),
                "dispatched_at": (now - chrono::Duration::seconds(last_attempt_secs)).to_rfc3339(),
            }),
            false,
        )
        .await
        .unwrap();
        card
    }

    /// Y16a pin: Hold-arm requeue gated on remaining wall budget — ample
    /// (200s/100s) requeues unchanged, too small (60s/100s, M16 zai
    /// fx04/05/08's shape) parks with an honest unblock instead.
    #[tokio::test]
    async fn hold_gates_requeue_on_remaining_wall_budget() {
        let pool = test_pool().await;

        let ample = setup_hold_with_wall_budget(&pool, 200, 100).await;
        handle_goal_completion(&pool, &ample.id, &ample.project_id, Ok(()), false)
            .await
            .unwrap();
        let held = cards::get_card(&pool, &ample.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &held.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("ready"),
            "ample wall budget on a Hold must still requeue, unchanged"
        );
        assert_eq!(
            held.metadata_json[crate::cost_router::HOLD_METADATA_KEY]["count"],
            1
        );

        let tight = setup_hold_with_wall_budget(&pool, 60, 100).await;
        handle_goal_completion(&pool, &tight.id, &tight.project_id, Ok(()), false)
            .await
            .unwrap();
        let parked = cards::get_card(&pool, &tight.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &parked.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "an exhausted wall budget on a Hold must park, never requeue"
        );
        assert!(
            parked
                .metadata_json
                .get(crate::cost_router::HOLD_METADATA_KEY)
                .is_none(),
            "the ordinary Hold receipt must never be written once budget refuses the requeue"
        );
        let receipt = parked
            .metadata_json
            .get("wall_budget_exhausted")
            .expect("the honest wall_budget_exhausted receipt must be recorded on the card");
        assert!(receipt
            .get("reason")
            .and_then(|v| v.as_str())
            .unwrap()
            .contains("wall budget exhausted"));
        let unblock = decisions::find_open_decision_for_goal(&pool, &tight.id, "unblock")
            .await
            .unwrap()
            .expect("wall-budget exhaustion on a Hold must raise an unblock decision");
        assert_eq!(
            unblock.payload.get("reason").and_then(|v| v.as_str()),
            Some("wallclock_cap")
        );
    }

    // ── Lane R20b: salvage committed goal work before a budget/wall park ────

    fn r20b_git(root: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .expect("git must be on PATH for this test");
        assert!(
            out.status.success(),
            "git {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// A goal worktree shaped like `editapply` (A20 Q1, Mechanism A): a base
    /// commit on `main`, then a `goal/<run_id>` branch — checked out and left
    /// checked out, mirroring a real goal worktree — with ONE further commit
    /// carrying a genuine, passing Rust test (so `developer::verify`'s Auto
    /// scope, via Lane Y11's fork-point widening for an otherwise-clean
    /// working tree, finds real work to verify — not a vacuous pass).
    /// Returns `(worktree dir, baseline sha, head sha)`.
    fn r20b_worktree_with_committed_fix(run_id: &str) -> (tempfile::TempDir, String, String) {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        r20b_git(root, &["init", "-q", "-b", "main"]);
        r20b_git(root, &["config", "user.email", "test@example.com"]);
        r20b_git(root, &["config", "user.name", "Test"]);
        r20b_git(root, &["config", "commit.gpgsign", "false"]);
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"r20b-fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/lib.rs"),
            "pub fn add(a: i32, b: i32) -> i32 { a + b }\n",
        )
        .unwrap();
        r20b_git(root, &["add", "-A"]);
        r20b_git(root, &["commit", "-q", "-m", "base"]);
        let baseline = r20b_git(root, &["rev-parse", "HEAD"]);

        let branch = format!("goal/{run_id}");
        r20b_git(root, &["checkout", "-q", "-b", &branch]);
        std::fs::write(
            root.join("src/lib.rs"),
            "pub fn add(a: i32, b: i32) -> i32 { a + b }\n\n#[test]\nfn it_adds() { assert_eq!(add(2, 2), 4); }\n",
        )
        .unwrap();
        r20b_git(root, &["commit", "-q", "-am", "fix: the salvageable work"]);
        let head = r20b_git(root, &["rev-parse", "HEAD"]);
        (dir, baseline, head)
    }

    /// A goal card `in_progress` with `dispatch_evidence.{baseline_commit,
    /// worktree_path}` pointing at [`r20b_worktree_with_committed_fix`] and a
    /// wall budget shaped by `remaining_secs`/`last_attempt_secs` (same
    /// convention as `setup_hold_with_wall_budget`; pass `None` for no
    /// configured cap at all).
    async fn r20b_setup_goal_with_committed_work(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        run_id: &str,
        budget: Option<(i64, i64)>,
    ) -> (cards::Card, tempfile::TempDir, String) {
        let (dir, _baseline, head) = r20b_worktree_with_committed_fix(run_id);
        let card = setup_goal_in_state(pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            pool,
            &card.id,
            serde_json::json!({
                "worktree_path": dir.path().to_string_lossy(),
                "head_commit": head,
                // M21 gate fix: deliberately EMPTY, not the real commit —
                // `maybe_credit_and_bypass_hold`'s Z2-1 bypass (`ev.commits.
                // is_empty()`) is an UNRELATED pre-existing mechanism that
                // fires before `maybe_hold_review` ever reaches the Y16a
                // wall-budget/salvage check, and this fixture's real,
                // passing Rust project satisfied its own underlying-check
                // condition — silently routing every r20b test straight to
                // Review without ever calling `maybe_salvage_committed_work`
                // at all. Salvage's own eligibility check
                // (`commits_ahead_of_baseline`) reads real git history, not
                // this cosmetic field, so it is unaffected.
                "commits": [],
                "baseline_commit": _baseline,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        let session_id = format!("r20b-worker-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, ?)")
            .bind(&session_id)
            .bind(dir.path().to_string_lossy().as_ref())
            .execute(pool)
            .await
            .unwrap();
        persist_card_meta(pool, &card.id, |m| {
            m.insert(
                "worker_session_id".to_string(),
                serde_json::json!(session_id),
            );
        })
        .await
        .unwrap();
        if let Some((remaining_secs, last_attempt_secs)) = budget {
            let now = chrono::Utc::now();
            sqlx::query(
                "UPDATE cards SET metadata_json = json_set(metadata_json, '$.budget', \
                 json('{\"wallclock_cap_secs\": 400}')) WHERE id = ?",
            )
            .bind(&card.id)
            .execute(pool)
            .await
            .unwrap();
            cards::merge_card_metadata(
                pool,
                &card.id,
                serde_json::json!({
                    "first_dispatched_at":
                        (now - chrono::Duration::seconds(400 - remaining_secs)).to_rfc3339(),
                    "dispatched_at":
                        (now - chrono::Duration::seconds(last_attempt_secs)).to_rfc3339(),
                }),
                false,
            )
            .await
            .unwrap();
        }
        let card = cards::get_card(pool, &card.id).await.unwrap().unwrap();
        (card, dir, head)
    }

    /// Lane R22c (A23/M24 evidence): the exact shape of the DeepSeek
    /// `editapply` misses — a 3rd dispatch whose session made zero further
    /// changes (`"commits":[],"files_changed":0` in the real records; here,
    /// a `goal/<run_id>` branch checked out but never advanced past the
    /// base commit). `baseline == head`, so `commits_ahead_of_baseline`
    /// reads 0 — the "nothing to salvage" case `maybe_salvage_committed_
    /// work` must still audit, not silently swallow.
    fn r20b_worktree_with_no_commits_past_baseline(run_id: &str) -> (tempfile::TempDir, String) {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        r20b_git(root, &["init", "-q", "-b", "main"]);
        r20b_git(root, &["config", "user.email", "test@example.com"]);
        r20b_git(root, &["config", "user.name", "Test"]);
        r20b_git(root, &["config", "commit.gpgsign", "false"]);
        std::fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"r20b-fixture\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
        )
        .unwrap();
        std::fs::create_dir_all(root.join("src")).unwrap();
        std::fs::write(
            root.join("src/lib.rs"),
            "pub fn add(a: i32, b: i32) -> i32 { a + b }\n",
        )
        .unwrap();
        r20b_git(root, &["add", "-A"]);
        r20b_git(root, &["commit", "-q", "-m", "base"]);
        let baseline = r20b_git(root, &["rev-parse", "HEAD"]);
        let branch = format!("goal/{run_id}");
        r20b_git(root, &["checkout", "-q", "-b", &branch]);
        (dir, baseline)
    }

    /// Lane R22c: same shape as [`r20b_setup_goal_with_committed_work`], but
    /// the worker's branch never advanced past the dispatch baseline —
    /// `commits_ahead_of_baseline` reads 0, so salvage must skip (not
    /// crash, not silently return) and still leave an audit trail.
    async fn r20b_setup_goal_with_no_commits(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        run_id: &str,
    ) -> (cards::Card, tempfile::TempDir) {
        let (dir, baseline) = r20b_worktree_with_no_commits_past_baseline(run_id);
        let card = setup_goal_in_state(pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            pool,
            &card.id,
            serde_json::json!({
                "worktree_path": dir.path().to_string_lossy(),
                "head_commit": baseline,
                "commits": [],
                "baseline_commit": baseline,
                "files_changed": 0,
                "insertions": 0,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        let session_id = format!("r20b-worker-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, ?)")
            .bind(&session_id)
            .bind(dir.path().to_string_lossy().as_ref())
            .execute(pool)
            .await
            .unwrap();
        persist_card_meta(pool, &card.id, |m| {
            m.insert(
                "worker_session_id".to_string(),
                serde_json::json!(session_id),
            );
        })
        .await
        .unwrap();
        let card = cards::get_card(pool, &card.id).await.unwrap().unwrap();
        (card, dir)
    }

    /// Lane R22c: the `decision_audit` rows written for a goal by
    /// [`record_salvage_receipt`]/[`record_salvage_audit`], in `seq` order —
    /// scoped to `acted_by = ACTOR_SALVAGE_POLICY` so this never picks up an
    /// unrelated row (e.g. `headless_unblock_refused`, `park`) from the same
    /// goal.
    async fn salvage_audit_outcomes(pool: &sqlx::Pool<sqlx::Sqlite>, goal_id: &str) -> Vec<String> {
        sqlx::query_scalar(
            "SELECT outcome FROM decision_audit WHERE goal_id = ? AND acted_by = ? ORDER BY seq ASC",
        )
        .bind(goal_id)
        .bind(decisions::ACTOR_SALVAGE_POLICY)
        .fetch_all(pool)
        .await
        .unwrap()
    }

    /// A20 Q1 Mechanism A (`editapply`): a goal held with too little wall
    /// budget for another attempt, but its branch already carries a real,
    /// committed, verifiable fix — must be salvaged (verified, reviewed, and
    /// — subject to `PERMAGENT_HEADLESS_AUTOLAND`, off by default here —
    /// moved to Review/landed) instead of stranded behind an unblock nobody
    /// answers. UNVERIFIED beyond desk-checking: depends on
    /// `developer::verify`'s real Rust/`cargo test` detection, which this
    /// EDIT-ONLY lane cannot compile or run.
    #[tokio::test]
    async fn salvage_lands_a_committed_goal_on_a_wall_budget_park() {
        let pool = test_pool().await;
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-salvage-lands", Some((60, 100))).await;

        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "a salvaged goal must never be left in_progress"
        );
        assert_ne!(
            col.state_binding.as_deref(),
            Some("failed"),
            "a salvaged goal must not be parked — its committed work was proven, not stranded"
        );
        let receipt = updated
            .metadata_json
            .get("salvaged_on_park")
            .expect("a landed salvage must record the salvaged_on_park receipt");
        assert_eq!(
            receipt.get("commits_ahead").and_then(|v| v.as_u64()),
            Some(1)
        );

        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
                .await
                .unwrap()
                .is_none(),
            "a salvaged goal must never also raise an unblock decision"
        );

        let session_id = updated
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .unwrap()
            .to_string();
        assert!(
            session_had_successful_verify(&pool, Some(&session_id)).await,
            "the synthetic verify evidence must be genuine, readable by the SAME predicate a \
             live worker's own verify call would satisfy"
        );
    }

    /// G27 HIGH-1 belt-and-braces: `maybe_salvage_committed_work` must
    /// refuse to verify/land ANY commit range that has not passed the
    /// credential/secret scan — independent of whatever committed it (a
    /// worker's own commit, or R28a-b's now-scanned teardown checkpoint;
    /// this fixture models a commit that reached the branch some other way,
    /// fully committed so the earlier uncommitted-work guard cannot mask
    /// it). Commits a secret-shaped `.env` file (the same shape
    /// `goal_engine::scan_committed_changes_blocks_secrets_and_passes_clean`
    /// uses) on top of an otherwise-clean, already-passing fix.
    #[tokio::test]
    async fn salvage_refuses_a_committed_secret() {
        let pool = test_pool().await;
        let (dir, baseline, _head) = r20b_worktree_with_committed_fix("r28ab-salvage-secret");
        std::fs::write(dir.path().join(".env"), "API_KEY=Sup3rS3cretValue123\n").unwrap();
        r20b_git(dir.path(), &["add", "-A"]);
        r20b_git(dir.path(), &["commit", "-q", "-m", "oops secret"]);
        let head = r20b_git(dir.path(), &["rev-parse", "HEAD"]);

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": dir.path().to_string_lossy(),
                "head_commit": head,
                "commits": [],
                "baseline_commit": baseline,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        let session_id = format!("r28ab-worker-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, ?)")
            .bind(&session_id)
            .bind(dir.path().to_string_lossy().as_ref())
            .execute(&pool)
            .await
            .unwrap();
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                "worker_session_id".to_string(),
                serde_json::json!(session_id),
            );
        })
        .await
        .unwrap();

        handle_goal_timeout(&pool, &card.id, &card.project_id, 0, None, None)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert!(
            updated.metadata_json.get("salvaged_on_park").is_none(),
            "a committed secret must never be salvaged/landed"
        );
        let receipt = updated
            .metadata_json
            .get("salvage_receipt")
            .expect("a refused salvage must still leave a breadcrumb");
        assert_eq!(
            receipt.get("outcome").and_then(|v| v.as_str()),
            Some("salvage_skipped_secret_scan")
        );
        let note = receipt
            .get("note")
            .and_then(|v| v.as_str())
            .unwrap_or_default();
        assert!(
            note.contains(".env"),
            "the refusal note must name the flagged file: {note}"
        );
    }

    /// A committed fix exists, but the goal's wall budget is fully spent
    /// (`remaining_wall_budget_secs` reads `Some(0)`) — salvage must skip
    /// the verify attempt entirely rather than spend the last sliver of
    /// budget on a doomed run, and the goal parks exactly as it would have
    /// before this lane.
    #[tokio::test]
    async fn salvage_skipped_with_no_budget() {
        let pool = test_pool().await;
        // cap=400s, elapsed=400s → 0s remaining.
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-salvage-no-budget", Some((0, 100)))
                .await;

        // M21 gate fix: drives `handle_goal_timeout`, not
        // `handle_goal_completion`'s Ok(()) → `maybe_hold_review` Hold arm.
        // That Hold arm pre-gates salvage on `wall_budget_exhausted_refusal`,
        // which by DESIGN returns `None` (not just "not tight enough to
        // refuse", but also) for a FULLY exhausted budget — assuming
        // `check_budget`'s own Wallclock arm already owns that case
        // elsewhere. Nothing calls `check_budget` on the success path, so a
        // fully-exhausted goal reaching that Hold arm never even calls
        // `maybe_salvage_committed_work` at all: `WallBudgetCeiling::
        // Remaining(0)` can never be observed from that call site.
        // `handle_goal_timeout` is the one salvage call site with NO such
        // pre-gate — it always attempts salvage before its own
        // `exhaust_and_park` — so it is the only one of the three that can
        // actually exercise this skip path end to end.
        handle_goal_timeout(&pool, &card.id, &card.project_id, 0, None, None)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "no wall budget left must still park the goal, exactly as before this lane"
        );
        let receipt = updated
            .metadata_json
            .get("salvage_receipt")
            .expect("a skipped salvage must still leave a breadcrumb");
        assert_eq!(
            receipt.get("outcome").and_then(|v| v.as_str()),
            Some("salvage_skipped_no_budget")
        );
        assert!(
            updated.metadata_json.get("salvaged_on_park").is_none(),
            "a skipped salvage must never claim the goal was landed"
        );
    }

    /// A20 Q1 Mechanism B (`loc-refund`/`refactor-shipping`): the drain's own
    /// cap-expiry loop AND `park_dispatched_goals_now`'s shutdown-signal
    /// sweep both funnel through `handle_goal_timeout` — a committed fix
    /// must be salvaged there too, not just on the Y16a Hold-arm path.
    #[tokio::test]
    async fn drain_shutdown_salvages_a_committed_goal() {
        let pool = test_pool().await;
        // No `budget` configured at all: `remaining_wall_budget_secs` reads
        // `None` (no configured ceiling — never "zero budget"), so salvage
        // gets the plain 90s time box.
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-drain-shutdown", None).await;

        // `None`: ample grace (or none of this drain's business — the
        // ordinary cap-expiry loop never races a SIGTERM clock at all).
        handle_goal_timeout(&pool, &card.id, &card.project_id, 0, None, None)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "a salvaged goal must never be left in_progress"
        );
        assert_ne!(
            col.state_binding.as_deref(),
            Some("failed"),
            "handle_goal_timeout (the drain cap AND the shutdown-signal sweep) must salvage \
             committed work instead of stranding it behind a park"
        );
        assert!(updated.metadata_json.get("salvaged_on_park").is_some());
    }

    /// G25 HIGH-2: the shutdown-signal sweep's grace clock. Under 10s of
    /// assumed SIGTERM grace remaining, salvage must skip entirely rather
    /// than start a verify run it cannot finish before SIGKILL.
    #[tokio::test]
    async fn drain_shutdown_salvage_skips_with_insufficient_grace() {
        let pool = test_pool().await;
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-drain-no-grace", None).await;

        let almost_out_of_grace =
            Some(std::time::Instant::now() + std::time::Duration::from_secs(3));
        let outcome = maybe_salvage_committed_work(&pool, &card, almost_out_of_grace, None).await;
        assert!(matches!(outcome, SalvageOutcome::NotSalvaged { .. }));

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let receipt = updated
            .metadata_json
            .get("salvage_receipt")
            .expect("an insufficient-grace skip must still leave a breadcrumb");
        assert_eq!(
            receipt.get("outcome").and_then(|v| v.as_str()),
            Some("salvage_skipped_no_grace")
        );
        assert!(updated.metadata_json.get("salvaged_on_park").is_none());
    }

    /// G25 MED: at most one salvage attempt per goal, ever.
    #[tokio::test]
    async fn salvage_refuses_a_second_attempt_for_the_same_goal() {
        let pool = test_pool().await;
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-salvage-once", None).await;
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                SALVAGE_ATTEMPTED_METADATA_KEY.to_string(),
                serde_json::json!(1),
            );
        })
        .await
        .unwrap();
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        let outcome = maybe_salvage_committed_work(&pool, &card, None, None).await;
        match outcome {
            SalvageOutcome::NotSalvaged { note } => {
                assert!(note.contains("already attempted"));
            }
            SalvageOutcome::Salvaged { .. } => panic!("a spent salvage attempt must not re-fire"),
        }
        // Confirms the guard refuses BEFORE doing any git/verify work: no
        // `salvage_receipt`/`salvaged_on_park` write of any kind.
        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert!(updated.metadata_json.get("salvage_receipt").is_none());
        assert!(updated.metadata_json.get("salvaged_on_park").is_none());
    }

    // ── Lane R20b-d (A21 Q1): salvage on the hold-exhaustion Park ───────────
    //
    // Every sub-test here pre-spends R18g's own `headless_unblock_count`
    // (gate 2 of `maybe_headless_unblock_verify_gap`) so its outcome is
    // deterministic regardless of whether some OTHER test already set the
    // process-global `HEADLESS_DISPATCH_POLICY_CONFIG` `OnceLock` (it can
    // only ever be set once per test binary, and Rust runs `#[tokio::test]`s
    // in parallel by default) — R18g refuses on that gate either way, so
    // these tests observe the salvage-vs-park ordering, not R18g's own
    // eligibility math (already covered by the pre-existing R18g test
    // suite above).

    /// A20/A21's headline case: `pricing.py` (`3121ffe`) was a genuinely
    /// correct, committed fix discarded because its literal AC never passed
    /// and R18g's own one-shot budget was already spent — must now be
    /// salvaged instead of parked unread.
    #[tokio::test]
    async fn hold_exhaustion_park_salvages_committed_work() {
        let pool = test_pool().await;
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r20b-hold-salvage", None).await;
        persist_card_meta(&pool, &card.id, |m| {
            crate::cost_router::HoldState {
                count: crate::cost_router::MAX_HOLDS,
                last_plan: None,
            }
            .write_into(m);
            m.insert(
                HEADLESS_UNBLOCK_METADATA_KEY.to_string(),
                serde_json::json!(1),
            );
        })
        .await
        .unwrap();

        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "a salvaged goal must never be left in_progress"
        );
        assert_ne!(
            col.state_binding.as_deref(),
            Some("failed"),
            "a hold-exhaustion park with committed work must salvage it, not strand it \
             unread behind an unblock"
        );
        let receipt = updated
            .metadata_json
            .get("salvaged_on_park")
            .expect("the hold-exhaustion Park arm must attempt salvage before parking");
        assert_eq!(
            receipt.get("commits_ahead").and_then(|v| v.as_u64()),
            Some(1)
        );
        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
                .await
                .unwrap()
                .is_none(),
            "a salvaged goal must never also raise an unblock decision"
        );
    }

    // Lane R20b-e (M21/M24 gate fix): `hold_exhaustion_park_prefers_r18g_
    // unblock_when_eligible` used to live here, testing that R18g's headless
    // unblock (tried BEFORE salvage in `maybe_hold_review`'s `HoldOutcome::
    // Park` arm) wins over salvage when eligible. REMOVED: it drove that by
    // calling `HEADLESS_DISPATCH_POLICY_CONFIG.set(...)` — a process-global
    // `OnceLock` that can only ever be set once for the life of a test
    // binary. `cargo test` runs `#[tokio::test]`s in parallel within ONE
    // process, so once this test ran, `HEADLESS_DISPATCH_POLICY_CONFIG.
    // get().is_some()` read `true` for every OTHER test still to run in the
    // same binary — including the pre-existing `repeated_premature_done_
    // parks_after_max_holds` earlier in this test module, which assumes headless is OFF. That
    // test's hold-exhausted, nothing-committed goal was silently resumed by
    // R18g instead of parked, so its own `needs_human_attention` assertion
    // read `Null` (the card was never parked at all) — the M24 gate failure
    // this lane fixes.
    //
    // The ordering claim itself needs no integration test: in
    // `maybe_hold_review`'s `HoldOutcome::Park` arm, `maybe_headless_
    // unblock_verify_gap` is called FIRST, with an unconditional `return
    // Ok(Some(resumed))` on success — the salvage call textually below it
    // cannot run once that early return fires, by construction, with no
    // flag or state that could reorder the two at runtime. R18g's OWN
    // success behavior when eligible is covered by the pre-existing, safe
    // R18g test suite above (which injects `headless` as an explicit
    // parameter to `maybe_headless_unblock_verify_gap` directly, never
    // touching the global config); the complementary "R18g not eligible →
    // salvage fires" case is `hold_exhaustion_park_salvages_committed_work`
    // below.

    /// A hold-exhaustion park with nothing committed at all (no dispatch
    /// baseline recorded) has nothing for salvage to find — falls straight
    /// through to the ordinary park, exactly as it did before this lane.
    #[tokio::test]
    async fn hold_exhaustion_park_with_uncommitted_work_parks() {
        let pool = test_pool().await;
        let goal = create_roadmap_goal(
            &pool,
            "in_progress",
            "Nothing committed",
            "r20b-hold-c",
            &[],
        )
        .await;
        persist_card_meta(&pool, &goal.id, |m| {
            crate::cost_router::HoldState {
                count: crate::cost_router::MAX_HOLDS,
                last_plan: None,
            }
            .write_into(m);
            m.insert(
                HEADLESS_UNBLOCK_METADATA_KEY.to_string(),
                serde_json::json!(1),
            );
        })
        .await
        .unwrap();

        handle_goal_completion(&pool, &goal.id, &goal.project_id, Ok(()), false)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &goal.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "nothing committed must still park the goal, exactly as before this lane"
        );
        // M24 gate fix (Lane R20b-e): the specific regression — a hold-
        // exhausted goal with nothing to salvage must still be parked with
        // `needs_human_attention: true`, byte-identical to the pre-R20b-d
        // park contract `repeated_premature_done_parks_after_max_holds`
        // (above) already pins. This assertion is the direct guard for that
        // M24 failure (`needs_human_attention` read `Null`): salvage's
        // `NotSalvaged` outcome must fall all the way through to the SAME
        // `goal_transition::park_goal` call an ordinary hold-exhaustion park
        // always made, never short-circuit around it.
        assert_eq!(
            updated.metadata_json["needs_human_attention"], true,
            "a hold-exhausted goal with nothing to salvage must still be parked for a human"
        );
        assert!(updated.metadata_json.get("salvaged_on_park").is_none());
        let unblock = decisions::find_open_decision_for_goal(&pool, &goal.id, "unblock")
            .await
            .unwrap()
            .expect("an ordinary hold-exhaustion park must still raise an unblock decision");
        assert!(
            unblock.detail.contains("salvage"),
            "the skip note must be folded into the park detail, not discarded: {}",
            unblock.detail
        );
    }

    // ── Lane R22c: salvage on the attempt-cap park, always audited ──────────
    //
    // A23/M24 evidence: a real `editapply`-shaped run showed the exact
    // sequence `transition:dispatch, requeue, transition:dispatch, requeue,
    // transition:dispatch, headless_unblock_refused(attempt_cap_exhausted),
    // created, park` in `decision_audit`, with NO salvage row anywhere in
    // between — even though the card's own metadata showed
    // `maybe_salvage_committed_work` DID run (a `salvage_receipt` or
    // `salvaged_on_park` key was present). Traced to source: the
    // `HoldOutcome::Park` arm of `maybe_hold_review`
    // (`maybe_headless_unblock_verify_gap` then `maybe_salvage_committed_
    // work`, unconditionally, with no early return between them) was never
    // the bug — `record_salvage_receipt`/the final `salvaged_on_park` write
    // only ever touched card metadata, never `decision_audit`. These two
    // tests pin the fix: every salvage outcome at this park site — landed
    // or skipped — now leaves a `decision_audit` row, queried independently
    // of card metadata so a future analysis never has to guess again.

    /// Reproduces the evidence shape as closely as the existing R20b-d test
    /// harness allows: `attempt_count` at `DEFAULT_ATTEMPT_CAP` (3) — the
    /// same dimension the real `check_budget` refusal hit — a hold-exhausted
    /// goal, and a genuinely committed, verifiable fix on the branch. Must
    /// land via salvage (not park) AND leave a `salvaged_on_park`
    /// `decision_audit` row, independent of the card-metadata receipt.
    #[tokio::test]
    async fn hold_exhaustion_park_at_attempt_cap_salvages_and_audits() {
        let pool = test_pool().await;
        let (card, _dir, _head) =
            r20b_setup_goal_with_committed_work(&pool, "r22c-attempt-cap-salvage", None).await;
        persist_card_meta(&pool, &card.id, |m| {
            crate::cost_router::HoldState {
                count: crate::cost_router::MAX_HOLDS,
                last_plan: None,
            }
            .write_into(m);
            // Pre-spend R18g's own once-per-goal gate — same reasoning as
            // every other test in this section: makes `maybe_headless_
            // unblock_verify_gap`'s refusal deterministic regardless of
            // whether some OTHER test already flipped the process-global
            // `HEADLESS_DISPATCH_POLICY_CONFIG` `OnceLock`, without this
            // test mutating that global itself.
            m.insert(
                HEADLESS_UNBLOCK_METADATA_KEY.to_string(),
                serde_json::json!(1),
            );
        })
        .await
        .unwrap();
        // Three dispatches, attempt cap reached — the exact `spent: 3, cap:
        // 3` dimension A23 traced the real refusal to (DEFAULT_ATTEMPT_CAP).
        sqlx::query(
            "UPDATE cards SET metadata_json = json_set(metadata_json, '$.attempt_count', 3) \
             WHERE id = ?",
        )
        .bind(&card.id)
        .execute(&pool)
        .await
        .unwrap();

        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "a salvaged goal must never be left in_progress"
        );
        assert_ne!(
            col.state_binding.as_deref(),
            Some("failed"),
            "committed, verifiable work at attempt-cap exhaustion must be salvaged, not parked"
        );
        assert!(
            updated.metadata_json.get("salvaged_on_park").is_some(),
            "the card-metadata receipt must still be written, exactly as before this lane"
        );

        let outcomes = salvage_audit_outcomes(&pool, &card.id).await;
        assert_eq!(
            outcomes,
            vec!["salvaged_on_park".to_string()],
            "a landed salvage must leave exactly one decision_audit row naming the real outcome, \
             not silence — the pre-fix defect A23/M24 found"
        );
    }

    /// The no-commits variant of the same park: `attempt_count` at the cap,
    /// but the branch never advanced past its dispatch baseline — the exact
    /// shape A23 flagged as needing its own explanation ("why did the worker
    /// not commit"), not a silent swallow. Salvage must skip (never crash,
