    /// (c) The goal branch carries a real, unlanded commit AND the worktree
    /// also has a genuine dirty change sitting on top of it. Per
    /// `decide_goal_hold`'s own stated intent ("Any role after a successful
    /// verify → Allow (goal callers also require committed work)"), the
    /// commit already satisfies the commit-required rule — the extra dirty
    /// file is informational, not a reason to Hold a goal that has real,
    /// reviewable progress (this mirrors the pre-existing `(committed: true,
    /// dirty: true)` case in
    /// `hold_verified_goal_until_work_is_committed_uncommitted_status_is_informational`,
    /// which already asserts Allow for a non-rolling-baseline-reset commit
    /// + dirty combination — this test exercises the SAME combination
    /// through the new trunk-relative path).
    #[tokio::test]
    async fn maybe_hold_review_allows_unlanded_trunk_commit_despite_dirty_worktree_on_top() {
        let pool = test_pool().await;
        let (trunk, goal_dir, _base_sha, fix_sha) =
            r22d_trunk_and_goal_worktree("r42a-allow-dirty");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        // A further, genuinely uncommitted edit on top of the already-
        // committed fix.
        std::fs::write(
            goal_dir.path().join("src/lib.rs"),
            "pub fn add(a: i32, b: i32) -> i32 { a + b }\n\n#[test]\nfn it_adds() { \
             assert_eq!(add(2, 2), 4); }\n\n// stray edit, never committed\n",
        )
        .unwrap();

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                "head_commit": fix_sha,
                "commits": [],
                "baseline_commit": fix_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        stamp_successful_verify(&pool, &card.id).await;

        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let held = maybe_hold_review(&pool, &card, false, None).await.unwrap();
        assert!(
            held.is_none(),
            "a real, unlanded commit at the trunk must still Allow even with a stray dirty \
             edit on top — decide_goal_hold's own intent is committed work, not a spotless \
             worktree: {held:?}"
        );
    }

    // ── Lane R42a-b (G29 HIGH-1): the trunk-relative override requires a ────
    // verified PASS bound to the exact unlanded head, not just "some commit
    // exists somewhere unlanded" — closes the gap G29's review found in
    // R42a's own override (a stale, never-independently-verified checkpoint
    // commit, or ANY unrelated verify pass elsewhere in the session, could
    // credit committed work before this lane).

    /// (b) The one unlanded commit is a genuinely BROKEN checkpoint (R28a's
    /// unconditional teardown checkpoint, reproduced by
    /// `r42ab_trunk_and_goal_worktree_with_failing_commit`). This session's
    /// OWN recorded verify pass is real but bound to a DIFFERENT commit
    /// (`dispatch_evidence.head_commit` set to the base sha, not the
    /// checkpoint) — option (a) cannot fire — so the override must fall to
    /// a fresh, time-boxed verify, which genuinely fails against this
    /// broken checkpoint. Must Hold, naming the unverified checkpoint.
    /// R47 (A44): a pre-R47 record holds a `--short` abbreviation where the
    /// worktree now reports a full sha; the override must still bind. The >= 7
    /// floor keeps a stray short string from matching broadly.
    #[test]
    fn sha_matches_binds_a_short_record_to_a_full_head() {
        let full = "0b8a39d7c1e4f2a6b90d3c5e7f1a2b4c6d8e0f13";
        assert!(sha_matches("0b8a39d", full), "short prefix must bind");
        assert!(sha_matches(full, "0b8a39d"), "order must not matter");
        assert!(sha_matches(full, full), "identical shas bind");
        assert!(
            sha_matches("  0b8a39d\n", full),
            "surrounding whitespace is trimmed"
        );
        assert!(
            !sha_matches("0b8a39e", full),
            "a different sha must not bind"
        );
        assert!(
            !sha_matches("0b8a39", full),
            "fewer than 7 chars must never bind"
        );
        assert!(!sha_matches("", full), "an empty sha must never bind");
    }

    #[tokio::test]
    async fn maybe_hold_review_holds_unlanded_checkpoint_when_fresh_verify_fails() {
        let pool = test_pool().await;
        let (trunk, goal_dir, base_sha, checkpoint_sha) =
            r42ab_trunk_and_goal_worktree_with_failing_commit("r42ab-hold-fresh-fail");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                // Bound to the BASE commit, not the checkpoint that is
                // actually unlanded — this session's verify evidence (below)
                // is real, but never proven to have checked this exact head.
                "head_commit": base_sha,
                "commits": [],
                "baseline_commit": checkpoint_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        stamp_successful_verify(&pool, &card.id).await;

        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let held = maybe_hold_review(&pool, &card, false, None).await.unwrap();
        let plan = held
            .expect("an unlanded checkpoint commit that fails a fresh verify must Hold, not Allow");
        assert!(
            plan.contains("unlanded checkpoint present but unverified"),
            "must name the unverified-checkpoint reason: {plan}"
        );
    }

    /// (c) The one unlanded commit is the SAME genuinely passing fix
    /// `r22d_trunk_and_goal_worktree` builds. This session's own recorded
    /// verify pass is real but — same as (b) — bound to the base commit,
    /// not this fix, so option (a) cannot fire. A fresh, time-boxed verify
    /// run now against the goal worktree genuinely passes. Must Allow, and
    /// must actually have paid for that fresh verify (`FRESH_HOLD_VERIFY_
    /// CALL_COUNT >= 1`) rather than trusting the unrelated recorded pass.
    #[tokio::test]
    async fn maybe_hold_review_allows_unlanded_commit_when_fresh_verify_passes_and_recorded_verify_is_not_bound_to_head(
    ) {
        let pool = test_pool().await;
        let (trunk, goal_dir, base_sha, fix_sha) =
            r22d_trunk_and_goal_worktree("r42ab-allow-fresh-pass");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                // Bound to the BASE commit, not the fix that is actually
                // unlanded — proves the override cannot lean on this
                // session's generic `verify_ran` flag alone.
                "head_commit": base_sha,
                "commits": [],
                "baseline_commit": fix_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        stamp_successful_verify(&pool, &card.id).await;

        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let call_count = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let held = FRESH_HOLD_VERIFY_CALL_COUNT
            .scope(
                call_count.clone(),
                maybe_hold_review(&pool, &card, false, None),
            )
            .await
            .unwrap();
        assert!(
            held.is_none(),
            "a fresh verify pass against the actually-unlanded commit must Allow even though \
             this session's own recorded verify was bound to a different head: {held:?}"
        );
        assert!(
            call_count.load(std::sync::atomic::Ordering::SeqCst) >= 1,
            "the Allow must be earned by an actual fresh verify call, not by trusting the \
             unrelated recorded pass"
        );
    }

    /// (d) The goal's own `salvage_receipt` already recorded a genuine
    /// verify FAILURE (`salvage_verify_failed`) for this branch — salvage
    /// already spent time proving this exact, still-unmoved range broken.
    /// Even with a session verify recorded AT this exact head (the (a)
    /// shape, which would otherwise Allow immediately), the override must
    /// refuse outright and never re-verify: Hold, and the fresh-verify seam
    /// (`FRESH_HOLD_VERIFY_CALL_COUNT`) must stay at 0.
    #[tokio::test]
    async fn maybe_hold_review_holds_without_reverifying_when_salvage_already_recorded_a_failure() {
        let pool = test_pool().await;
        let (trunk, goal_dir, _base_sha, fix_sha) =
            r22d_trunk_and_goal_worktree("r42ab-hold-salvage-already-failed");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                // Matches the CURRENT head, deliberately the same shape as
                // test (a) — proves `salvage_already_failed` refuses the
                // override even when the cheap head-match path would
                // otherwise have fired.
                "head_commit": fix_sha,
                "commits": [],
                "baseline_commit": fix_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        stamp_successful_verify(&pool, &card.id).await;
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                "salvage_receipt".to_string(),
                serde_json::json!({
                    "outcome": "salvage_verify_failed",
                    "note": "salvage already ran a genuine verify against this range and it \
                              failed",
                    "recorded_at": chrono::Utc::now().to_rfc3339(),
                }),
            );
        })
        .await
        .unwrap();

        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let call_count = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let held = FRESH_HOLD_VERIFY_CALL_COUNT
            .scope(
                call_count.clone(),
                maybe_hold_review(&pool, &card, false, None),
            )
            .await
            .unwrap();
        let plan = held.expect(
            "a goal whose salvage_receipt already recorded a verify failure must Hold, never \
             Allow via the override",
        );
        assert!(
            plan.contains("unlanded checkpoint present but unverified"),
            "must name the unverified-checkpoint reason: {plan}"
        );
        assert!(
            plan.contains("salvage already recorded a verify failure"),
            "must name WHY it is not re-verifying: {plan}"
        );
        assert_eq!(
            call_count.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "must never pay for a fresh verify against a range salvage already proved broken"
        );
    }

    /// R42a-c (G30 review, MEDIUM): `run_fresh_verify_for_hold` spawns a
    /// real build/test subprocess against the goal worktree — if a worker
    /// this process itself dispatched is still live and writing to that
    /// exact worktree, the fresh verify races the worker's own edits
    /// instead of confirming a settled head. Same unlanded-commit shape as
    /// test (c) above (a genuinely passing fix), but with a live worker
    /// registered in `GOAL_WORKERS` (Y4b's registry, the same one `goal_
    /// status`'s `session_alive` trusts) for this card: the override must
    /// Hold with "worker still live; verify deferred" WITHOUT spending the
    /// fresh-verify seam. Once that worker's handle is taken — the same
    /// state a genuinely completed dispatch leaves behind — a second call
    /// against the identical unlanded commit must fall through to the
    /// fresh verify and Allow, proving the seam wasn't merely broken.
    // `GOAL_WORKERS` is process-global; serialize against the other tests
    // that touch it (same convention as `goal_status_reports_a_registered_
    // goal_worker_as_alive_and_leaves_it_alone`).
    #[tokio::test]
    #[serial_test::serial(goal_workers)]
    async fn maybe_hold_review_defers_fresh_verify_while_goal_worker_is_live_then_verifies_once_gone(
    ) {
        let pool = test_pool().await;
        let (trunk, goal_dir, base_sha, fix_sha) =
            r22d_trunk_and_goal_worktree("r42ac-defer-while-live");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "in_progress", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                // Bound to the BASE commit, not the fix that is actually
                // unlanded, so neither `recorded_pass_at_head` nor
                // `salvage_already_failed` can explain a Hold here — only
                // the live-worker guard can.
                "head_commit": base_sha,
                "commits": [],
                "baseline_commit": fix_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        stamp_successful_verify(&pool, &card.id).await;
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        register_goal_worker(
            &card.id,
            "r42ac-live-session",
            goal_engine::GoalKill::None,
            None,
        );
        assert!(goal_worker_is_live(&card.id));

        let live_call_count = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let held_while_live = FRESH_HOLD_VERIFY_CALL_COUNT
            .scope(
                live_call_count.clone(),
                maybe_hold_review(&pool, &card, false, None),
            )
            .await
            .unwrap();
        let plan = held_while_live
            .expect("a live worker's worktree must Hold, never Allow via a racing verify");
        assert!(
            plan.contains("worker still live; verify deferred"),
            "must name the deferral reason: {plan}"
        );
        assert_eq!(
            live_call_count.load(std::sync::atomic::Ordering::SeqCst),
            0,
            "must never spawn the fresh verify while the dispatching worker is still live"
        );

        // The worker is gone now (a completed/cancelled dispatch clears its
        // `GOAL_WORKERS` entry the same way) — the identical unlanded commit
        // must now earn its Allow the normal way, by actually paying for a
        // fresh verify.
        take_goal_worker(&card.id);
        assert!(!goal_worker_is_live(&card.id));

        let gone_call_count = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let held_once_gone = FRESH_HOLD_VERIFY_CALL_COUNT
            .scope(
                gone_call_count.clone(),
                maybe_hold_review(&pool, &card, false, None),
            )
            .await
            .unwrap();
        assert!(
            held_once_gone.is_none(),
            "once the worker is gone, a fresh verify pass against the actually-unlanded commit \
             must Allow: {held_once_gone:?}"
        );
        assert!(
            gone_call_count.load(std::sync::atomic::Ordering::SeqCst) >= 1,
            "must actually spend the fresh-verify seam once the worker is no longer live"
        );
    }

    /// A goal with real uncommitted work (never committed at all) has no
    /// dispatch baseline recorded — `maybe_salvage_committed_work` refuses
    /// at its very first check and the goal parks EXACTLY as it did before
    /// this lane (the pre-existing `tight` case in
    /// `hold_gates_requeue_on_remaining_wall_budget`, named explicitly here).
    #[tokio::test]
    async fn uncommitted_only_goal_parks_unchanged() {
        let pool = test_pool().await;
        // No `dispatch_evidence`/`baseline_commit` at all — nothing for
        // salvage to even inspect.
        let card = setup_hold_with_wall_budget(&pool, 60, 100).await;

        handle_goal_completion(&pool, &card.id, &card.project_id, Ok(()), false)
            .await
            .unwrap();

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "a goal with nothing committed must park exactly as it did before this lane"
        );
        assert!(updated.metadata_json.get("salvaged_on_park").is_none());
    }

    /// R18g's `maybe_headless_unblock_verify_gap` had four silent
    /// `return Ok(None)` gates. Each refusal must now write a
    /// `decision_audit` row (`outcome = 'headless_unblock_refused'`) naming
    /// which gate fired.
    #[tokio::test]
    async fn headless_unblock_refusal_gates_write_audit_rows() {
        let pool = test_pool().await;

        async fn refused_gate_names(pool: &sqlx::Pool<sqlx::Sqlite>, goal_id: &str) -> Vec<String> {
            sqlx::query_scalar(
                "SELECT evidence_digest FROM decision_audit WHERE goal_id = ? \
                 AND outcome = 'headless_unblock_refused' ORDER BY seq ASC",
            )
            .bind(goal_id)
            .fetch_all(pool)
            .await
            .unwrap()
        }

        // Gate 1: reason mismatch (never one of the two byte-for-byte
        // literals `decide_goal_hold` raises).
        let jailed = create_roadmap_goal(&pool, "in_progress", "Jailed goal", "r20b-a", &[]).await;
        let card = cards::get_card(&pool, &jailed.id).await.unwrap().unwrap();
        maybe_headless_unblock_verify_gap(
            &pool,
            &card,
            "blocked by the write jail: path escapes the sandbox",
            true,
        )
        .await
        .unwrap();
        let gates = refused_gate_names(&pool, &jailed.id).await;
        assert_eq!(gates.len(), 1);
        assert!(gates[0].starts_with("reason_mismatch:"));

        // Gate 2: once-per-goal already spent.
        let spent = create_roadmap_goal(&pool, "in_progress", "Spent goal", "r20b-b", &[]).await;
        persist_card_meta(&pool, &spent.id, |m| {
            m.insert(
                HEADLESS_UNBLOCK_METADATA_KEY.to_string(),
                serde_json::json!(1),
            );
        })
        .await
        .unwrap();
        let card = cards::get_card(&pool, &spent.id).await.unwrap().unwrap();
        maybe_headless_unblock_verify_gap(
            &pool,
            &card,
            crate::cost_router::hold_done::PARK_REASON_NO_VERIFY,
            true,
        )
        .await
        .unwrap();
        assert_eq!(
            refused_gate_names(&pool, &spent.id).await,
            vec!["once_per_goal_spent".to_string()]
        );

        // Gate 3: wall budget exhausted. `setup_hold_with_wall_budget`
        // returns the card snapshot from BEFORE it writes `budget`/
        // `first_dispatched_at`/`dispatched_at` (it never re-fetches) — the
        // OTHER pre-existing caller of this helper never notices because it
        // hands only `.id`/`.project_id` to `handle_goal_completion`, which
        // re-queries the card itself. This gate function reads
        // `card.metadata_json` directly, so it needs a fresh fetch here —
        // M21 gate fix (the stale snapshot has no configured wall budget at
        // all, so `wall_budget_exhausted_refusal` read `None` and no gate
        // ever refused).
        let tight = setup_hold_with_wall_budget(&pool, 60, 100).await;
        let tight = cards::get_card(&pool, &tight.id).await.unwrap().unwrap();
        maybe_headless_unblock_verify_gap(
            &pool,
            &tight,
            crate::cost_router::hold_done::PARK_REASON_NO_VERIFY,
            true,
        )
        .await
        .unwrap();
        assert_eq!(
            refused_gate_names(&pool, &tight.id).await,
            vec!["wall_budget_exhausted".to_string()]
        );

        // Gate 4: reservation/cost (attempt-cap) budget exhausted.
        let capped = create_roadmap_goal(&pool, "in_progress", "Capped goal", "r20b-d", &[]).await;
        sqlx::query(
            "UPDATE cards SET metadata_json = json_set(metadata_json, '$.budget', \
             json('{\"attempt_cap\": 1}'), '$.attempt_count', 1) WHERE id = ?",
        )
        .bind(&capped.id)
        .execute(&pool)
        .await
        .unwrap();
        let card = cards::get_card(&pool, &capped.id).await.unwrap().unwrap();
        maybe_headless_unblock_verify_gap(
            &pool,
            &card,
            crate::cost_router::hold_done::PARK_REASON_UNCOMMITTED,
            true,
        )
        .await
        .unwrap();
        // Lane R21d: the gate label now names the actual `BudgetExhaustion`
        // variant plus spent/cap, not the generic "cost_budget_exhausted".
        assert_eq!(
            refused_gate_names(&pool, &capped.id).await,
            vec!["attempt_cap_exhausted:spent=1,cap=1".to_string()]
        );
    }

    /// Y16a: a headless goal's first dispatch gets `budget.wallclock_cap_secs`
    /// populated from `PERMAGENT_HEADLESS_DRAIN_SECS` — previously never set
    /// in production, which is why the checks above needed hand-seeded
    /// `budget` rows to exercise at all.
    ///
    /// Y16c (G19 HIGH, documented fallback): no `PERMAGENT_HEADLESS_STARTED_AT`
    /// is set here, so the cap is the raw drain value unmodified — exactly
    /// the pre-Y16c behaviour when the process-start anchor is missing.
    #[tokio::test]
    #[serial_test::serial]
    async fn headless_wallclock_cap_patch_reads_the_drain_env_when_no_cap_is_configured() {
        std::env::remove_var("PERMAGENT_HEADLESS_STARTED_AT");
        std::env::set_var("PERMAGENT_HEADLESS_DRAIN_SECS", "555");
        let patch = headless_wallclock_cap_patch(&serde_json::json!({}));
        std::env::remove_var("PERMAGENT_HEADLESS_DRAIN_SECS");
        assert_eq!(
            patch,
            Some(serde_json::json!({ "wallclock_cap_secs": 555 }))
        );
    }

    /// Y16a: an already-configured per-goal cap (user- or roadmap-authored)
    /// is never overridden by the drain env, and other budget fields on the
    /// same card survive untouched.
    #[tokio::test]
    #[serial_test::serial]
    async fn headless_wallclock_cap_patch_leaves_an_existing_cap_alone() {
        std::env::set_var("PERMAGENT_HEADLESS_DRAIN_SECS", "100");
        let existing = serde_json::json!({
            "budget": { "wallclock_cap_secs": 999, "attempt_cap": 5 }
        });
        let patch = headless_wallclock_cap_patch(&existing);
        std::env::remove_var("PERMAGENT_HEADLESS_DRAIN_SECS");
        assert_eq!(patch, None);
    }

    /// Y16c (G19 HIGH): pure arithmetic — dispatching 200s after process
    /// start with a 440s drain leaves a 240s cap.
    #[test]
    fn wallclock_cap_from_process_start_subtracts_elapsed_time() {
        assert_eq!(headless_wallclock_cap_from_process_start(440, 200), 240);
    }

    /// Y16c: dispatching at t=0 (no time spent yet) leaves the cap equal to
    /// the full raw drain value.
    #[test]
    fn wallclock_cap_from_process_start_at_dispatch_time_zero() {
        assert_eq!(headless_wallclock_cap_from_process_start(440, 0), 440);
    }

    /// Y16c: the cap can never exceed the raw drain value, even under clock
    /// skew that makes elapsed time read as negative.
    #[test]
    fn wallclock_cap_from_process_start_never_exceeds_the_raw_drain() {
        assert_eq!(headless_wallclock_cap_from_process_start(440, -30), 440);
    }

    /// Y16c: fully spent drain floors the cap at 0 rather than underflowing.
    #[test]
    fn wallclock_cap_from_process_start_floors_at_zero() {
        assert_eq!(headless_wallclock_cap_from_process_start(200, 500), 0);
    }

    /// Y16c (G19 HIGH): `headless_wallclock_cap_patch` end to end — a
    /// dispatch 200s after the stamped process start with a 440s drain gets
    /// a 240s cap, not the raw 440s (which could land its deadline after the
    /// eval harness's own SIGKILL — see the function's doc comment).
    #[tokio::test]
    #[serial_test::serial]
    async fn headless_wallclock_cap_patch_anchors_to_process_start_when_the_env_is_set() {
        let started_at = chrono::Utc::now().timestamp() - 200;
        std::env::set_var("PERMAGENT_HEADLESS_DRAIN_SECS", "440");
        std::env::set_var("PERMAGENT_HEADLESS_STARTED_AT", started_at.to_string());
        let patch = headless_wallclock_cap_patch(&serde_json::json!({}));
        std::env::remove_var("PERMAGENT_HEADLESS_DRAIN_SECS");
        std::env::remove_var("PERMAGENT_HEADLESS_STARTED_AT");
        assert_eq!(
            patch,
            Some(serde_json::json!({ "wallclock_cap_secs": 240 }))
        );
    }

    /// Y16c: dispatching right at process start (no time spent yet) gets the
    /// full raw drain value as its cap, even with the anchor env set.
    #[tokio::test]
