    /// Y16c: the rejection marker only refuses the SPECIFIC session it names
    /// — a card whose marker points at some earlier, unrelated session must
    /// still continue from the current prior session's (unrejected) branch.
    #[tokio::test]
    async fn prior_goal_branch_tip_still_continues_when_the_rejection_marker_is_stale() {
        let tmp = tempfile::tempdir().unwrap();
        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);

        let git = |args: &[&str]| {
            let status = std::process::Command::new("git")
                .arg("-C")
                .arg(&repo)
                .args(args)
                .output()
                .unwrap();
            assert!(
                status.status.success(),
                "git {:?} failed: {}",
                args,
                String::from_utf8_lossy(&status.stderr)
            );
        };
        let branch = goal_engine::goal_branch_name("prev-session-id");
        git(&["checkout", "-b", branch.as_str()]);
        std::fs::write(repo.join("work.txt"), "unrejected work").unwrap();
        git(&["add", "."]);
        git(&["commit", "-q", "-m", "unrejected worker's commit"]);

        let metadata = serde_json::json!({
            "worker_session_id": "prev-session-id",
            "goal_branch_rejected_session_id": "some-older-rejected-session-id",
        });
        let (session_id, _tip) = prior_goal_branch_tip(&repo, &metadata)
            .await
            .expect("a stale rejection marker for a different session must not block this one");
        assert_eq!(session_id, "prev-session-id");
    }

    #[tokio::test]
    #[serial_test::serial]
    async fn dispatch_goal_fn_dispatches_an_internal_worker_through_a_headless_policy_with_no_extension_manager(
    ) {
        std::env::set_var("PERMAGENT_ROLE_EDIT_PROVIDER", "ollama");
        std::env::set_var("PERMAGENT_ROLE_EDIT_MODEL", "qwen3");

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        // Isolate into a throwaway repo, never this checkout (see the helper's
        // doc comment) — the completion tracker's background push may still
        // fail against it (no remote), which is fine: best-effort, and this
        // test never awaits that far.
        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(repo.to_str().unwrap())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "ready", 0).await;

        let session = crate::session::Session {
            provider_name: Some("ollama".to_string()),
            model_config: Some(crate::model::ModelConfig::new("qwen3").unwrap()),
            ..crate::session::Session::default()
        };
        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let probe_cache = ProbeCache::new();
        let policy = HeadlessDispatchPolicy {
            session_for_provider_fallback: Some(Arc::new(session)),
            restrict_ranked_selection_to_internal_engine: true,
            auto_land: false,
        };

        // Pin the worker explicitly ("permagent" — InternalSubagent) so this
        // test exercises T1's provider fallback deterministically, without
        // depending on T2's ranked-selection outcome (covered separately).
        let result = dispatch_goal_fn(
            &context,
            &probe_cache,
            &card.id,
            Some("permagent"),
            Some(&policy),
        )
        .await;

        std::env::remove_var("PERMAGENT_ROLE_EDIT_PROVIDER");
        std::env::remove_var("PERMAGENT_ROLE_EDIT_MODEL");

        let session_id = result.expect(
            "dispatch through a session-carrying headless policy must succeed — no \
             'Extension manager not available' error",
        );
        assert!(!session_id.is_empty());
    }

    /// X-cost-1, end-to-end: a fresh goal dispatched through a headless
    /// policy with ONLY `PERMAGENT_PACK_MECHANICAL_*` pinned (no
    /// `PERMAGENT_ROLE_*`) must record the PACK model on the goal card's
    /// routing receipt (`capability_snapshot.model_routing`), written
    /// SYNCHRONOUSLY by `advance_goal_checked` before `engine.spawn` even
    /// runs — unlike the dispatched child session's own `model_config`,
    /// which the spawned subagent task updates later and is not safe to
    /// assert against right after `dispatch_goal_fn` returns. A vanilla
    /// `setup_goal_in_state` card ("Test goal in ready" / "test") hits
    /// `assess_goal`'s no-strong-signal default (`Tier::CheapCloud` →
    /// `WorkflowRole::Mechanical`) on this, its first dispatch — no
    /// escalation state exists yet — so the assessed-role branch of
    /// `dispatch_goal_fn`'s InternalSubagent arm is what must consult the
    /// pack pin. Pre-fix, `role_model_or_derived` never read
    /// `PERMAGENT_PACK_*` at all, so this pin had zero effect and the
    /// receipt would have shown the T1 session fallback instead.
    #[tokio::test]
    #[serial_test::serial]
    async fn dispatch_goal_fn_honours_a_pack_only_pin_for_a_fresh_headless_goal() {
        std::env::remove_var("PERMAGENT_ROLE_MECHANICAL_PROVIDER");
        std::env::remove_var("PERMAGENT_ROLE_MECHANICAL_MODEL");
        std::env::set_var("PERMAGENT_PACK_MECHANICAL_PROVIDER", "ollama");
        std::env::set_var("PERMAGENT_PACK_MECHANICAL_MODEL", "qwen3-coder");

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(repo.to_str().unwrap())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "ready", 0).await;

        // The T1 session fallback is a DIFFERENT model from the pack pin, so
        // the assertion below is exact: if the pin were ignored, the child
        // would land on "ollama"/"qwen3" (the fallback), not "qwen3-coder"
        // (the pin).
        let fallback_session = crate::session::Session {
            provider_name: Some("ollama".to_string()),
            model_config: Some(crate::model::ModelConfig::new("qwen3").unwrap()),
            ..crate::session::Session::default()
        };
        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let probe_cache = ProbeCache::new();
        let policy = HeadlessDispatchPolicy {
            session_for_provider_fallback: Some(Arc::new(fallback_session)),
            restrict_ranked_selection_to_internal_engine: true,
            auto_land: false,
        };

        let result = dispatch_goal_fn(
            &context,
            &probe_cache,
            &card.id,
            Some("permagent"),
            Some(&policy),
        )
        .await;

        std::env::remove_var("PERMAGENT_PACK_MECHANICAL_PROVIDER");
        std::env::remove_var("PERMAGENT_PACK_MECHANICAL_MODEL");

        let _session_id = result.expect("dispatch must succeed");

        let updated = cards::get_card(&pool, &card.id)
            .await
            .unwrap()
            .expect("the card must still exist");
        let routing = updated
            .metadata_json
            .get("capability_snapshot")
            .and_then(|s| s.get("model_routing"))
            .unwrap_or_else(|| {
                panic!(
                    "expected a model_routing receipt, got {:?}",
                    updated.metadata_json
                )
            });
        assert_eq!(
            routing.get("source").and_then(|v| v.as_str()),
            Some("pack_pin"),
            "{routing:?}"
        );
        assert_eq!(
            routing.get("provider").and_then(|v| v.as_str()),
            Some("ollama"),
            "{routing:?}"
        );
        assert_eq!(
            routing.get("model").and_then(|v| v.as_str()),
            Some("qwen3-coder"),
            "the receipt must name the PACK-pinned model, not the T1 session \
             fallback ('qwen3'): {routing:?}"
        );
    }

    /// R48d (HARNESS_LOOP_LOG.md "A45 design", Addendum (b)/(c)): an explicit
    /// per-goal `worker_tier` — persisted as `card.metadata_json.
    /// dispatch_worker_tier`, exactly the way `goal_advance{action: dispatch,
    /// worker_tier}` persists it before calling into this function — outranks
    /// the default breadth/vocabulary rule outright. Mirrors
    /// `dispatch_goal_fn_honours_a_pack_only_pin_for_a_fresh_headless_goal`'s
    /// own env-pin/assert-on-the-persisted-receipt shape, but pins the LOCAL
    /// pack: a vanilla `setup_goal_in_state` goal's own default rule
    /// (`default_worker_tier_for_goal`, no `paths`/`tags` set) lands on
    /// `Mechanical`, a DIFFERENT role/pack from `Local` — so a Local-pinned
    /// receipt is only possible if the explicit tier actually won.
    #[tokio::test]
    #[serial_test::serial]
    async fn dispatch_goal_fn_honours_an_explicit_worker_tier_and_records_it_on_the_audit() {
        std::env::remove_var("PERMAGENT_ROLE_LOCAL_PROVIDER");
        std::env::remove_var("PERMAGENT_ROLE_LOCAL_MODEL");
        std::env::set_var("PERMAGENT_PACK_LOCAL_PROVIDER", "ollama");
        std::env::set_var("PERMAGENT_PACK_LOCAL_MODEL", "qwen3-coder");

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(repo.to_str().unwrap())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "ready", 0).await;
        // Persist the explicit worker_tier exactly as `goal_advance` would —
        // this test exercises `dispatch_goal_fn`'s own precedence, not the
        // `handle_goal_advance` validation wired ahead of it.
        sqlx::query(
            "UPDATE cards SET metadata_json = json_set(metadata_json, '$.dispatch_worker_tier', ?) \
             WHERE id = ?",
        )
        .bind("local")
        .bind(&card.id)
        .execute(&pool)
        .await
        .unwrap();

        let fallback_session = crate::session::Session {
            provider_name: Some("ollama".to_string()),
            model_config: Some(crate::model::ModelConfig::new("qwen3").unwrap()),
            ..crate::session::Session::default()
        };
        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let probe_cache = ProbeCache::new();
        let policy = HeadlessDispatchPolicy {
            session_for_provider_fallback: Some(Arc::new(fallback_session)),
            restrict_ranked_selection_to_internal_engine: true,
            auto_land: false,
        };

        let result = dispatch_goal_fn(
            &context,
            &probe_cache,
            &card.id,
            Some("permagent"),
            Some(&policy),
        )
        .await;

        std::env::remove_var("PERMAGENT_PACK_LOCAL_PROVIDER");
        std::env::remove_var("PERMAGENT_PACK_LOCAL_MODEL");

        let _session_id = result.expect("dispatch must succeed");

        let updated = cards::get_card(&pool, &card.id)
            .await
            .unwrap()
            .expect("the card must still exist");
        let snapshot = updated
            .metadata_json
            .get("capability_snapshot")
            .unwrap_or_else(|| {
                panic!(
                    "expected a capability_snapshot, got {:?}",
                    updated.metadata_json
                )
            });
        let routing = snapshot
            .get("model_routing")
            .unwrap_or_else(|| panic!("expected a model_routing receipt, got {snapshot:?}"));
        assert_eq!(
            routing.get("provider").and_then(|v| v.as_str()),
            Some("ollama"),
            "{routing:?}"
        );
        assert_eq!(
            routing.get("model").and_then(|v| v.as_str()),
            Some("qwen3-coder"),
            "the explicit worker_tier must route to the LOCAL pack pin, not the \
             default rule's Mechanical/CheapCloud pick: {routing:?}"
        );

        let cost_routing = snapshot
            .get("cost_routing")
            .unwrap_or_else(|| panic!("expected a cost_routing audit block, got {snapshot:?}"));
        assert_eq!(
            cost_routing.get("routing_choice").and_then(|v| v.as_str()),
            Some("local"),
            "the dispatch audit row must carry routing_choice: {cost_routing:?}"
        );
        assert!(
            cost_routing.get("routing_reason").is_some(),
            "{cost_routing:?}"
        );
    }

    /// R48d: `goal_advance{action: dispatch, worker_tier}` refuses an
    /// unrecognized tier before dispatch even starts — `WorkflowRole::
    /// from_tag` is a fixed, deterministic match with no dependency on
    /// global config, so this refusal fires regardless of what routing IS
    /// configured in the test environment.
    #[tokio::test]
    async fn goal_advance_dispatch_refuses_an_unrecognized_worker_tier_naming_the_valid_tiers() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 1).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        args.insert("action".to_string(), serde_json::json!("dispatch"));
        args.insert(
            "worker_tier".to_string(),
            serde_json::json!("not-a-real-tier-r48d"),
        );

        let err = client
            .handle_goal_advance(Some(args))
            .await
            .expect_err("an unrecognized worker_tier must refuse before dispatch even starts");
        assert!(
            err.contains("not-a-real-tier-r48d"),
            "the refusal must name the offending value: {err}"
        );
        assert!(
            err.to_lowercase().contains("tier"),
            "the refusal must be about the worker_tier: {err}"
        );
    }

    /// R48d: the pure core of `routing_roster` — one row per `WorkflowRole`,
    /// classified consistently with `is_local_provider`, an unresolvable role
    /// reporting "unavailable" rather than a baked default. Two fake packs
    /// (one local, one cloud) stand in for a real `DerivedRoleMap` so this
    /// stays a pure, IO-free test.
    #[test]
    fn routing_roster_reflects_the_configured_packs() {
        use crate::cost_router::{RoleModel, RoleSource, WorkflowRole};

        let cloud = RoleModel {
            provider: "anthropic".to_string(),
            model: "claude-opus-4-8".to_string(),
        };
        let local = RoleModel {
            provider: "ollama".to_string(),
            model: "qwen3-coder".to_string(),
        };
        let rows = routing_roster_rows(|role| match role {
            WorkflowRole::Orchestrate | WorkflowRole::Review => {
                Some((cloud.clone(), RoleSource::Configured))
            }
            WorkflowRole::Mechanical | WorkflowRole::Local => {
                Some((local.clone(), RoleSource::Derived))
            }
            WorkflowRole::Edit => None,
        });

        assert_eq!(rows.len(), 5, "one row per WorkflowRole: {rows:?}");

        let orchestrate = rows
            .iter()
            .find(|r| r.tier == "orchestrate")
            .expect("orchestrate row");
        assert!(orchestrate.available);
        assert_eq!(orchestrate.local_or_cloud, Some("cloud"));
        assert_eq!(orchestrate.provider.as_deref(), Some("anthropic"));

        let local_row = rows.iter().find(|r| r.tier == "local").expect("local row");
        assert!(local_row.available);
        assert_eq!(local_row.local_or_cloud, Some("local"));
        assert_eq!(local_row.provider.as_deref(), Some("ollama"));
        assert_eq!(local_row.source, Some("derived"));

        let edit = rows.iter().find(|r| r.tier == "edit").expect("edit row");
        assert!(!edit.available, "{edit:?}");
        assert_eq!(edit.provider, None);
        assert_eq!(
            edit.reason,
            Some("unavailable — no configured or derived model"),
            "an unresolvable role must say so plainly, never a baked default: {edit:?}"
        );
    }

    /// R48d: `explicit_routing_choice` reads `card.metadata_json.
    /// dispatch_worker_tier`/`dispatch_reason` — present with a recognized
    /// tag → `Some`; absent, or an unrecognized tag (e.g. hand-edited
    /// metadata), → `None` rather than inventing a role from garbage.
    #[test]
    fn explicit_routing_choice_reads_a_recognized_tag_and_ignores_the_rest() {
        let present = explicit_routing_choice(&serde_json::json!({
            "dispatch_worker_tier": "local",
            "dispatch_reason": "small py fixture",
        }))
        .expect("a recognized tag must resolve");
        assert_eq!(present.tier, crate::cost_router::WorkflowRole::Local);
        assert_eq!(present.reason, "small py fixture");

        let no_reason = explicit_routing_choice(&serde_json::json!({
            "dispatch_worker_tier": "orchestrate",
        }))
        .expect("a recognized tag must resolve even with no reason");
        assert_eq!(
            no_reason.reason, "explicit worker_tier on dispatch",
            "a missing reason gets a stand-in, not an empty string"
        );

        assert!(explicit_routing_choice(&serde_json::json!({})).is_none());
        assert!(explicit_routing_choice(&serde_json::json!({
            "dispatch_worker_tier": "not-a-real-tier",
        }))
        .is_none());
    }

    /// Lane U / U1 (HARNESS_LOOP_LOG.md, "Lane G4 review" finding 1,
    /// CRITICAL): before this fix, `OrchestratorClient::dispatch_goal_to`
    /// hardcoded `policy: None` no matter what
    /// `install_dispatch_hook_for_headless_session` had installed, so
    /// `goal_advance(dispatch)` (`handle_goal_advance`'s
    /// `GoalAction::Dispatch` arm, which calls `dispatch_goal_to` directly)
    /// and `resume_roadmap` (`handle_resume_roadmap` → `dispatch_eligible_goals`
    /// → `OrchestratorClient::dispatch_goal` → `dispatch_goal_to`) never got
    /// T1's provider fallback or T2's internal-engine restriction — only the
    /// auto-dispatch nudge (through `GOAL_DISPATCH_HOOK` directly) did.
    ///
    /// Both calls below are safe by construction rather than by hoping no
    /// external CLI is on `PATH`: the `goal_advance(dispatch)` call is
    /// pinned to `permagent` (bypasses ranked selection entirely — the
    /// SAME technique
    /// `dispatch_goal_fn_dispatches_an_internal_worker_through_a_headless_policy_with_no_extension_manager`
    /// uses), and the `resume_roadmap` call relies on structural safety, not
    /// luck: T2's `restrict_ranked_selection_to_internal_engine` (the
    /// installer's default) filters every ExternalCli/SupervisedCli worker
    /// out of the candidate list BEFORE `select_worker_detailed` ever probes
    /// one, so ranked selection cannot reach Claude Code/Codex/Cursor once
    /// the policy is installed — the exact hazard Lane T's own T2 test found
    /// real on this machine.
    ///
    /// Pre-fix repro: reverting `dispatch_goal_to`'s `policy` argument back
    /// to a literal `None` and running this test panics at the first
    /// `.expect(...)` below with
    /// `"goal_advance(dispatch) must reach the installed headless policy \
    /// through dispatch_goal_to instead of the hardcoded \`policy: None\` \
    /// G4 finding 1 flagged: \"Extension manager not available\""` — the
    /// InternalSubagent branch's `resolve_worker_provider_fn(context, None)`
    /// fails exactly like the original S1 defect, on a path S1/T1 never
    /// touched.
    #[tokio::test]
    #[serial_test::serial]
    async fn dispatch_goal_to_and_resume_roadmap_consult_the_installed_headless_policy() {
        // Lane T1: force a clean slot for the whole test, regardless of
        // whatever another test in this binary already installed — the
        // assertions below need `install_dispatch_hook_for_headless_session`
        // (below) to actually be the one that wins the process-global
        // dispatch-hook slot's first-install-wins race, which is only
        // guaranteed if the slot starts empty. Held for the whole function
        // so `Drop` restores the prior state once this test is done, rather
        // than leaking this test's own hook into whatever runs next.
        let _hook_guard = take_goal_dispatch_hook_for_test();

        std::env::set_var("PERMAGENT_ROLE_EDIT_PROVIDER", "ollama");
        std::env::set_var("PERMAGENT_ROLE_EDIT_MODEL", "qwen3");

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(repo.to_str().unwrap())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        sm.update(&coordinator.id)
            .provider_name("ollama")
            .model_config(crate::model::ModelConfig::new("qwen3").unwrap())
            .apply()
            .await
            .unwrap();

        // The SAME production installer `permagent run` calls — this test
        // must exercise the real seam, not a hand-rolled substitute.
        install_dispatch_hook_for_headless_session(sm.clone(), coordinator.id.clone());

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let orchestrator = OrchestratorClient::new(context).unwrap();

        // `goal_advance(dispatch)`. Marked `read_only` so it never trips
        // `write_scope_conflict` against goal B below (two undeclared-scope
        // goals in the same project would otherwise refuse to run
        // concurrently — orthogonal to what this test pins).
        let card_a = setup_goal_in_state(&pool, "ready", 0).await;
        sqlx::query(
            "UPDATE cards SET metadata_json = json_set(metadata_json, '$.read_only', json('true')) \
             WHERE id = ?",
        )
        .bind(&card_a.id)
        .execute(&pool)
        .await
        .unwrap();
        let result_a = orchestrator
            .dispatch_goal_to(&card_a.id, Some("permagent"))
            .await;
        let session_a = result_a.expect(
            "goal_advance(dispatch) must reach the installed headless policy through \
             dispatch_goal_to instead of the hardcoded `policy: None` G4 finding 1 flagged",
        );
        assert!(!session_a.is_empty());

        // `resume_roadmap` → `dispatch_eligible_goals` → `dispatch_goal` →
        // `dispatch_goal_to(id, None)` (ranked selection).
        let card_b = setup_goal_in_state(&pool, "ready", 0).await;
        let dispatched =
            dispatch_eligible_goals(&pool, crate::projects::PERSONAL_PROJECT_ID, &orchestrator)
                .await
                .expect("dispatch_eligible_goals must not error");

        std::env::remove_var("PERMAGENT_ROLE_EDIT_PROVIDER");
        std::env::remove_var("PERMAGENT_ROLE_EDIT_MODEL");

        assert_eq!(
            dispatched, 1,
            "resume_roadmap's dispatch_eligible_goals must reach the installed headless \
             policy too — a bypass here reports 0 dispatched instead of failing loudly"
        );
        let updated_b = cards::get_card(&pool, &card_b.id).await.unwrap().unwrap();
        let col_b = cards::get_column(&pool, &updated_b.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col_b.state_binding.as_deref(),
            Some("in_progress"),
            "the resume_roadmap goal must have actually been dispatched, not just counted"
        );
    }

    /// T2 pinning (pure): `worker_engine_allowed_for_ranked_dispatch` — the
    /// filter `select_worker_detailed` applies to its candidate list — must
    /// keep every worker when unrestricted (today's behavior, unchanged) and
    /// keep ONLY InternalSubagent-engine workers when restricted. Exercised
    /// against the REAL default roster's real entries (not a hand-rolled
    /// fixture) so this pins actual production data: Claude Code, Codex and
    /// Cursor are all ExternalCli and must be excluded; `permagent` is
    /// InternalSubagent and must remain.
    #[test]
    fn worker_engine_allowed_for_ranked_dispatch_restricts_to_internal_subagent_workers_only() {
        let roster = agent_identity::default_roster();

        for external_key in ["claude_code", "codex", "cursor"] {
            let engine = &roster[external_key].engine;
            assert!(
                matches!(engine, agent_identity::WorkerEngineKind::ExternalCli { .. }),
                "fixture assumption: '{external_key}' must be ExternalCli"
            );
            assert!(
                worker_engine_allowed_for_ranked_dispatch(engine, false),
                "unrestricted selection must still consider '{external_key}' — unchanged behavior"
            );
            assert!(
                !worker_engine_allowed_for_ranked_dispatch(engine, true),
                "a headless run must never consider ExternalCli worker '{external_key}'"
            );
        }

        let permagent_engine = &roster["permagent"].engine;
        assert!(matches!(
            permagent_engine,
            agent_identity::WorkerEngineKind::InternalSubagent
        ));
        assert!(worker_engine_allowed_for_ranked_dispatch(
            permagent_engine,
            false
        ));
        assert!(
            worker_engine_allowed_for_ranked_dispatch(permagent_engine, true),
            "an InternalSubagent worker must remain a candidate even when restricted"
        );
    }

    /// T2, integration: `select_worker_detailed`'s own restriction argument
    /// must never select a non-InternalSubagent worker for a code-editing
    /// goal card. This is the "before" reproduction of the live defect too —
    /// `dispatch_ready_goals_with`'s auto-nudge (the CLI hook's own call
    /// shape) always calls with `requested_worker: None`, so before T2 this
    /// exact call could return Claude Code/Codex/Cursor whenever one is
    /// `bin_exists` on the machine running the test — which is a real,
    /// non-hypothetical risk on Jesse's own dev machine where these tools are
    /// installed. Asserting the ENGINE KIND of the restricted call's result
    /// (rather than which specific worker) keeps this deterministic
    /// regardless of which external CLIs happen to be on PATH. G15 MED-4:
    /// also pin the audit's eligible pool and ranking to the selection snapshot.
    #[tokio::test]
    async fn internal_only_selection_and_cost_audit_agree_on_candidates() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 0).await;
        let probe_cache = ProbeCache::new();

        let restricted = select_worker_detailed(&pool, &probe_cache, &card, true)
            .await
            .expect(
                "an internal-only worker must always be selectable (permagent is always available)",
            );

        let config = agent_identity::load_agent_config();
        let required: Vec<String> =
            serde_json::from_value(restricted.snapshot["required_kinds"].clone()).unwrap();
        let ordinary: Vec<&String> = required
            .iter()
            .filter(|kind| {
                agent_identity::WorkerCapabilities::default()
                    .supports_requirement(kind)
                    .is_none()
            })
            .collect();
        let mut expected: Vec<serde_json::Value> = restricted.snapshot["candidates_considered"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|row| {
                let kinds: Vec<String> = serde_json::from_value(row["tool_kinds"].clone()).unwrap();
                row["available"] == true
                    && (kinds.is_empty() || ordinary.iter().all(|kind| kinds.contains(kind)))
            })
            .cloned()
            .collect();
        expected.sort_by_key(|row| row["key"].as_str().unwrap().to_string());
        assert!(!expected.is_empty());
        // Check both the real selection snapshot and the audit's no-snapshot
        // fallback, so snapshot filtering cannot hide an extra audit candidate.
        for snapshot in [&restricted.snapshot, &serde_json::Value::Null] {
            let candidates =
                cost_routing_candidates(&pool, &probe_cache, &config, true, &required, snapshot)
                    .await;
            assert_eq!(
                goal_state::select_best_worker(&candidates, &[]).unwrap(),
                restricted.worker_key
            );
            let audit = build_capability_snapshot(&restricted.worker_key, &required, &candidates);
            let mut actual = audit["candidates_considered"].as_array().unwrap().clone();
            actual.sort_by_key(|row| row["key"].as_str().unwrap().to_string());
            assert_eq!(actual, expected);
        }
        let engine = config
            .workers
            .get(&restricted.worker_key)
            .map(|w| &w.engine)
            .expect("selected worker must be a real roster entry");
        assert!(
            matches!(engine, agent_identity::WorkerEngineKind::InternalSubagent),
            "restricted headless selection chose '{}', engine {:?} — must be InternalSubagent",
            restricted.worker_key,
            engine
        );
    }

    /// E4 (harness loop, Round E, from Lane F9 forensics 2026-09-10) —
    /// corrects this test's prior claim. Pre-E4, `select_requested_worker`
    /// (the `Some(requested)` arm of `dispatch_goal_fn`'s worker selection)
    /// never consulted the restriction flag at all — only the ranked
    /// (`None`) arm did — which is exactly how fx08's coordinator, under
    /// `PERMAGENT_HEADLESS_WORKER=internal`, pinned `claude_code`, then
    /// `cursor`, then `codex` in turn and had every one of them honoured
    /// before failing downstream on a durable-identity check. Requesting an
    /// InternalSubagent worker (`permagent`, always available) is
    /// unaffected by the restriction either way — this pins that the
    /// UNRESTRICTED case still resolves it normally, both with and without
    /// a policy asking for restriction (since it is internal either way,
    /// there is nothing to restrict).
    #[tokio::test]
    async fn select_requested_worker_honours_an_internal_pin_regardless_of_restriction() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 0).await;
        let probe_cache = ProbeCache::new();

        for restrict in [false, true] {
            let selection = select_requested_worker(
                &pool,
                &probe_cache,
                &card,
                "permagent",
                restrict,
            )
            .await
            .expect("an explicitly requested, always-available internal worker must be honoured");
            assert_eq!(selection.worker_key, "permagent");
            assert_eq!(selection.snapshot["selection_mode"], "explicitly_requested");
        }
    }

    /// E4 pin, fx08's exact shape: an internal-only headless session
    /// (`restrict_to_internal_engine: true`) must refuse an EXPLICIT pin to
    /// an external-CLI worker, honestly, before spending an attempt —
    /// rather than honouring the pin and letting it fail three attempts
    /// later on `ExternalCliEngine::validate_billing_contract`'s durable-
    /// identity check. Pre-fix: this call succeeds (the restriction is
    /// silently ignored for a pinned request) — this assertion fails on
    /// `.is_ok()` instead of the expected `Err`.
    ///
    /// M2 (G8 review, harness loop Lane E3 2026-09-10): the prior version of
    /// this test found its external worker via
    /// `agent_identity::load_agent_config()`'s REAL result — which reads
    /// this machine's actual `~/.permagent/agent.yaml`
    /// (`agent_identity::agent_yaml_path`, gated on `PERMAGENT_PATH_ROOT`
    /// only when a test opts in) merged with `default_roster()` only for
    /// keys the file does NOT already define
    /// (`merge_missing_default_workers` — `.entry(key).or_insert(...)`,
    /// never overwrites an existing entry). A machine whose saved
    /// `agent.yaml` redefines every default external-CLI worker
    /// (`claude_code`/`codex`/`cursor`) as something other than
    /// `ExternalCli`, or removes them, made the `else { return; }` that used
    /// to sit here silently skip this ENTIRE test on THAT machine — never
    /// caught by CI's own clean environment — permanently losing coverage
    /// for the exact fx08 regression this lane exists to pin. Fixed by
    /// constructing the roster this test runs against, in an isolated
    /// `PERMAGENT_PATH_ROOT`, so an external-CLI worker is unconditionally
    /// present and this test can never pass vacuously.
    #[tokio::test]
    async fn select_requested_worker_refuses_an_external_pin_when_restricted_to_internal() {
        let _guard = env_lock::lock_env([("PERMAGENT_PATH_ROOT", None::<&str>)]);
        let path_root = tempfile::tempdir().unwrap();
        std::env::set_var("PERMAGENT_PATH_ROOT", path_root.path());

        let external_key = "e3_test_external_worker";
        let mut workers = std::collections::HashMap::new();
        workers.insert(
            external_key.to_string(),
            agent_identity::WorkerPersona {
                first_name: "E3 Test External".to_string(),
                engine: agent_identity::WorkerEngineKind::ExternalCli {
                    bin: "definitely-not-a-real-binary-e3-test".to_string(),
                    args: vec!["{prompt}".to_string()],
                },
                ..Default::default()
            },
        );
        let fixture_config = agent_identity::AgentConfig {
            primary: Default::default(),
            workers,
        };
        let yaml_path = agent_identity::agent_yaml_path();
        std::fs::create_dir_all(yaml_path.parent().unwrap()).unwrap();
        std::fs::write(&yaml_path, serde_yaml::to_string(&fixture_config).unwrap()).unwrap();

        // Confirm the fixture is genuinely external-CLI before trusting
        // anything below — this pin must never itself pass vacuously.
        let loaded = agent_identity::load_agent_config();
        let persona = loaded
            .workers
            .get(external_key)
            .expect("the fixture worker must be present in the loaded roster");
        assert!(
            !matches!(
                persona.engine,
                agent_identity::WorkerEngineKind::InternalSubagent
            ),
            "the fixture worker must be an external-CLI engine, not internal"
        );

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 0).await;
        let probe_cache = ProbeCache::new();

        let err = select_requested_worker(&pool, &probe_cache, &card, external_key, true)
            .await
            .expect_err("a headless internal-only run must refuse an explicit external pin");
        assert!(
            err.contains("restricted to internal workers only"),
            "the refusal must say WHY, not just fail: {err}"
        );

        // Unrestricted, this fix must add NO new refusal — the external
        // worker may still fail for its own, pre-existing reasons (its CLI
        // binary does not exist on this test machine, by deliberate
        // construction above), but never for "restricted to internal
        // workers only".
        if let Err(unrestricted_err) =
            select_requested_worker(&pool, &probe_cache, &card, external_key, false).await
        {
            assert!(
                !unrestricted_err.contains("restricted to internal workers only"),
                "an unrestricted run must never see this lane's new refusal: {unrestricted_err}"
            );
        }

        std::env::remove_var("PERMAGENT_PATH_ROOT");
    }

    /// T2: no policy (the daemon's own `install_dispatch_hook` shape) leaves
    /// `dispatch_goal_fn`'s ranked selection UNRESTRICTED — `restrict` derives
    /// from `policy.is_some_and(...)`, so `policy: None` is always `false`.
    #[test]
    fn no_policy_never_restricts_ranked_selection() {
        assert!(!None::<&HeadlessDispatchPolicy>
            .is_some_and(|p| p.restrict_ranked_selection_to_internal_engine));
    }

    // ── Harness loop, Lane T / T3: bounded post-run drain ───────────────────

    /// Stamp `worker_session_id` onto a card's metadata — the mark
    /// `dispatch_goal_fn` leaves before the completion tracker starts, and
    /// the signal [`goal_card_for_worker_session`] reads back.
    async fn attach_worker_session_to_card(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        card_id: &str,
        session_id: &str,
    ) {
        let card = cards::get_card(pool, card_id).await.unwrap().unwrap();
        let mut meta = card.metadata_json.as_object().cloned().unwrap_or_default();
        meta.insert(
            "worker_session_id".to_string(),
            serde_json::json!(session_id),
        );
        sqlx::query("UPDATE cards SET metadata_json = ? WHERE id = ?")
            .bind(serde_json::Value::Object(meta).to_string())
            .bind(card_id)
            .execute(pool)
            .await
            .unwrap();
    }

    /// T3, "nothing dispatched → no wait": a coordinator session with no
    /// child sessions at all must return instantly with an empty summary —
    /// this is the case that must NEVER block `permagent run`'s exit, and it
    /// is asserted against a generous cap so a regression that ignores the
    /// empty wait-set (and sleeps for the whole cap regardless) would show up
    /// as a slow test, not just a wrong count.
    #[tokio::test]
    async fn drain_dispatched_goals_returns_immediately_when_nothing_was_dispatched() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        let start = std::time::Instant::now();
        let summary = drain_dispatched_goals(
            &pool,
            &coordinator.id,
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(20),
            |_, _| panic!("no dispatched goal exists — on_status must never fire"),
        )
        .await
        .unwrap();

        assert!(
            start.elapsed() < std::time::Duration::from_secs(1),
            "an empty wait-set must never sleep out the cap: took {:?}",
            start.elapsed()
        );
        assert_eq!(summary, DrainSummary::default());
        assert!(!summary.dispatched_anything());
    }

    /// T3, "a fake dispatched goal that completes → drain returns promptly":
    /// the goal card is ALREADY Complete before the drain starts (the
    /// simplest deterministic stand-in for "completed by the time we poll" —
    /// no timing dependency on a concurrently-running fake worker), so the
    /// very first poll observes a terminal state and returns without
    /// sleeping out the generous cap.
    #[tokio::test]
    async fn drain_dispatched_goals_returns_promptly_once_the_dispatched_goal_completes() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let child = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: fake".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let card = setup_goal_in_state(&pool, "complete", 1).await;
        attach_worker_session_to_card(&pool, &card.id, &child.id).await;

        let start = std::time::Instant::now();
        let mut observed = Vec::new();
        let summary = drain_dispatched_goals(
            &pool,
            &coordinator.id,
            std::time::Duration::from_secs(5),
            std::time::Duration::from_millis(20),
            |session_id, state| observed.push((session_id.to_string(), state)),
        )
        .await
        .unwrap();

        assert!(
            start.elapsed() < std::time::Duration::from_secs(1),
            "an already-complete goal must not sleep out the cap: took {:?}",
            start.elapsed()
        );
        assert_eq!(
            summary,
            DrainSummary {
                finished: 1,
                timed_out: 0
            }
        );
        assert_eq!(observed, vec![(child.id.clone(), GoalState::Complete)]);
    }

    /// Harness loop, Lane V (V2): "drain waits for landing" — a goal that
    /// completed but has NOT been landed (it sits in `Review`, exactly where
    /// V1 leaves an unverified goal, or where any goal sits before a human
    /// approves it) must never be mistaken for a terminal state. `Review` is
    /// deliberately absent from `drain_dispatched_goals`'s own `TERMINAL`
    /// array — this test pins that a goal parked there is waited on (never
    /// treated as "already done") and, at the cap, is parked exactly like any
    /// other still-running goal — never silently counted as finished.
    #[tokio::test]
    async fn drain_dispatched_goals_does_not_treat_review_as_landed() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let child = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: fake".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        // Review, not Complete: the goal finished its worker run and has an
        // open approve_review decision (V1 left it here because it had no
        // durable verifier pass), but nothing has landed it yet.
        let card = setup_goal_in_state(&pool, "review", 1).await;
        attach_worker_session_to_card(&pool, &card.id, &child.id).await;

        let cap = std::time::Duration::from_millis(80);
        let start = std::time::Instant::now();
        let summary = drain_dispatched_goals(
            &pool,
            &coordinator.id,
            cap,
            std::time::Duration::from_millis(20),
            |_, _| {},
        )
        .await
        .unwrap();
        let elapsed = start.elapsed();

        assert!(
            elapsed >= cap,
            "a goal sitting in Review (not landed) must be waited on, not treated as terminal: \
             returned after {elapsed:?} against a {cap:?} cap"
        );
        assert_eq!(
            summary,
            DrainSummary {
                finished: 0,
                timed_out: 1
            },
            "an un-landed goal must be counted as timed-out/parked, never as finished"
        );
        assert!(
            landed_goals_for_session(&pool, &coordinator.id)
                .await
                .unwrap()
                .is_empty(),
            "a goal that only reached Review must never be reported as landed"
        );
    }

    /// Harness loop, Lane V (V2): `landed_goals_for_session` is the CLI's own
    /// source for its "landed `<id>` → `<sha>`" summary lines — reads back
    /// the head commit `goal_landing::land` fast-forwarded, for every
    /// dispatched goal that reached Complete.
    #[tokio::test]
    async fn landed_goals_for_session_reads_back_the_head_commit_of_a_complete_goal() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let landed_child = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: landed".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let landed_card = setup_goal_in_state(&pool, "complete", 1).await;
        attach_worker_session_to_card(&pool, &landed_card.id, &landed_child.id).await;
        // YF2 (G6 review, Lane Y-fix 2026-09-09): `head_commit`/`commits`
        // alone are no longer sufficient — `goal_landed_head_commit` also
        // requires `dispatch_evidence.landing.outcome == "landed"`, the
        // field `land_approved_goal` now persists once `goal_landing::land`
        // actually succeeds.
        cards::set_goal_dispatch_evidence(
            &pool,
            &landed_card.id,
            serde_json::json!({
                "head_commit": "deadbeefcafe",
                "commits": ["one"],
                "landing": {
                    "outcome": "landed",
                    "landed_head": "deadbeefcafe",
                    "describe": "landed: main fast-forwarded to deadbeefc (goal/run-1)",
                    "at": "2026-09-09T00:00:00Z",
                },
            }),
        )
        .await
        .unwrap();

        // A second dispatched goal that is still Review (not landed) must
        // never appear in the result.
        let unlanded_child = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: not landed".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let unlanded_card = setup_goal_in_state(&pool, "review", 1).await;
        attach_worker_session_to_card(&pool, &unlanded_card.id, &unlanded_child.id).await;

        let landed = landed_goals_for_session(&pool, &coordinator.id)
            .await
            .unwrap();
        assert_eq!(
            landed,
            vec![(landed_card.id.clone(), "deadbeefcafe".to_string())]
        );
    }

    /// Y10d (A15 Q4a): M15 fx05 and fx08 — both Y6 re-dispatches, both
    /// first-ever solves of their fixture — each printed
    /// `note: landed <id> → <sha>` TWICE. `landed_goals_for_session` walks
    /// SESSIONS, and a re-dispatched card has one worker session per attempt
    /// (all kept in `worker_session_ids`), every one of which resolves back to
    /// the same card. One line per goal, not per attempt.
    #[tokio::test]
    async fn landed_goals_for_session_reports_a_re_dispatched_card_once() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        // Two worker sessions, the shape Y6's requeue leaves behind: attempt 1
        // ran out of rope, attempt 2 finished the same card.
        let mut worker_ids = Vec::new();
        for attempt in 1..=2 {
            let child = sm
                .create_session_with_parent(
                    Some(&coordinator.id),
                    tmp.path().to_path_buf(),
                    format!("Goal: attempt {attempt}"),
                    SessionType::SubAgent,
                    GooseMode::Auto,
                )
                .await
                .unwrap();
            worker_ids.push(child.id);
        }

        let card = setup_goal_in_state(&pool, "complete", 1).await;
        let stored = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let mut meta = stored
            .metadata_json
            .as_object()
            .cloned()
            .unwrap_or_default();
        meta.insert(
            "worker_session_ids".to_string(),
            serde_json::json!(worker_ids),
        );
        meta.insert(
            "worker_session_id".to_string(),
            serde_json::json!(worker_ids[1]),
        );
        sqlx::query("UPDATE cards SET metadata_json = ? WHERE id = ?")
            .bind(serde_json::Value::Object(meta).to_string())
            .bind(&card.id)
            .execute(&pool)
            .await
            .unwrap();
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "head_commit": "f7b9c90aaaa",
                "commits": ["one"],
                "landing": {
                    "outcome": "landed",
                    "landed_head": "f7b9c90aaaa",
                    "describe": "landed: main fast-forwarded to f7b9c90 (goal/run-2)",
                    "at": "2026-09-10T00:00:00Z",
                },
            }),
        )
        .await
        .unwrap();

        let landed = landed_goals_for_session(&pool, &coordinator.id)
            .await
            .unwrap();
        assert_eq!(
            landed,
            vec![(card.id.clone(), "f7b9c90aaaa".to_string())],
            "a re-dispatched card must be reported exactly once, not once per attempt"
        );
    }

