    /// Lane U / U2 (HARNESS_LOOP_LOG.md, "Lane G4 review" finding 2, HIGH):
    /// before this fix, `drain_dispatched_goals` queried
    /// `sessions.parent_session_id` exactly ONCE, before the poll loop — a
    /// goal auto-dispatched mid-drain (the common `create_roadmap` shape:
    /// "Remaining goals will dispatch automatically as dependencies
    /// complete") was in neither the initial snapshot nor ever re-queried,
    /// so it was never waited on AND never parked at the cap: the exact
    /// "left silently InProgress" failure T3 exists to close, reintroduced
    /// for every multi-root or dependency-chained roadmap.
    ///
    /// Goal A is dispatched (and stays `in_progress`, never completing)
    /// before the drain starts. Goal B — standing in for a dependent
    /// `promote_and_dispatch_dependents` auto-dispatches once an earlier
    /// goal finishes — is dispatched from a [`DrainIterationHook`] on the
    /// loop's SECOND iteration, deterministically: no sleeping background
    /// task racing the poll loop's own timing, no wall-clock margin to get
    /// wrong under load. Both goals deliberately never reach a terminal
    /// state, so the drain can only return by hitting the cap. The drain
    /// must discover B (created after the loop already started) and park it
    /// at the cap alongside A, not ignore it because it didn't exist when
    /// the loop began.
    ///
    /// Pre-fix repro: temporarily stubbing `drain_dispatched_goals_with` to
    /// snapshot `descendant_session_ids` once before the loop (the pre-U2
    /// shape) makes this panic at `"assertion `left == right` failed: ...
    /// left: DrainSummary { finished: 0, timed_out: 1 }\n right:
    /// DrainSummary { finished: 0, timed_out: 2 }"` — goal B never gets
    /// discovered, so it is never parked and its card is left `in_progress`
    /// after the drain returns.
    #[tokio::test]
    async fn drain_dispatched_goals_waits_for_a_goal_dispatched_mid_drain() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        // Goal A: in_progress for the whole drain, never completes.
        let child_a = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: fake a".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let card_a = setup_goal_in_state(&pool, "in_progress", 0).await;
        attach_worker_session_to_card(&pool, &card_a.id, &child_a.id).await;

        // Deterministic mid-drain dispatch: on the loop's 2nd iteration
        // (never sooner — the 1st iteration only discovers goal A), create
        // goal B and stash it for the assertions below. Goal B never
        // completes either.
        let card_b_cell: Arc<tokio::sync::Mutex<Option<cards::Card>>> =
            Arc::new(tokio::sync::Mutex::new(None));
        let sm_bg = sm.clone();
        let pool_bg = pool.clone();
        let coordinator_id_bg = coordinator.id.clone();
        let tmp_path = tmp.path().to_path_buf();
        let card_b_cell_hook = card_b_cell.clone();
        let mut iteration = 0u32;
        let hook: DrainIterationHook = Box::new(move || {
            iteration += 1;
            let fire = iteration == 2;
            let sm_bg = sm_bg.clone();
            let pool_bg = pool_bg.clone();
            let coordinator_id_bg = coordinator_id_bg.clone();
            let tmp_path = tmp_path.clone();
            let card_b_cell_hook = card_b_cell_hook.clone();
            Box::pin(async move {
                if !fire {
                    return;
                }
                let child_b = sm_bg
                    .create_session_with_parent(
                        Some(&coordinator_id_bg),
                        tmp_path,
                        "Goal: fake b".to_string(),
                        SessionType::SubAgent,
                        GooseMode::Auto,
                    )
                    .await
                    .unwrap();
                let card_b = setup_goal_in_state(&pool_bg, "in_progress", 0).await;
                attach_worker_session_to_card(&pool_bg, &card_b.id, &child_b.id).await;
                *card_b_cell_hook.lock().await = Some(card_b);
            })
        });

        // The cap only needs to cover a handful of poll iterations — nothing
        // here depends on wall-clock scheduling of a separate task.
        let cap = std::time::Duration::from_millis(500);
        let summary = drain_dispatched_goals_with(
            &pool,
            &coordinator.id,
            cap,
            std::time::Duration::from_millis(10),
            |_, _| {},
            Some(hook),
            // U2's pin is about DISCOVERY, not re-dispatch: both goals stay
            // `in_progress` throughout, so no sweep would touch them anyway.
            // Off explicitly so this test never depends on Y6's rail.
            DrainRedispatch {
                dispatch: None,
                max_redispatch: 0,
                sweep_headroom: std::time::Duration::ZERO,
            },
        )
        .await
        .unwrap();

        let card_b = card_b_cell.lock().await.clone().unwrap();

        assert_eq!(
            summary,
            DrainSummary {
                finished: 0,
                timed_out: 2
            },
            "the mid-drain goal must be tracked and parked too, not just the one already \
             dispatched when the drain started"
        );

        let updated_b = cards::get_card(&pool, &card_b.id).await.unwrap().unwrap();
        let col_b = cards::get_column(&pool, &updated_b.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col_b.state_binding.as_deref(),
            Some("in_progress"),
            "a goal dispatched mid-drain must be tracked and parked, not silently left \
             in_progress"
        );
    }

    /// Lane U / U3 (HARNESS_LOOP_LOG.md, "Lane G4 review" finding 3): the
    /// immediate park pass `CliSession::drain_dispatched_goals` runs when a
    /// SIGTERM/SIGINT interrupts the drain — no polling, no sleep, one
    /// snapshot. Pinned directly at this level (rather than through the
    /// actual `tokio::signal` wiring in `crates/goose-cli/src/session/mod.rs`)
    /// because raising a real signal from a unit test would race every other
    /// test in this binary over process-wide signal delivery.
    #[tokio::test]
    async fn park_dispatched_goals_now_parks_every_still_running_goal_immediately() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        let child_running = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: running".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let card_running = setup_goal_in_state(&pool, "in_progress", 0).await;
        attach_worker_session_to_card(&pool, &card_running.id, &child_running.id).await;

        let child_done = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: done".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let card_done = setup_goal_in_state(&pool, "complete", 0).await;
        attach_worker_session_to_card(&pool, &card_done.id, &child_done.id).await;

        let start = std::time::Instant::now();
        let summary = park_dispatched_goals_now(&pool, &coordinator.id)
            .await
            .unwrap();
        assert!(
            start.elapsed() < std::time::Duration::from_secs(1),
            "must not poll or sleep: took {:?}",
            start.elapsed()
        );
        assert_eq!(
            summary,
            DrainSummary {
                finished: 1,
                timed_out: 1
            }
        );

        let updated = cards::get_card(&pool, &card_running.id)
            .await
            .unwrap()
            .unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "a running goal must be parked immediately on a shutdown signal, not left \
             in_progress"
        );
    }

    /// R31b-b (G28 review, MEDIUM-1): `park_dispatched_goals_now` re-derives
    /// card state fresh and, before this fix, called `handle_goal_timeout`
    /// unconditionally for every non-terminal card — the same gap as the
    /// drain's cap-expiry pass, just reached over SIGTERM instead of a cap.
    /// A card whose completion handler is already in flight must be left
    /// alone rather than force-parked out from under it.
    #[tokio::test]
    async fn park_dispatched_goals_now_skips_a_goal_whose_completion_is_in_flight() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let coordinator = sm
            .create_session(
                tmp.path().to_path_buf(),
                "coordinator".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        let child = sm
            .create_session_with_parent(
                Some(&coordinator.id),
                tmp.path().to_path_buf(),
                "Goal: wedged".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let card = setup_goal_in_state(&pool, "in_progress", 0).await;
        attach_worker_session_to_card(&pool, &card.id, &child.id).await;

        let guard = CompletionInFlight::begin(&card.id);
        let summary = park_dispatched_goals_now(&pool, &coordinator.id)
            .await
            .unwrap();
        assert_eq!(
            summary,
            DrainSummary {
                finished: 0,
                timed_out: 0
            },
            "an in-flight goal must be neither finished nor force-parked by this sweep"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "the SIGTERM park sweep must never force-park a goal whose completion handler is \
             still running"
        );
        assert!(updated.metadata_json.get("salvage_attempted").is_none());

        drop(guard);
    }

    #[tokio::test]
    async fn dispatch_goal_fn_is_callable_without_a_client() {
        // #213: the dispatch pipeline is a free function — no OrchestratorClient
        // (and no resume/sweep spawn) required. A goal that is not in Ready must
        // be rejected by the extracted seam exactly as the method did.
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        // A goal sitting in Review (not Ready) must not dispatch.
        let card = setup_goal_in_state(&pool, "review", 0).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let probe_cache = ProbeCache::new();

        let err = dispatch_goal_fn(&context, &probe_cache, &card.id, None, None)
            .await
            .expect_err("a non-Ready goal must not dispatch");
        assert!(
            err.contains("not 'ready'"),
            "the free seam must reject a non-Ready goal: {}",
            err
        );

        // Card did not move out of Review.
        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(col.state_binding.as_deref(), Some("review"));
    }

    /// H1 (G8 review, harness loop Lane E3 2026-09-10), G8's own pinning
    /// test 3: "dispatch with no known working dir → refused, not
    /// current_dir". Before this lane, a project with no `root_path` and no
    /// attached session fell back to `std::env::current_dir()` — under
    /// `cargo test` that is THIS repo's own checkout (see
    /// `init_git_repo_for_dispatch_test`'s own doc comment, found live
    /// while writing an earlier test in this same file) — and dispatch
    /// would have proceeded to isolate a REAL worktree under it. Pre-fix,
    /// this call would succeed (or fail for some unrelated reason far
    /// downstream, having already used the wrong directory); this asserts
    /// it refuses immediately, honestly, and leaves the card untouched.
    #[tokio::test]
    async fn dispatch_goal_fn_refuses_when_no_working_directory_is_known_never_falls_back_to_current_dir(
    ) {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        // The default `personal` project this fixture dispatches onto has
        // `root_path` NULL (the same seed Lane F8/D1's forensics traced this
        // whole hazard class to) and no `context.session` is attached — so
        // neither of the two legitimate sources this fix consults can
        // resolve a working directory.
        let card = setup_goal_in_state(&pool, "ready", 0).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let probe_cache = ProbeCache::new();

        let err = dispatch_goal_fn(&context, &probe_cache, &card.id, None, None)
            .await
            .expect_err("dispatch must refuse rather than silently use the daemon's cwd");
        assert!(
            err.contains("no working directory is known"),
            "the refusal must say why, not just fail: {err}"
        );
        assert!(
            err.contains("refusing to fall back to the daemon's own current directory"),
            "the refusal must name the specific fallback it is declining, not merely fail for \
             some unrelated downstream reason: {err}"
        );

        // Every other refusal in `dispatch_goal_fn` leaves the card in Ready
        // with no metadata changes — this one must be no different.
        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("ready"),
            "a refused dispatch must never move the card out of Ready"
        );
        assert!(
            updated.metadata_json.get("worker_key").is_none(),
            "no worker was ever selected against a real working directory, so no worker_key \
             may be recorded"
        );
    }

