    // ── Harness loop, Lane V (V1): land on completion in headless Auto ──────

    fn git_v1(root: &std::path::Path, args: &[&str]) -> String {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(root)
            .args(args)
            .output()
            .expect("git must be on PATH for this test");
        assert!(
            out.status.success(),
            "git {args:?} failed: {}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout).trim().to_string()
    }

    /// A trunk on `main` and a `goal/<run_id>` branch one commit ahead of it
    /// — the exact shape `goal_landing::land` fast-forwards, mirroring
    /// `decisions_effects::tests::repo_with_finished_goal_branch`. Returns
    /// (repo root, the branch's head commit).
    fn v1_repo_with_finished_goal_branch(run_id: &str) -> (tempfile::TempDir, String) {
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        git_v1(root, &["init", "-b", "main"]);
        git_v1(root, &["config", "user.email", "test@example.com"]);
        git_v1(root, &["config", "user.name", "Test"]);
        git_v1(root, &["config", "commit.gpgsign", "false"]);
        std::fs::write(root.join("README.md"), "base\n").unwrap();
        git_v1(root, &["add", "-A"]);
        git_v1(root, &["commit", "-m", "base"]);
        let branch = format!("goal/{run_id}");
        git_v1(root, &["checkout", "-b", &branch]);
        std::fs::write(root.join("work.txt"), "the goal's work\n").unwrap();
        git_v1(root, &["add", "-A"]);
        git_v1(root, &["commit", "-m", "the work"]);
        let head = git_v1(root, &["rev-parse", "HEAD"]);
        git_v1(root, &["checkout", "main"]);
        (dir, head)
    }

    /// The `dispatch_evidence` shape the real completion tracker persists
    /// (`cards::set_goal_dispatch_evidence`) BEFORE calling
    /// `handle_goal_completion`, for a worker whose worktree directory name
    /// is `run_id` (so `goal_landing::land_request_from_metadata` derives
    /// branch `goal/<run_id>`, matching [`v1_repo_with_finished_goal_branch`]).
    async fn v1_stamp_dispatch_evidence(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        card_id: &str,
        run_id: &str,
        head_commit: &str,
    ) {
        cards::set_goal_dispatch_evidence(
            pool,
            card_id,
            serde_json::json!({
                "worktree_path": format!("/tmp/.permagent-goal-worktrees/{run_id}"),
                "head_commit": head_commit,
                "commits": ["abc123 the work"],
                "baseline_commit": "0000000000000000000000000000000000000000",
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
                "diffstat": " work.txt | 1 +\n",
                "worker_summary": "did the work",
            }),
        )
        .await
        .unwrap();
    }

    /// V1 positive: a headless Auto goal whose worker session produced a
    /// real, durable verifier pass lands with NO human ever touching the
    /// Decision Inbox — the working directory's HEAD advances to the
    /// worker's commit, exactly as the brief's contract requires.
    /// The `approve_review` decision `handle_goal_completion` would have
    /// filed for a card already in Review — created directly so this test
    /// exercises `auto_land_headless_goal` in isolation, decoupled from the
    /// pre-existing (unrelated) `maybe_hold_review`/`decide_hold` gate that
    /// `handle_goal_completion` also runs: that gate ALWAYS holds/parks a
    /// first-attempt completion with no verify pass rather than ever letting
    /// it reach Review at all (`cost_router::hold_done::decide_hold` grants
    /// `Allow` only when `verify_ran`), so driving the full
    /// `handle_goal_completion` flow can never actually produce the "reached
    /// Review with no verifier pass" case V1's own gate additionally guards.
    async fn v1_review_decision(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        card_id: &str,
    ) -> decisions::Decision {
        v2_review_decision(pool, card_id, None).await
    }

    /// V2: same fixture as [`v1_review_decision`], with an optional
    /// `minting_session_id` stamped into the payload — the field
    /// `orchestrator::handle_goal_completion` writes when it files a
    /// decision under a headless auto-land policy, and the ONLY thing
    /// `goal_transition::check_proof`'s Tier-1 arm will ever accept an
    /// `ACTOR_AUTO_LAUNCH` proof against.
    async fn v2_review_decision(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        card_id: &str,
        minting_session_id: Option<&str>,
    ) -> decisions::Decision {
        let payload = match minting_session_id {
            Some(session_id) => serde_json::json!({ "minting_session_id": session_id }),
            None => serde_json::json!({}),
        };
        decisions::create_decision(
            pool,
            decisions::NewDecision {
                kind: "approve_review".to_string(),
                goal_id: Some(card_id.to_string()),
                project_id: Some(crate::projects::PERSONAL_PROJECT_ID.to_string()),
                headline: Some("Review the finished work".to_string()),
                detail: Some("evidence".to_string()),
                payload,
                ..Default::default()
            },
        )
        .await
        .unwrap()
    }

    // Harness loop, Lane V (V1) found landing refused by a SEPARATE,
    // pre-existing tier gate it did not touch — `goal_transition::check_proof`'s
    // Tier-1 arm hardcoded `acted_by` to `ACTOR_JESSE`/`ACTOR_HENRY` and did
    // not accept `ACTOR_AUTO_LAUNCH`. Jesse ruled (HARNESS_LOOP_LOG.md
    // "JESSE RULING (2026-09-08 23:55): Tier-1 landing → option 3") for a
    // policy switch, default off: `PERMAGENT_HEADLESS_AUTOLAND`. Lane V2
    // implements it (`auto_land_allowed`/`calling_session_id` threaded into
    // `check_proof` via `advance_goal_checked_with_auto_land`) and un-ignores
    // this test, which now exercises the positive case with the switch on
    // and a matching minting session.
    #[tokio::test]
    async fn headless_auto_land_lands_a_goal_with_a_durable_verifier_pass() {
        let (repo, head) = v1_repo_with_finished_goal_branch("v1-land-run");
        let root = repo.path().to_string_lossy().into_owned();

        let pool = test_pool().await;
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(&root)
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        v1_stamp_dispatch_evidence(&pool, &card.id, "v1-land-run", &head).await;
        stamp_successful_verify(&pool, &card.id).await;
        let decision = v2_review_decision(&pool, &card.id, Some("coord-session-1")).await;
        // Re-fetch: `stamp_successful_verify` stamped `worker_session_id`
        // onto the card row AFTER `card` above was captured, and
        // `auto_land_headless_goal` (like the real completion tracker's own
        // `handle_goal_completion`, which always fetches its `card` AFTER
        // dispatch already stamped `worker_session_id`) reads that field off
        // the `cards::Card` it is GIVEN rather than re-querying — passing the
        // stale snapshot here would make it see no worker session at all.
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        auto_land_headless_goal(&pool, &decision.id, &card, true, Some("coord-session-1")).await;

        assert_eq!(
            git_v1(repo.path(), &["rev-parse", "HEAD"]),
            head,
            "headless Auto completion with a durable verifier pass must fast-forward the \
             working directory onto the worker's commit with no human answer"
        );
        assert!(
            repo.path().join("work.txt").exists(),
            "the worker's file must be present in the working directory after auto-landing"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("complete"),
            "an auto-landed goal must reach Complete, not sit in Review"
        );
        assert_eq!(
            updated
                .metadata_json
                .pointer("/dispatch_evidence/verdict/status")
                .and_then(|v| v.as_str()),
            Some("pass"),
            "the auto-land receipt must be durably recorded on the card"
        );

        let d = decisions::find_open_decision_for_goal(&pool, &card.id, "approve_review")
            .await
            .unwrap();
        assert!(
            d.is_none(),
            "the approve_review decision must be resolved (answered), not left open"
        );
    }

    /// V1 negative: a goal in Review with no durable verifier pass in its
    /// worker session must NOT be landed. Y10b: under auto-land the refusal
    /// is now SAID — the card is parked with an `unblock` naming it — rather
    /// than left in Review behind a decision a headless run cannot answer.
    #[tokio::test]
    async fn headless_auto_land_does_not_land_a_goal_with_no_verifier_pass() {
        let (repo, head) = v1_repo_with_finished_goal_branch("v1-noland-run");
        let root = repo.path().to_string_lossy().into_owned();

        let pool = test_pool().await;
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(&root)
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        v1_stamp_dispatch_evidence(&pool, &card.id, "v1-noland-run", &head).await;
        // Deliberately no `stamp_successful_verify` — the worker never ran an
        // authoritative `verify` pass.
        let decision = v1_review_decision(&pool, &card.id).await;

        auto_land_headless_goal(&pool, &decision.id, &card, true, Some("coord-session-1")).await;

        assert_ne!(
            git_v1(repo.path(), &["rev-parse", "HEAD"]),
            head,
            "with no durable verifier pass, the working directory must NOT advance"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "Y10b: an unverified completion is parked, never advanced to Complete"
        );

        let d = decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
            .await
            .unwrap()
            .expect("Y10b: the refusal must raise an answerable unblock decision");
        assert_eq!(d.status, "open");
        assert!(
            d.detail.contains("no verify evidence"),
            "the unblock detail must name the refusal, got {:?}",
            d.detail
        );
        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "approve_review")
                .await
                .unwrap()
                .is_none(),
            "the moot approve_review must be superseded, not left open and unanswerable"
        );
        let answered = decisions::get_decision(&pool, &decision.id)
            .await
            .unwrap()
            .expect("the approve_review row still exists");
        assert_eq!(
            answered.status, "superseded",
            "superseded, never answered — the refusal stands"
        );
        assert!(
            answered.acted_by.is_none(),
            "an unverified completion must never be auto-approved"
        );
    }

    // ── Lane R29b (A28 Miss 3): the read-only auto-land shortcut must ───────
    // refuse a goal whose branch still carries unlanded commits.

    /// The A28 Miss 3 shape, reconstructed: a card carries a `read_only_review`
    /// receipt (as a later, zero-progress session's own rolling baseline made
    /// it look genuinely read-only), but the goal branch itself — measured
    /// against the real trunk, not that session's rolling baseline — still
    /// has a real, unlanded commit. `auto_land_headless_goal` must NOT record
    /// `status: "read_only"` in that case; it must leave an audit trail
    /// naming the refusal and route the goal through the ordinary
    /// salvage/verify/land path instead.
    #[tokio::test]
    async fn read_only_auto_land_refuses_when_the_goal_branch_has_unlanded_commits() {
        let pool = test_pool().await;
        let (trunk, goal_dir, base_sha, fix_sha) =
            r22d_trunk_and_goal_worktree("r29b-readonly-unlanded");

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                "head_commit": fix_sha,
                "commits": [],
                // The rolling baseline a later, zero-progress session would
                // have recorded: it equals the branch tip (nothing further
                // was committed on top), which is exactly why that session's
                // own `worktree_mutated` check read clean and left a
                // `read_only_review` receipt in the first place.
                "baseline_commit": fix_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                "read_only_review".to_string(),
                serde_json::json!({
                    "report": "x".repeat(60),
                    "landed_notes": "no change (read-only review)",
                    "recorded_at": chrono::Utc::now().to_rfc3339(),
                }),
            );
        })
        .await
        .unwrap();
        let decision = v1_review_decision(&pool, &card.id).await;
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        auto_land_headless_goal(&pool, &decision.id, &card, true, Some("coord-session-1")).await;

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_ne!(
            updated
                .metadata_json
                .pointer("/dispatch_evidence/verdict/status")
                .and_then(|v| v.as_str()),
            Some("read_only"),
            "a goal branch with unlanded commits must never be landed as a no-op read-only \
             review — the real, already-committed fix would be stranded"
        );

        let outcomes = salvage_audit_outcomes(&pool, &card.id).await;
        assert!(
            outcomes
                .iter()
                .any(|o| o == "read_only_landing_refused_unlanded_commits=1"),
            "expected a read_only_landing_refused_unlanded_commits audit row, got {outcomes:?}"
        );

        // The trunk's own base commit must be unaffected either way — this
        // test asserts the read-only shortcut was refused, not that salvage
        // itself lands the work (that mechanism is covered by the R20b/R22d
        // salvage tests).
        assert_eq!(
            git_v1(trunk.path(), &["rev-parse", "HEAD"]),
            base_sha,
            "sanity: the trunk fixture itself is unmodified by this test's setup"
        );
    }

    /// Counterpart: when the goal branch's tip is ALREADY an ancestor of the
    /// real trunk (nothing unlanded — the ordinary case, e.g. an earlier
    /// attempt's fix already landed, or the goal genuinely never committed
    /// anything), the new guard must not misfire; the read-only receipt
    /// still lands the ordinary way. Uses a real trunk resolution (not just
    /// an unresolvable-worktree fallback) so this actually exercises
    /// `commits_unlanded_at_trunk`'s `Ok((0, _))` arm.
    #[tokio::test]
    async fn read_only_auto_land_still_lands_when_nothing_is_unlanded_at_trunk() {
        let pool = test_pool().await;
        let run_id = "r29b-readonly-already-landed";
        let (trunk, goal_dir, base_sha, fix_sha) = r22d_trunk_and_goal_worktree(run_id);
        // Simulate the fix already having reached trunk (an earlier
        // salvage, or a human's own merge) — the goal branch's tip is now
        // an ancestor of trunk's HEAD, so nothing is left unlanded. `trunk`
        // and `goal_dir` are separate clones with separate object stores
        // (see `r22d_trunk_and_goal_worktree`), so the fix commit's objects
        // have to be fetched in before trunk can fast-forward onto it.
        let branch = format!("goal/{run_id}");
        let goal_dir_str = goal_dir.path().to_string_lossy().into_owned();
        r20b_git(trunk.path(), &["fetch", "-q", &goal_dir_str, &branch]);
        r20b_git(trunk.path(), &["merge", "--ff-only", "-q", "FETCH_HEAD"]);
        assert_eq!(
            git_v1(trunk.path(), &["rev-parse", "HEAD"]),
            fix_sha,
            "sanity: the trunk fixture must have fast-forwarded onto the fix"
        );

        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(trunk.path().to_string_lossy().as_ref())
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": goal_dir.path().to_string_lossy(),
                "head_commit": fix_sha,
                "commits": [],
                "baseline_commit": base_sha,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                "read_only_review".to_string(),
                serde_json::json!({
                    "report": "x".repeat(60),
                    "landed_notes": "no change (read-only review)",
                    "recorded_at": chrono::Utc::now().to_rfc3339(),
                }),
            );
        })
        .await
        .unwrap();
        let decision = v1_review_decision(&pool, &card.id).await;
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        auto_land_headless_goal(&pool, &decision.id, &card, true, Some("coord-session-1")).await;

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .pointer("/dispatch_evidence/verdict/status")
                .and_then(|v| v.as_str()),
            Some("read_only"),
            "a goal with nothing unlanded at trunk must still take the ordinary read-only \
             auto-land path"
        );

        let outcomes = salvage_audit_outcomes(&pool, &card.id).await;
        assert!(
            outcomes
                .iter()
                .all(|o| o != "read_only_landing_refused_unlanded_commits=1"),
            "must not refuse a goal with nothing unlanded, got {outcomes:?}"
        );
    }

    /// Y10b's own boundary: OUTSIDE a headless auto-land run there IS a human
    /// on the other end of the `approve_review`, so the refusal must behave
    /// exactly as it did before — decision open, card still in Review, no
    /// park.
    #[tokio::test]
    async fn a_refusal_without_auto_land_leaves_the_approve_review_open() {
        let (repo, head) = v1_repo_with_finished_goal_branch("v1-noautoland-run");
        let root = repo.path().to_string_lossy().into_owned();

        let pool = test_pool().await;
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(&root)
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        v1_stamp_dispatch_evidence(&pool, &card.id, "v1-noautoland-run", &head).await;
        stamp_vacuous_verify_exchange(&pool, &card.id).await;
        let decision = v2_review_decision(&pool, &card.id, Some("coord-session-1")).await;
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        auto_land_headless_goal(&pool, &decision.id, &card, false, Some("coord-session-1")).await;

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("review"),
            "with auto-land off the card stays in Review for its human reviewer"
        );
        let d = decisions::find_open_decision_for_goal(&pool, &card.id, "approve_review")
            .await
            .unwrap()
            .expect("the approve_review decision must remain open for a human");
        assert_eq!(d.status, "open");
        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
                .await
                .unwrap()
                .is_none(),
            "no park, so no unblock — Y10b must not fire outside a headless auto-land run"
        );
    }

    /// G5 finding 1: a goal whose worker session's ONLY verify pass is
    /// vacuous (a smoke-only or zero-tests PASS — authoritative on the wire,
    /// but not real coverage) must be refused exactly like the no-pass-at-all
    /// case above: the working directory must not advance, the decision
    /// stays open for a human, and — unlike the no-pass case — a durable
    /// receipt naming the reason is recorded on the card so a reviewer sees
    /// why headless landing declined to act.
    #[tokio::test]
    async fn headless_auto_land_does_not_land_a_goal_with_only_a_vacuous_verifier_pass() {
        let (repo, head) = v1_repo_with_finished_goal_branch("v1-vacuous-noland-run");
        let root = repo.path().to_string_lossy().into_owned();

        let pool = test_pool().await;
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(&root)
            .bind(crate::projects::PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = setup_goal_in_state(&pool, "review", 1).await;
        v1_stamp_dispatch_evidence(&pool, &card.id, "v1-vacuous-noland-run", &head).await;
        stamp_vacuous_verify_exchange(&pool, &card.id).await;
        let decision = v2_review_decision(&pool, &card.id, Some("coord-session-1")).await;
        // Re-fetch for the same reason the positive landing test does: the
        // vacuous-verify stamp above set `worker_session_id` on the card row
        // AFTER `card` was captured.
        let card = cards::get_card(&pool, &card.id).await.unwrap().unwrap();

        auto_land_headless_goal(&pool, &decision.id, &card, true, Some("coord-session-1")).await;

        assert_ne!(
            git_v1(repo.path(), &["rev-parse", "HEAD"]),
            head,
            "with only a vacuous verifier pass, the working directory must NOT advance"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("failed"),
            "Y10b: a vacuous-only completion is parked, never advanced to Complete"
        );

        assert_eq!(
            updated
                .metadata_json
                .pointer("/dispatch_evidence/verdict/status")
                .and_then(|v| v.as_str()),
            Some("vacuous"),
            "the refusal must leave a durable receipt on the card"
        );
        let reason = updated
            .metadata_json
            .pointer("/dispatch_evidence/verdict/reason")
            .and_then(|v| v.as_str())
            .unwrap_or_default();
        assert!(
            reason.starts_with("verify pass was vacuous: "),
            "the receipt must name the vacuous reason, got {reason:?}"
        );

        // Y10b: the run summary must be able to say WHY, so the refusal parks
        // with an unblock that names it — M15 fx03/fx10/zai fx01 all exited
        // with nothing but the drain's generic "still running at exit".
        let d = decisions::find_open_decision_for_goal(&pool, &card.id, "unblock")
            .await
            .unwrap()
            .expect("Y10b: the refusal must raise an answerable unblock decision");
        assert_eq!(d.status, "open");
        assert!(
            d.detail.contains("vacuous"),
            "the unblock detail must name the vacuous verify, got {:?}",
            d.detail
        );
        assert_eq!(
            updated
                .metadata_json
                .get("last_error")
                .and_then(|v| v.as_str())
                .map(|e| e.contains("vacuous verify")),
            Some(true),
            "the parked card's last_error must name the refusal too"
        );
        assert!(
            decisions::find_open_decision_for_goal(&pool, &card.id, "approve_review")
                .await
                .unwrap()
                .is_none(),
            "the moot approve_review must be superseded, not left open and unanswerable"
        );
        let answered = decisions::get_decision(&pool, &decision.id)
            .await
            .unwrap()
            .expect("the approve_review row still exists");
        assert_eq!(answered.status, "superseded");
        assert!(
            answered.acted_by.is_none(),
            "a vacuous-only completion must never be auto-approved"
        );
    }

