    /// `goal_advance action="dispatch"` used to be a bare column move. It
    /// answered "Goal 'X' advanced: ready → in_progress" while selecting no
    /// worker, spawning no process and writing no execution receipt — so the
    /// orchestrator believed it had assigned work that nothing was doing, and
    /// the goal sat InProgress until a sweep reclaimed it as abandoned.
    ///
    /// The part with teeth is the S4 budget gate: the real pipeline parks a
    /// goal that is out of attempts, and the bare transition walked straight
    /// past it. This test pins that gate, because it can be asserted without
    /// an installed CLI, a git worktree or a provider — an exhausted goal
    /// fails before worker selection is ever reached.
    #[tokio::test]
    async fn tool_path_dispatch_runs_the_pipeline_not_a_bare_transition() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();

        // Ready, but already past DEFAULT_ATTEMPT_CAP.
        let card = setup_goal_in_state(&pool, "ready", 99).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        args.insert("action".to_string(), serde_json::json!("dispatch"));

        let err = client
            .handle_goal_advance(Some(args))
            .await
            .expect_err("an exhausted goal must not dispatch via the tool path");
        assert!(
            err.contains("not dispatched"),
            "the budget gate must refuse the dispatch: {err}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "dispatch must never report progress it did not start"
        );
        assert!(
            updated.metadata_json.get("worker_key").is_none(),
            "no worker ran, so no worker_key may be recorded"
        );
    }

    // ── Lane R22a: goal_advance enforces check_worker before dispatch ──────

    /// A Ready goal with NO prior `check_worker` on file for the worker this
    /// dispatch would use: `ensure_worker_checked_for_dispatch` must perform
    /// the check itself and record it, rather than silently trusting an
    /// unchecked worker. `permagent` is the always-merged-in default worker
    /// (`agent_identity::merge_missing_default_workers`, `availability_check:
    /// "always"`), so this is deterministic regardless of the local
    /// machine's own agent.yaml.
    #[tokio::test]
    async fn goal_advance_dispatch_performs_a_missing_check_worker_and_records_it() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 1).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        assert!(
            client.checked_workers_this_session.lock().await.is_empty(),
            "a fresh session must start with nothing checked"
        );

        client
            .ensure_worker_checked_for_dispatch(&card, Some("permagent"))
            .await
            .expect("permagent is always available — the check must succeed");

        assert!(
            client
                .checked_workers_this_session
                .lock()
                .await
                .contains("permagent"),
            "the internal check must record itself exactly as a real check_worker call would"
        );
    }

    /// A worker already checked earlier THIS session must not be re-probed.
    /// Proven by pre-recording a key that does not resolve in agent.yaml at
    /// all: if `ensure_worker_checked_for_dispatch` repeated the check it
    /// would call `check_worker_core`, which errors for an unknown worker —
    /// so an `Ok` here is only possible if the prior record short-circuited
    /// the check entirely.
    #[tokio::test]
    async fn goal_advance_dispatch_does_not_repeat_a_check_worker_already_on_file() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 1).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let bogus_key = "r22a-not-a-real-roster-key";
        client.record_check_worker(bogus_key).await;

        client
            .ensure_worker_checked_for_dispatch(&card, Some(bogus_key))
            .await
            .expect(
                "a worker already recorded as checked this session must short-circuit, \
                 even though it does not resolve in agent.yaml at all",
            );
    }

    /// No capable worker on file (fresh session, worker unknown to
    /// agent.yaml): the gate must refuse with a structured, named error and
    /// must NOT record a check that never actually resolved a worker.
    #[tokio::test]
    async fn goal_advance_dispatch_refuses_with_a_structured_error_when_no_capable_worker() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 1).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let bogus_key = "r22a-still-not-a-real-roster-key";
        let err = client
            .ensure_worker_checked_for_dispatch(&card, Some(bogus_key))
            .await
            .expect_err("an unknown worker must refuse, not silently pass");
        assert!(
            err.contains(bogus_key),
            "the refusal must name the worker it checked: {err}"
        );

        assert!(
            !client
                .checked_workers_this_session
                .lock()
                .await
                .contains(bogus_key),
            "a worker whose check itself failed must not be recorded as checked"
        );
    }

    /// End-to-end through the public tool path: `goal_advance{action:
    /// dispatch}` on a Ready goal, requesting a worker that does not exist,
    /// must refuse BEFORE moving the card — never a half-dispatch.
    #[tokio::test]
    async fn tool_path_dispatch_refuses_before_moving_the_card_when_the_worker_check_fails() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let card = setup_goal_in_state(&pool, "ready", 1).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        args.insert("action".to_string(), serde_json::json!("dispatch"));
        args.insert(
            "worker".to_string(),
            serde_json::json!("r22a-not-a-real-roster-key-e2e"),
        );

        let err = client
            .handle_goal_advance(Some(args))
            .await
            .expect_err("dispatching to an unchecked, unknown worker must be refused");
        assert!(
            err.contains("r22a-not-a-real-roster-key-e2e"),
            "the refusal must name the worker: {err}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("ready"),
            "a refused pre-dispatch worker check must leave the card exactly where it was"
        );
        assert!(
            updated.metadata_json.get("worker_key").is_none(),
            "no worker was ever selected, so none may be recorded"
        );
    }

    // ── Lane R25a: goal_advance/check_worker resolve the project's single
    // Ready/In Progress card by cwd when card_id/worker_key is omitted;
    // goal_list makes cards discoverable (Lane K12's finding: a seeded Ready
    // goal card is in the store with the right project root_path, but
    // neither tool had any way to discover its id) ──

    /// Seed a project rooted at `working_dir` with one goal card in
    /// `state_binding`, returning `(project, card)`. `working_dir` must
    /// exist on disk (`create_project` requires it).
    async fn setup_project_and_goal_at(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        name: &str,
        working_dir: &std::path::Path,
        state_binding: &str,
        title: &str,
    ) -> (crate::projects::Project, cards::Card) {
        let project = crate::projects::create_project(
            pool,
            crate::projects::CreateProject {
                name: name.to_string(),
                root_path: Some(working_dir.to_string_lossy().into_owned()),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        cards::seed_goal_columns(pool, &project.id).await.unwrap();
        let col = cards::get_goal_column(pool, &project.id, state_binding)
            .await
            .unwrap()
            .unwrap();
        let card = cards::create_card(
            pool,
            cards::CreateCard {
                project_id: project.id.clone(),
                title: title.to_string(),
                description: Some("test".to_string()),
                card_type: Some("goal".to_string()),
                column_id: Some(col.id.clone()),
                created_by: None,
                metadata_json: None,
            },
        )
        .await
        .unwrap();
        (project, card)
    }

    /// `goal_advance` with NO `card_id`, exactly one Ready card for the cwd
    /// project: the omitted argument resolves to that card and the request
    /// reaches real dispatch machinery — proven by hitting R22a's
    /// enforced check_worker gate FOR THE RESOLVED CARD (a bogus worker key
    /// refusal, the same deterministic assertion
    /// `tool_path_dispatch_refuses_before_moving_the_card_when_the_worker_check_fails`
    /// uses) rather than a "no card_id"/"ambiguous" resolution error. A real
    /// end-to-end worker spawn is out of scope here — nothing else in this
    /// file drives `dispatch_goal_fn` to a real success either (it needs a
    /// real git worktree and agent process); this proves the NEW behavior
    /// this lane adds (resolution) without re-testing R22a's or
    /// `dispatch_goal_fn`'s own already-covered machinery.
    #[tokio::test]
    async fn goal_advance_without_card_id_resolves_the_single_ready_card_before_dispatch() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(crate::session::SessionManager::new(
            tmp.path().to_path_buf(),
        ));
        let pool = sm.pool_clone().await.unwrap();
        let (_project, _card) = setup_project_and_goal_at(
            &pool,
            "R25a Single Ready",
            tmp.path(),
            "ready",
            "Rename widget-cli",
        )
        .await;

        let session = sm
            .create_session(
                tmp.path().to_path_buf(),
                "r25a-goal-advance".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: Some(Arc::new(session)),
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("action".to_string(), serde_json::json!("dispatch"));
        args.insert(
            "worker".to_string(),
            serde_json::json!("r25a-not-a-real-roster-key"),
        );
        // Deliberately no "card_id".

        let err = client
            .handle_goal_advance(Some(args))
            .await
            .expect_err("an unknown worker must still refuse even once the card resolves");
        assert!(
            err.contains("r25a-not-a-real-roster-key"),
            "reaching the worker-check refusal (not a card-resolution error) proves the \
             omitted card_id resolved to the seeded Ready card: {err}"
        );
    }

