    #[test]
    fn ground_acceptance_criteria_behaviourally_is_a_no_op_when_already_behavioural() {
        let mut criteria = vec![
            "`python -m logfilter --level BOGUS sample_logs/app.log` exits with code 2".to_string(),
        ];
        let before = criteria.clone();
        let (behavioural_added, existence_only) =
            ground_acceptance_criteria_behaviourally(&mut criteria, LOGFILTER_TASK_PROMPT, None);
        assert!(!behavioural_added);
        assert!(!existence_only);
        assert_eq!(criteria, before);
    }

    #[test]
    fn ground_roadmap_goals_records_ac_grounding_behavioural_added_in_the_receipts() {
        let facts = RepoFacts {
            manifests: vec!["setup.py".to_string()],
            files: vec!["logfilter/cli.py".to_string()],
            file_count: 5,
            check_commands: vec![],
            ..Default::default()
        };
        let goals = vec![goal_state::ProposedGoal {
            title: "Fix argument validation".to_string(),
            description: LOGFILTER_TASK_PROMPT.to_string(),
            acceptance_criteria: a38_miss1_existence_only_criteria(),
            tags: vec![],
            depends_on: vec![],
        }];
        let (grounded, receipts) =
            ground_roadmap_goals(goals, &facts, &std::collections::BTreeSet::new(), None);
        assert!(
            receipts
                .iter()
                .any(|r| r.contains("ac_grounding behavioural_added=1")),
            "receipts: {receipts:?}"
        );
        assert_eq!(
            classify_acceptance_criterion(grounded[0].acceptance_criteria.last().unwrap()),
            AcKind::Behavioural
        );
    }

    /// End-to-end at the `ground_roadmap_goals` entry point: a goal whose
    /// task text's only concrete sentence is a bare absolute-path edit
    /// instruction gets no derived AC, and the receipt records WHY
    /// (`reason=no_behavioural_sentence`) rather than silently doing
    /// nothing.
    #[test]
    fn ground_roadmap_goals_tags_existence_only_and_records_the_reason_for_a_bare_path_sentence() {
        let facts = RepoFacts {
            manifests: vec!["setup.py".to_string()],
            files: vec!["src/foo.py".to_string()],
            file_count: 1,
            check_commands: vec![],
            ..Default::default()
        };
        let goals = vec![goal_state::ProposedGoal {
            title: "Tweak foo".to_string(),
            description: "edit /Users/x/ws/src/foo.py".to_string(),
            acceptance_criteria: vec!["src/foo.py exists".to_string()],
            tags: vec![],
            depends_on: vec![],
        }];
        let (grounded, receipts) =
            ground_roadmap_goals(goals, &facts, &std::collections::BTreeSet::new(), None);
        assert_eq!(
            grounded[0].acceptance_criteria,
            vec!["src/foo.py exists".to_string()],
            "no AC should have been derived from a bare path sentence"
        );
        assert!(
            receipts
                .iter()
                .any(|r| r
                    .contains("ac_grounding behavioural_added=0 reason=no_behavioural_sentence")),
            "receipts: {receipts:?}"
        );
    }

    /// Priority ordering: a criterion that reads as BOTH a symbol claim and
    /// a bare file-existence claim ("class Foo exists in src/bar.py")
    /// resolves to the more specific `symbol_defined` shape, not
    /// `file_exists`.
    #[test]
    fn classify_probe_shape_prefers_symbol_defined_over_file_exists() {
        let shape = classify_probe_shape("class Foo exists in src/bar.py").unwrap();
        assert_eq!(
            shape,
            ProbeShape::SymbolDefined {
                path: "src/bar.py".to_string(),
                symbol: "Foo".to_string(),
                kind: "class".to_string(),
            }
        );
    }

    /// A criterion that fits none of the three probe shapes (a file
    /// reference with no exist/symbol/command claim) still yields no probe
    /// classification -- confirming the fallback to plain `UNVERIFIED`
    /// above is reached honestly, not because the classifier over-fires.
    #[test]
    fn classify_probe_shape_is_none_for_a_plain_content_claim() {
        assert_eq!(
            classify_probe_shape("src/does_not_exist.rs contains the fix"),
            None
        );
    }

    /// R21b Tests bullet 4: free text naming no specific check or file is
    /// left alone — not everything is a command, and a criterion with no
    /// named claim can never be "ungrounded" in the R21b sense.
    #[test]
    fn ungrounded_named_criteria_leaves_free_text_alone() {
        let facts = RepoFacts::default();
        let goals = vec![goal(
            "Polish copy",
            "improve the error text",
            &["the error message is friendly and non-technical"],
            &[],
        )];
        assert!(ungrounded_named_criteria_in_goals(&goals, &facts).is_empty());
    }

    /// An AC already wearing Z1's own `UNVERIFIED (...)` marker (decompose-
    /// time grounding already gave up honestly and asked for human review)
    /// must never be re-flagged here — that would just second-guess Z1's
    /// own, already-honest output.
    #[test]
    fn ungrounded_named_criteria_exempts_z1s_own_unverified_marker() {
        let facts = RepoFacts::default();
        let goals = vec![goal(
            "Polish copy",
            "improve the error text",
            &[
                "UNVERIFIED (no detected check command in this repo) — kept for human review: \
               grep -q 'class Foo' src/bar.py",
            ],
            &[],
        )];
        assert!(ungrounded_named_criteria_in_goals(&goals, &facts).is_empty());
    }

    /// End-to-end (A21 Q1 repair, direct): `create_roadmap` must
    /// independently validate acceptance criteria against what this repo
    /// can actually check, not just trust that `decompose_roadmap` already
    /// ran — a caller-supplied `goals_json` need not have gone through Z1's
    /// decompose-time grounding at all. First call: an AC naming a file
    /// this repo does not have is rejected with a structured error and no
    /// card is created. Second call for the SAME exact proposal: accepted,
    /// with the ungrounded criterion rewritten (never invented) and
    /// `ac_rewritten` recorded on the card for human review.
    #[tokio::test]
    async fn create_roadmap_rejects_then_rewrites_an_ac_naming_a_file_this_repo_lacks() {
        let (_tmp, sm, _session, _em, client) =
            roadmap_handler_fixture(GooseMode::Approve, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let goals = vec![goal_state::ProposedGoal {
            title: "Fix pricing".to_string(),
            description: "fix the pricing bug".to_string(),
            acceptance_criteria: vec![
                "src/pricing_missing_file.rs contains the rounding fix".to_string()
            ],
            tags: vec![],
            depends_on: vec![],
        }];
        let (hash, decision_id) =
            install_answered_roadmap_proof(&pool, crate::projects::PERSONAL_PROJECT_ID, &goals)
                .await;
        let goals_json = serde_json::to_string(&goals).unwrap();

        // First attempt: rejected, structured error, nothing materialized.
        let err = client
            .handle_create_roadmap(Some(create_roadmap_args(&goals_json, &hash, &decision_id)))
            .await
            .expect_err(
                "an AC naming a file this repo does not have must be rejected on the first \
                 attempt",
            );
        assert!(err.contains("rejected"));
        assert!(err.contains("src/pricing_missing_file.rs"));
        let cards: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM cards WHERE project_id = ? AND card_type = 'goal'",
        )
        .bind(crate::projects::PERSONAL_PROJECT_ID)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(
            cards, 0,
            "a rejected proposal must not materialize any card"
        );

        // Second attempt for the SAME exact proposal: accepted with a
        // rewrite, never a second rejection.
        let result = client
            .handle_create_roadmap(Some(create_roadmap_args(&goals_json, &hash, &decision_id)))
            .await
            .expect("the second attempt for the same proposal must be accepted with a rewrite");
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(text.contains("ac_rewritten") || text.contains("corrected"));

        let metadata: String = sqlx::query_scalar(
            "SELECT metadata_json FROM cards WHERE project_id = ? AND card_type = 'goal'",
        )
        .bind(crate::projects::PERSONAL_PROJECT_ID)
        .fetch_one(&pool)
        .await
        .unwrap();
        let metadata: serde_json::Value = serde_json::from_str(&metadata).unwrap();
        assert_eq!(metadata["ac_rewritten"], true);
        assert!(metadata["ac_rewritten_notes"][0]
            .as_str()
            .unwrap()
            .contains("src/pricing_missing_file.rs"));
        let rewritten_ac = metadata["acceptance_criteria"][0].as_str().unwrap();
        assert!(
            rewritten_ac.starts_with("UNVERIFIED"),
            "no check was detected in this tempdir repo, so the rewrite must be an honest \
             UNVERIFIED marker, never an invented check: {rewritten_ac}"
        );
    }

    #[tokio::test]
    async fn cross_project_approval_is_rejected_without_consuming_proof() {
        let pool = test_pool().await;
        let other = crate::projects::create_project(
            &pool,
            crate::projects::CreateProject {
                name: "Other roadmap project".to_string(),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        let goals = vec![
            goal_state::ProposedGoal {
                title: "Cross A".to_string(),
                description: "first".to_string(),
                acceptance_criteria: vec![],
                tags: vec![],
                depends_on: vec![],
            },
            goal_state::ProposedGoal {
                title: "Cross B".to_string(),
                description: "second".to_string(),
                acceptance_criteria: vec![],
                tags: vec![],
                depends_on: vec![0],
            },
        ];
        let hash = roadmap_proposal_hash(&goals);
        let decision = crate::decisions::create_decision(
            &pool,
            crate::decisions::NewDecision {
                kind: "choice".to_string(),
                project_id: Some(other.id),
                headline: Some("Approve this roadmap?".to_string()),
                detail: Some("Wrong project".to_string()),
                payload: serde_json::json!({
                    "question": "Create this exact roadmap?",
                    "options": [
                        {"id": "approve-roadmap", "label": "Approve and begin"},
                        {"id": "reject-roadmap", "label": "Reject"}
                    ],
                    "proposal": crate::decisions::PROPOSAL_ROADMAP_CREATE,
                    "roadmap_approval": {"proposal_hash": hash}
                }),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        crate::decisions::answer_decision(
            &pool,
            &decision.id,
            &crate::decisions::DecisionAnswer {
                answer: "choice".to_string(),
                choice_id: Some("approve-roadmap".to_string()),
                ..Default::default()
            },
            crate::decisions::ACTOR_JESSE,
        )
        .await
        .unwrap();
        let project = crate::projects::get_project(&pool, crate::projects::PERSONAL_PROJECT_ID)
            .await
            .unwrap()
            .unwrap();
        let mut metadata = project.metadata_json;
        metadata.as_object_mut().unwrap().insert(
            ROADMAP_PROPOSAL_METADATA_KEY.to_string(),
            serde_json::json!({
                "hash": hash,
                "approval_decision_id": decision.id,
            }),
        );
        crate::projects::update_project(
            &pool,
            crate::projects::PERSONAL_PROJECT_ID,
            crate::projects::UpdateProject {
                metadata_json: Some(metadata),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        let order = goal_state::topological_order(&goals).unwrap();
        let err = materialize_roadmap_transaction(
            &pool,
            crate::projects::PERSONAL_PROJECT_ID,
            &goals,
            &order,
            &hash,
            &decision.id,
            None,
            GooseMode::Approve,
            None,
        )
        .await
        .expect_err("cross-project approval must be rejected");
        assert!(err.contains("different project"));
        let project = crate::projects::get_project(&pool, crate::projects::PERSONAL_PROJECT_ID)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            project.metadata_json[ROADMAP_PROPOSAL_METADATA_KEY]["hash"],
            hash
        );
    }

