    #[tokio::test]
    async fn dispatch_prefers_card_budget_identity_for_headless_workers() {
        let temp = tempfile::tempdir().unwrap();
        let manager = crate::session::SessionManager::new(temp.path().to_path_buf());
        let session = manager
            .create_session(
                temp.path().to_path_buf(),
                "approver".to_string(),
                crate::session::SessionType::User,
                crate::config::GooseMode::Auto,
            )
            .await
            .unwrap();
        let mut extension_data = session.extension_data;
        extension_data.set_extension_state(
            crate::session::BUDGET_TASK_EXTENSION_NAME,
            crate::session::BUDGET_TASK_EXTENSION_VERSION,
            serde_json::Value::String("parent-task".to_string()),
        );
        manager
            .update(&session.id)
            .extension_data(extension_data)
            .apply()
            .await
            .unwrap();
        let session = manager.get_session(&session.id, false).await.unwrap();

        assert_eq!(
            dispatch_budget_task_id(&serde_json::json!({}), Some(&session)).as_deref(),
            Some("parent-task")
        );
        assert_eq!(
            dispatch_budget_task_id(
                &serde_json::json!({"budget_task_id": "materialized-task"}),
                Some(&session)
            )
            .as_deref(),
            Some("materialized-task")
        );
    }

    // ── R2 (harness loop, Lane G3 review of the R1/R2 commit): fail-closed
    // session-mode detection, plus end-to-end handler coverage through the
    // LIVE `current_session_mode()` call path rather than a hand-supplied
    // `GooseMode` argument. ──

    /// The exact two goals `RoadmapMockProvider` returns, so a test can
    /// independently recompute the same `proposal_hash`/`goals_json`
    /// `create_roadmap` requires without parsing the tool response text.
    fn roadmap_fixture_goals() -> Vec<goal_state::ProposedGoal> {
        vec![
            goal_state::ProposedGoal {
                title: "R2 fixture A".to_string(),
                description: "first".to_string(),
                acceptance_criteria: vec![],
                tags: vec![],
                depends_on: vec![],
            },
            goal_state::ProposedGoal {
                title: "R2 fixture B".to_string(),
                description: "second".to_string(),
                acceptance_criteria: vec![],
                tags: vec![],
                depends_on: vec![0],
            },
        ]
    }

    /// A `LocalFree` provider (no marginal cost, so no durable-task/budget
    /// reservation is required) that always answers with
    /// `roadmap_fixture_goals()` as the decomposition response, driving
    /// `handle_decompose_roadmap`'s real LLM path deterministically with no
    /// network access.
    #[derive(Clone)]
    struct RoadmapMockProvider {
        model_config: crate::model::ModelConfig,
    }

    impl RoadmapMockProvider {
        fn new() -> Self {
            Self {
                model_config: crate::model::ModelConfig::new("mock-roadmap-decomposer").unwrap(),
            }
        }
    }

    #[async_trait::async_trait]
    impl Provider for RoadmapMockProvider {
        fn get_name(&self) -> &str {
            "mock-roadmap"
        }

        fn cost_tier(&self) -> crate::session::CostTier {
            crate::session::CostTier::LocalFree
        }

        fn get_model_config(&self) -> crate::model::ModelConfig {
            self.model_config.clone()
        }

        async fn stream(
            &self,
            _model_config: &crate::model::ModelConfig,
            _session_id: &str,
            _system: &str,
            _messages: &[Message],
            _tools: &[Tool],
        ) -> Result<crate::providers::base::MessageStream, crate::providers::errors::ProviderError>
        {
            let text = serde_json::to_string(&serde_json::json!({
                "goals": roadmap_fixture_goals(),
            }))
            .unwrap();
            let message = Message::assistant().with_text(text);
            let usage = crate::providers::base::ProviderUsage::new(
                "mock-roadmap".to_string(),
                crate::providers::base::Usage::default(),
            );
            Ok(crate::providers::base::stream_from_single_message(
                message, usage,
            ))
        }
    }

    /// Build a real `OrchestratorClient` wired to an in-memory session, a
    /// `LocalFree` mock provider reachable through a genuine
    /// `ExtensionManager` (so `get_provider()`/`current_session_mode()`'s
    /// live-agent-mode lookup exercise the same code paths production does),
    /// and a fresh personal-project-seeded DB.
    ///
    /// `bind_context_session` controls whether `context.session` (read only
    /// by `current_session_mode()`) is set to the same session driving the
    /// call, or left `None` -- reproducing the production gap
    /// (`extension_manager.rs`'s `create_extension`, which leaves
    /// `context.session` `None` whenever `session_id` is absent or its
    /// lookup fails) independently of the session actually passed to
    /// `handle_decompose_roadmap`.
    async fn roadmap_handler_fixture(
        goose_mode: GooseMode,
        bind_context_session: bool,
    ) -> (
        tempfile::TempDir,
        Arc<SessionManager>,
        Session,
        Arc<crate::agents::extension_manager::ExtensionManager>,
        OrchestratorClient,
    ) {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let session = sm
            .create_session(
                tmp.path().to_path_buf(),
                "roadmap-handler-fixture".to_string(),
                SessionType::Hidden,
                goose_mode,
            )
            .await
            .unwrap();
        let mock_provider: Arc<dyn Provider> = Arc::new(RoadmapMockProvider::new());
        let em = Arc::new(crate::agents::extension_manager::ExtensionManager::new(
            Arc::new(tokio::sync::Mutex::new(Some(mock_provider))),
            sm.clone(),
            "test".to_string(),
            crate::agents::extension_manager::ExtensionManagerCapabilities { mcpui: false },
        ));
        let context = PlatformExtensionContext {
            extension_manager: Some(Arc::downgrade(&em)),
            session_manager: sm.clone(),
            session: if bind_context_session {
                Some(Arc::new(session.clone()))
            } else {
                None
            },
        };
        let client = OrchestratorClient::new(context).unwrap();
        (tmp, sm, session, em, client)
    }

    /// Runs `handle_decompose_roadmap` then reads back the proposal proof
    /// (`approval_decision_id`, and the independently-recomputed
    /// `goals_json`/`proposal_hash` `roadmap_fixture_goals()` must have
    /// produced) so a test can drive `handle_create_roadmap` without parsing
    /// tool-response prose.
    async fn decompose_then_read_proof(
        client: &OrchestratorClient,
        pool: &sqlx::Pool<sqlx::Sqlite>,
        session_id: &str,
    ) -> (CallToolResult, String, String, String) {
        let mut args = JsonObject::new();
        args.insert(
            "objective".to_string(),
            serde_json::json!("ship the R2 fixture"),
        );
        let decompose_result = client
            .handle_decompose_roadmap(session_id, Some(args))
            .await
            .expect("decomposition against the mock provider must succeed");

        let project = crate::projects::get_project(pool, crate::projects::PERSONAL_PROJECT_ID)
            .await
            .unwrap()
            .unwrap();
        let approval_decision_id = project.metadata_json[ROADMAP_PROPOSAL_METADATA_KEY]
            ["approval_decision_id"]
            .as_str()
            .unwrap()
            .to_string();
        let goals = roadmap_fixture_goals();
        let goals_json = serde_json::to_string(&goals).unwrap();
        let proposal_hash = roadmap_proposal_hash(&goals);
        assert_eq!(
            project.metadata_json[ROADMAP_PROPOSAL_METADATA_KEY]["hash"], proposal_hash,
            "the handler's stored proof hash must match the fixture goals' hash"
        );
        (
            decompose_result,
            approval_decision_id,
            goals_json,
            proposal_hash,
        )
    }

    fn create_roadmap_args(
        goals_json: &str,
        proposal_hash: &str,
        approval_decision_id: &str,
    ) -> JsonObject {
        let mut args = JsonObject::new();
        args.insert(
            "project_id_or_slug".to_string(),
            serde_json::json!(crate::projects::PERSONAL_PROJECT_ID),
        );
        args.insert("goals_json".to_string(), serde_json::json!(goals_json));
        args.insert(
            "proposal_hash".to_string(),
            serde_json::json!(proposal_hash),
        );
        args.insert(
            "approval_decision_id".to_string(),
            serde_json::json!(approval_decision_id),
        );
        args
    }

    /// R2-1 pinning, direct: `current_session_mode()` must return `None`,
    /// never `Some(GooseMode::Auto)`, when `context.session` is absent.
    #[tokio::test]
    async fn current_session_mode_is_none_without_a_context_session() {
        let (_tmp, _sm, _session, _em, client) =
            roadmap_handler_fixture(GooseMode::Approve, false).await;
        assert_eq!(
            client.current_session_mode().await,
            None,
            "an absent context.session must resolve to no known mode, not a default"
        );
    }

    /// R2-1 pinning, end-to-end (this is also the test Lane G3 finding 2
    /// asked for: it drives `current_session_mode()` through its LIVE call
    /// path inside real handlers, not a hand-supplied `GooseMode` argument).
    /// The session actually driving the call (`session_id`, passed to
    /// `handle_decompose_roadmap`) is genuinely `Approve` mode -- a human is
    /// expected to answer. `context.session`, read only by
    /// `current_session_mode()`, is independently `None` (the production gap
    /// from `extension_manager.rs`). Before the fix this silently granted
    /// Auto-mode self-approval; after the fix it must not.
    #[tokio::test]
    async fn auto_answer_gate_fails_closed_when_context_session_is_none() {
        let (_tmp, sm, session, _em, client) =
            roadmap_handler_fixture(GooseMode::Approve, false).await;
        let pool = sm.pool_clone().await.unwrap();

        assert_eq!(client.current_session_mode().await, None);

        let (decompose_result, approval_decision_id, goals_json, proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;
        let decompose_text = decompose_result.content[0].as_text().unwrap().text.clone();
        assert!(
            !decompose_text.contains("already pre-approved"),
            "a client with no context.session must never auto-answer: {decompose_text}"
        );

        let err = client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json,
                &proposal_hash,
                &approval_decision_id,
            )))
            .await
            .expect_err("no human ever answered this decision; creation must fail");
        assert_eq!(
            err,
            "Roadmap creation requires an answered Decision Inbox approval by the user"
        );
    }

    /// R2-3: the end-to-end handler test Lane G3 finding 2 asked for --
    /// `handle_decompose_roadmap` then `handle_create_roadmap` on a real
    /// `OrchestratorClient` whose bound session is genuinely `GooseMode::Auto`,
    /// asserting success with no human ever answering the Decision Inbox.
    /// This is the test that would have caught R2-1: with the pre-fix
    /// `current_session_mode()`, this test happened to still pass (a real
    /// Auto session reads as Auto either way) -- its value is in pairing
    /// with the Approve-mode sibling below, which the pre-fix code would
    /// have FAILED by wrongly self-approving.
    #[tokio::test]
    async fn handle_decompose_then_create_roadmap_succeeds_with_no_human_answer_in_auto_mode() {
        let (_tmp, sm, session, _em, client) = roadmap_handler_fixture(GooseMode::Auto, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (decompose_result, approval_decision_id, goals_json, proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;
        let decompose_text = decompose_result.content[0].as_text().unwrap().text.clone();
        assert!(
            decompose_text.contains("already pre-approved"),
            "an Auto-mode session must self-approve its own decomposition: {decompose_text}"
        );

        client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json,
                &proposal_hash,
                &approval_decision_id,
            )))
            .await
            .expect(
                "an Auto-mode session must be able to create its own pre-approved roadmap \
                 with no human answer",
            );
    }

    /// R2-3 sibling: the SAME two-handler flow with a genuinely `Approve`-mode
    /// bound session must still require a human answer -- this is the case
    /// the pre-fix `current_session_mode()` (which only special-cased the
    /// `None`-session gap, not this one) already got right, kept here as the
    /// paired non-regression half of the end-to-end coverage Lane G3 finding
    /// 2 asked for.
    #[tokio::test]
    async fn handle_decompose_then_create_roadmap_requires_human_answer_in_approve_mode() {
        let (_tmp, sm, session, _em, client) =
            roadmap_handler_fixture(GooseMode::Approve, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (decompose_result, approval_decision_id, goals_json, proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;
        let decompose_text = decompose_result.content[0].as_text().unwrap().text.clone();
        assert!(
            !decompose_text.contains("already pre-approved"),
            "an Approve-mode session must never self-approve: {decompose_text}"
        );

        let err = client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json,
                &proposal_hash,
                &approval_decision_id,
            )))
            .await
            .expect_err(
                "an unanswered decision must never create a roadmap for an Approve-mode session",
            );
        assert_eq!(
            err,
            "Roadmap creation requires an answered Decision Inbox approval by the user"
        );
    }

    // ── R45a (harness loop, A42 analysis finding 1): create_roadmap's own
    // proposal_hash mismatch handling ─────────────────────────────────────

    /// `goals_json` byte-identical to the latest pending proposal (after the
    /// same canonical serialisation `roadmap_proposal_hash` applies) must be
    /// accepted regardless of the submitted `proposal_hash` — DeepSeek's own
    /// failure mode (HARNESS_LOOP_LOG.md A42 analysis, finding 1): a
    /// hand-typed hash that never matched the server's own hash, while the
    /// resubmitted goals were the exact same proposal every time.
    #[tokio::test]
    async fn identical_goals_json_is_accepted_despite_a_wrong_proposal_hash() {
        let (_tmp, sm, session, _em, client) = roadmap_handler_fixture(GooseMode::Auto, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (_decompose_result, approval_decision_id, goals_json, proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;

        let wrong_hash = "f".repeat(64);
        assert_ne!(wrong_hash, proposal_hash);

        let result = client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json,
                &wrong_hash,
                &approval_decision_id,
            )))
            .await
            .expect(
                "goals_json byte-identical to the pending proposal must be accepted regardless \
                 of the submitted proposal_hash",
            );
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(
            text.contains("Goal cards:") && text.contains("id="),
            "a tolerated hash must still materialize the roadmap: {text}"
        );
    }

    /// The tolerance above must NOT swallow a genuine mismatch: `goals_json`
    /// that differs from the pending proposal, paired with a wrong hash,
    /// still fails — and the error names the exact hash expected for the
    /// goals actually submitted, so a model can recover in one more call.
    #[tokio::test]
    async fn goals_json_that_differs_from_the_pending_proposal_still_requires_the_correct_hash() {
        let (_tmp, sm, session, _em, client) = roadmap_handler_fixture(GooseMode::Auto, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (_decompose_result, approval_decision_id, _goals_json, _proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;

        let mut different_goals = roadmap_fixture_goals();
        different_goals[0].title = "A goal decompose_roadmap never proposed".to_string();
        let different_goals_json = serde_json::to_string(&different_goals).unwrap();
        let expected_hash = roadmap_proposal_hash(&different_goals);
        let wrong_hash = "f".repeat(64);
        assert_ne!(wrong_hash, expected_hash);

        let err = client
            .handle_create_roadmap(Some(create_roadmap_args(
                &different_goals_json,
                &wrong_hash,
                &approval_decision_id,
            )))
            .await
            .expect_err("goals that do not match the pending proposal and a wrong hash must fail");
        assert!(
            err.contains(&expected_hash),
            "the error must name the exact expected hash for these goals: {err}"
        );
    }

    /// A headless session that genuinely cannot reproduce the hash (goals
    /// that never match the pending proposal, three times in a row) must
    /// stop looping: the 3rd consecutive mismatch auto-approves the pending
    /// proposal instead of returning a 4th error. Drives
    /// `resolve_create_roadmap_proposal_hash` directly with `headless: true`
    /// passed explicitly — never the process-global headless dispatch
    /// policy `OnceLock` (`install_dispatch_hook_for_headless_session`),
    /// which a test must not install more than once per binary (see the
    /// warning above `roadmap_handler_fixture`). `GooseMode::Approve` (not
    /// `Auto`) keeps the decision genuinely `open` at decompose time, so the
    /// auto-approve this test observes is this lane's own, not
    /// `decompose_roadmap`'s pre-existing R1 self-approval.
    #[tokio::test]
    async fn headless_third_consecutive_mismatch_auto_approves_the_pending_proposal() {
        let (_tmp, sm, session, _em, client) =
            roadmap_handler_fixture(GooseMode::Approve, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (_decompose_result, approval_decision_id, _goals_json, _proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;

        let decision = crate::decisions::get_decision(&pool, &approval_decision_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            decision.status, "open",
            "Approve-mode decomposition must not self-approve"
        );

        let project = crate::projects::get_project(&pool, crate::projects::PERSONAL_PROJECT_ID)
            .await
            .unwrap()
            .unwrap();

        // Goals that never match the pending proposal, paired with a wrong
        // hash — a genuine, non-tolerated mismatch on every call.
        let mut mismatched_goals = roadmap_fixture_goals();
        mismatched_goals[0].title = "Not the pending proposal".to_string();
        let computed_hash = roadmap_proposal_hash(&mismatched_goals);
        let wrong_hash = "0".repeat(64);
        assert_ne!(computed_hash, wrong_hash);

        for attempt in 1..=2 {
            let outcome = client
                .resolve_create_roadmap_proposal_hash(
                    &pool,
                    &project,
                    &computed_hash,
                    wrong_hash.clone(),
                    &approval_decision_id,
                    true,
                )
                .await;
            match outcome {
                ProposalHashOutcome::Error(_) => {}
                ProposalHashOutcome::Respond(_) => {
                    panic!("attempt {attempt} auto-approved too early")
                }
                ProposalHashOutcome::Proceed(_) => {
                    panic!("attempt {attempt} must not be accepted")
                }
            }
        }

        let outcome = client
            .resolve_create_roadmap_proposal_hash(
                &pool,
                &project,
                &computed_hash,
                wrong_hash,
                &approval_decision_id,
                true,
            )
            .await;
        match outcome {
            ProposalHashOutcome::Respond(result) => {
                let text = result.content[0].as_text().unwrap().text.clone();
                assert!(
                    text.contains("now exists as an approved decision"),
                    "expected the loop-capping success message, got: {text}"
                );
            }
            ProposalHashOutcome::Error(message) => {
                panic!("expected the 3rd mismatch to auto-approve: {message}")
            }
            ProposalHashOutcome::Proceed(hash) => {
                panic!("expected the 3rd mismatch to auto-approve, got accepted: {hash}")
            }
        }

        let decision = crate::decisions::get_decision(&pool, &approval_decision_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(decision.status, "answered");
        assert_eq!(
            decision.answer_choice_id.as_deref(),
            Some("approve-roadmap"),
            "the pending proposal must now be approved"
        );
    }

    // ── M3-1: headless auto-dispatch (harness loop, Lane S) ────────────────

    /// M3-1 pinning: before a headless CLI (`permagent run`) installs a goal
    /// dispatcher, `create_roadmap` reports zero root goals dispatched even
    /// though the roadmap has a genuine root (no-dependency) goal — the exact
    /// defect Lane M3 quoted live in 8/10 measured fixtures ("the roadmap was
    /// created but it says '0 root goal(s) dispatched to workers'"), because
    /// `nudge_dispatch_ready_goals` (`orchestrator.rs`) only ever starts a
    /// worker through the process-global `GOAL_DISPATCH_HOOK`, and only the
    /// daemon installed it. Once a hook IS installed — Lane S's CLI fix
    /// installs the daemon's own `install_dispatch_hook` when the recipe is
    /// the coding harness and the session is `GooseMode::Auto`
    /// (`goose-cli/src/session/builder.rs`'s `wants_headless_goal_dispatch`)
    /// — the SAME `create_roadmap` call creates a real child session with
    /// `parent_session_id` set to the coordinator session, with no further
    /// coordinator tool call.
    ///
    /// This test installs a hook through the SAME `create_session_with_parent`
    /// seam `delegate` (`summon.rs`) and the production dispatcher
    /// (`dispatch_goal_fn`'s `InternalSubagentEngine::spawn`) both use as
    /// their very first step, without a live worker roster, network, or
    /// subprocess — that pins the WIRING this lane fixed (a hook, once
    /// installed, is actually reached and actually creates a session), not
    /// worker selection/spawn, which is separately covered where those
    /// functions are tested directly.
    ///
    /// Lane T1 (harness loop, M21 bisect, 2026-09-14): both the "no hook"
    /// and "hook installed" states are exercised in ONE test function, in
    /// order — that part was always safe. What was NOT safe: the process-
    /// global dispatch-hook slot used to be a bare `OnceLock`, so Phase 1's
    /// "no hook yet" assumption only held when this test happened to be the
    /// FIRST in the whole `cargo test --lib` binary to touch that slot —
    /// true when run alone or with `--test-threads=1`, false whenever
    /// another hook-installing test (this file's own
    /// `dispatch_goal_to_and_resume_roadmap_consult_the_installed_headless_
    /// policy`, or `test_dispatch_recorder::install()`'s callers elsewhere
    /// in the crate) happened to run first under parallel `-- roadmap`
    /// execution. This test now brackets EACH phase in its own
    /// `goal_dispatch_hook`-slot guard (`take_goal_dispatch_hook_for_test`
    /// for Phase 1's "definitely nothing installed",
    /// `replace_goal_dispatch_hook_for_test` for Phase 2's "definitely THIS
    /// closure") so its own two phases are correct regardless of what any
    /// other test in the binary already left installed, and regardless of
    /// run order. `#[serial_test::serial]` (the default, unnamed key) still
    /// keeps this test from running CONCURRENTLY with another test that
    /// touches the same slot — the guard fixes correctness of each test's
    /// own phases; the attribute fixes mutual exclusion between tests.
    #[serial_test::serial]
    #[tokio::test]
    async fn create_roadmap_dispatches_a_real_child_session_once_a_dispatch_hook_is_installed() {
        let (_tmp, sm, session, _em, client) = roadmap_handler_fixture(GooseMode::Auto, true).await;
        let pool = sm.pool_clone().await.unwrap();

        // Phase 1: no dispatch hook installed for the DURATION OF THIS BLOCK
        // — forced via the test seam rather than assumed from run order —
        // reproducing the exact headless-CLI defect Lane M3 measured live.
        {
            let _hook_guard = take_goal_dispatch_hook_for_test();
            let (_decompose_result, approval_decision_id, goals_json, proposal_hash) =
                decompose_then_read_proof(&client, &pool, &session.id).await;
            let result = client
                .handle_create_roadmap(Some(create_roadmap_args(
                    &goals_json,
                    &proposal_hash,
                    &approval_decision_id,
                )))
                .await
                .expect("roadmap creation with no worker dispatched must still succeed");
            let text = result.content[0].as_text().unwrap().text.clone();
            assert!(
                text.contains("0 root goal(s) dispatched to workers"),
                "no dispatch hook is installed yet — root-goal dispatch must report zero, \
                 matching Lane M3's live defect: {text}"
            );
            // M3-1(b): even with nothing dispatched, the real ids must be
            // listed so a coordinator that must dispatch manually never has
            // to guess one.
            assert!(
                text.contains("Goal cards:") && text.contains("id="),
                "create_roadmap's result text must list the real goal-card ids: {text}"
            );
        } // _hook_guard drops here, restoring whatever was installed before
          // this test ran (if anything) — Phase 2 below installs its own.

        // Phase 2: install a hook using the SAME `create_session_with_parent`
        // seam `delegate` and the production dispatcher use, then create a
        // second roadmap through the identical Auto-mode, no-human-answer path.
        // Held until the end of the function so it stays installed through
        // every Phase-2 assertion, then restores whatever Phase 1's guard
        // restored, on drop.
        let hook_sm = sm.clone();
        let parent_session_id = session.id.clone();
        let _hook_guard =
            replace_goal_dispatch_hook_for_test(std::sync::Arc::new(move |_card_id: String| {
                let hook_sm = hook_sm.clone();
                let parent_session_id = parent_session_id.clone();
                Box::pin(async move {
                    // Also feeds `test_dispatch_recorder` so any OTHER test
                    // that only cares "was card X asked to dispatch"
                    // (`saw(...)`) stays reliable regardless of which
                    // closure a given process run happens to have installed.
                    test_dispatch_recorder::record(_card_id.clone());
                    let child = hook_sm
                        .create_session_with_parent(
                            Some(&parent_session_id),
                            std::env::temp_dir(),
                            "Dispatched goal".to_string(),
                            SessionType::SubAgent,
                            GooseMode::Auto,
                        )
                        .await
                        .map_err(|e| e.to_string())?;
                    Ok(child.id)
                }) as GoalDispatchFuture
            }));

        let (_decompose_result2, approval_decision_id2, goals_json2, proposal_hash2) =
            decompose_then_read_proof(&client, &pool, &session.id).await;
        let result2 = client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json2,
                &proposal_hash2,
                &approval_decision_id2,
            )))
            .await
            .expect("roadmap creation must still succeed once a dispatch hook is installed");
        let text2 = result2.content[0].as_text().unwrap().text.clone();
        assert!(
            !text2.contains("0 root goal(s) dispatched"),
            "a real dispatch hook is installed — the root goal must be reported dispatched: {text2}"
        );
        // Harness loop, Lane T ("Also"): once something dispatched, the
        // coordinator must be told plainly that the work is still running in
        // the background and how to check on it — the recipe's rule 4
        // ("finish only after ... review evidence pass") needs a real seam to
        // see completion through, and `goal_status` is it.
        assert!(
            text2.contains("goal_status"),
            "the coordinator must be told how to check on a dispatched worker's progress: {text2}"
        );

        // The child session genuinely exists with parent_session_id set to
        // the SAME coordinator session that called create_roadmap — reading
        // this back is not "a further coordinator tool call": it only
        // confirms what create_roadmap's own call already wrote.
        let children: Vec<(String,)> =
            sqlx::query_as("SELECT id FROM sessions WHERE parent_session_id = ?")
                .bind(&session.id)
                .fetch_all(&pool)
                .await
                .unwrap();
        assert!(
            !children.is_empty(),
            "a worker session with parent_session_id set to the coordinator session must exist \
             after create_roadmap, with no further coordinator tool call"
        );
    }

    // ── Lane T1 (harness loop, M21 bisect, 2026-09-14): dispatch-hook test
    // seam regression proofs ────────────────────────────────────────────────

    /// The core regression proof for the new test seam: TWO sequential
    /// "installs" in the SAME process, each through its own
    /// [`replace_goal_dispatch_hook_for_test`] guard, must each see its OWN
    /// closure actually run — not whichever one happened to win a
    /// process-global `OnceLock` first (the old defect this lane fixes).
    /// `#[serial_test::serial]` only prevents this test from running
    /// CONCURRENTLY with another test that touches the slot; the guard is
    /// what makes each phase below correct regardless of what any other
    /// test in the binary has already installed or when this test happens
    /// to run.
    #[serial_test::serial]
    #[tokio::test]
    async fn goal_dispatch_hook_test_seam_two_sequential_installs_each_observe_their_own_hook() {
        let first_calls = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        {
            let seen = std::sync::Arc::clone(&first_calls);
            let _guard =
                replace_goal_dispatch_hook_for_test(std::sync::Arc::new(move |card_id: String| {
                    let seen = std::sync::Arc::clone(&seen);
                    Box::pin(async move {
                        seen.lock().unwrap().push(card_id.clone());
                        Ok(format!("first-hook-session-for-{card_id}"))
                    }) as GoalDispatchFuture
                }));

            let hook =
                goal_dispatch_hook_snapshot().expect("a hook is installed inside this scope");
            let result = hook("card-a".to_string()).await.unwrap();
            assert_eq!(result, "first-hook-session-for-card-a");
        } // _guard drops here, restoring whatever was installed before this
          // test ran (if anything).

        assert_eq!(
            first_calls.lock().unwrap().as_slice(),
            &["card-a".to_string()],
            "the first hook must have observed exactly the call routed to it"
        );

        // A SECOND install, in the same process, after the first guard has
        // already dropped: under the old `OnceLock`, this `.set()` would be
        // silently discarded and every subsequent dispatch would still run
        // the FIRST closure (or whichever process-wide winner got there
        // first) — the exact defect this lane fixes. With the guard-based
        // seam, this phase's own closure must be the one that actually runs.
        let second_calls = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let seen2 = std::sync::Arc::clone(&second_calls);
        let _guard2 =
            replace_goal_dispatch_hook_for_test(std::sync::Arc::new(move |card_id: String| {
                let seen2 = std::sync::Arc::clone(&seen2);
                Box::pin(async move {
                    seen2.lock().unwrap().push(card_id.clone());
                    Ok(format!("second-hook-session-for-{card_id}"))
                }) as GoalDispatchFuture
            }));

        let hook2 = goal_dispatch_hook_snapshot().expect("the second hook is installed");
        let result2 = hook2("card-b".to_string()).await.unwrap();
        assert_eq!(result2, "second-hook-session-for-card-b");
        assert_eq!(
            second_calls.lock().unwrap().as_slice(),
            &["card-b".to_string()],
            "the second install must win its own scope — it is not silently discarded the way \
             a bare OnceLock's second `.set()` used to be"
        );
        assert!(
            first_calls.lock().unwrap().iter().all(|id| id != "card-b"),
            "the FIRST hook (already restored/dropped by its own guard) must never observe \
             the second phase's call — a leaked/stale hook would prove the guard failed to \
             restore state between phases"
        );
    }

    /// [`install_goal_dispatch_hook`] preserves the exact "first install
    /// wins, second call is a harmless no-op" contract the old
    /// `OnceLock::set` gave production for free — the semantics
    /// [`install_dispatch_hook`] and [`install_dispatch_hook_for_headless_
    /// session`] both depend on, and the one thing Lane T1 was NOT allowed
    /// to change.
    #[serial_test::serial]
    #[tokio::test]
    async fn goal_dispatch_hook_production_install_is_idempotent() {
        // Force a clean slot for this test regardless of what another test
        // in the binary has already installed; restores the prior value on
        // drop.
        let _hook_guard = take_goal_dispatch_hook_for_test();

        let first_won = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let second_won = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));

        {
            let first_won = std::sync::Arc::clone(&first_won);
            install_goal_dispatch_hook(std::sync::Arc::new(move |card_id: String| {
                let first_won = std::sync::Arc::clone(&first_won);
                Box::pin(async move {
                    first_won.store(true, std::sync::atomic::Ordering::SeqCst);
                    Ok(format!("first-install-session-for-{card_id}"))
                }) as GoalDispatchFuture
            }));
        }
        {
            let second_won = std::sync::Arc::clone(&second_won);
            // Second call: must be a silent no-op, exactly like the old
            // `let _ = GOAL_DISPATCH_HOOK.set(..)` discarding its `Err`.
            install_goal_dispatch_hook(std::sync::Arc::new(move |card_id: String| {
                let second_won = std::sync::Arc::clone(&second_won);
                Box::pin(async move {
                    second_won.store(true, std::sync::atomic::Ordering::SeqCst);
                    Ok(format!("second-install-session-for-{card_id}"))
                }) as GoalDispatchFuture
            }));
        }

        let hook = goal_dispatch_hook_snapshot().expect("the first install must have won the slot");
        let result = hook("card-idempotent".to_string()).await.unwrap();
        assert_eq!(
            result, "first-install-session-for-card-idempotent",
            "the FIRST install must be the one actually reachable through the slot"
        );
        assert!(
            first_won.load(std::sync::atomic::Ordering::SeqCst),
            "the first installed closure must have run"
        );
        assert!(
            !second_won.load(std::sync::atomic::Ordering::SeqCst),
            "the second installed closure must never run — install_goal_dispatch_hook is \
             first-wins, matching the old OnceLock contract"
        );
    }

    /// Lane R1 (harness improvement loop) — the "replay slice" mechanism
    /// smoke test: record a real provider traffic pattern ONCE, then replay
    /// it through the REAL pipeline (`OrchestratorClient::handle_decompose_
    /// roadmap` -> `handle_create_roadmap` -> root-goal dispatch) with the
    /// SAME assertions a real run would need to pass, but with ZERO network
    /// calls and zero spend on the replay leg.
    ///
    /// **Why "record against a local fake, then replay" instead of shipping
    /// a hand-typed cassette file.** `cassette_key` hashes (model name,
    /// system prompt, canonicalized messages, canonicalized tools) — and
    /// `handle_decompose_roadmap`'s real request also folds in the live
    /// capability directory (`configured_worker_capabilities()`) and a repo
    /// facts probe (`RepoFacts::gather`), neither of which this lane can
    /// observe without a compile slot (no `cargo run`/`cargo test` allowed
    /// yet — see the lane's own README/report). Hand-typing a cassette line
    /// with a guessed key would either accidentally miss (proving nothing)
    /// or accidentally hit for the wrong reason (a coincidental string
    /// match) — neither is an honest proof. Recording a REAL decompose call
    /// against `RoadmapMockProvider` (this file's own existing deterministic
    /// fixture, already proven by `roadmap_handler_fixture` and every test
    /// above) and then replaying it in a FRESH session/DB/client makes the
    /// key self-consistent by construction: whatever
    /// `handle_decompose_roadmap` actually sends is exactly what gets
    /// hashed on both the record and the replay leg, because it is the same
    /// code computing both. The replay leg's `ExtensionManager` is built
    /// with a `CassetteProvider` alone — there is no `RoadmapMockProvider`
    /// instance anywhere in that leg's code, so "no real model was
    /// constructed or called" is true by construction, not merely asserted.
    ///
    /// Both legs pin `session.working_dir` to a deliberately NONEXISTENT
    /// path rather than each leg's own `tempfile::tempdir()` — `RepoFacts::
    /// gather` is documented best-effort ("an unreadable or missing
    /// directory yields an all-empty `RepoFacts`"), so a nonexistent path
    /// gives a byte-identical empty facts block on both legs, with no risk
    /// of the two legs' distinct temp-dir names (or their SQLite files)
    /// leaking into the hashed request and breaking the match.
    ///
    /// **What this proves:** `CassetteProvider::for_replay` reproduces a
    /// byte-identical decomposition through the REAL handler (same goals,
    /// same content hash — the "decision kind"/proposal-hash mechanism M7
    /// broke); the approval row is a real `choice` decision on BOTH legs;
    /// root goal dispatch (via the SAME `GOAL_DISPATCH_HOOK` wiring seam
    /// `create_roadmap_dispatches_a_real_child_session_once_a_dispatch_hook_
    /// is_installed` above already established as this codebase's own
    /// no-live-worker test boundary) fires and really creates a child
    /// worker session.
    ///
    /// It ALSO proves, incidentally but load-bearingly, that a replayed
    /// provider survives the accounted-completion path: `run_decomposition`
    /// goes through `AccountedFastCompletion`, which asks the provider for
    /// its `cost_tier()` BEFORE the call and would refuse a `PaidApi` answer
    /// without a durable task and a context limit. Replay reports the tier
    /// the RECORDING carried (`RoadmapMockProvider` is `LocalFree`), not a
    /// guess — see `cassette.rs`'s "Known limitations".
    ///
    /// **What this does NOT prove:** that the FACTORY installs the cassette.
    /// This test hands a `CassetteProvider` to an `ExtensionManager`
    /// directly and never calls `providers::create`, so it says nothing
    /// about `provider_registry.rs`'s `construct_and_wrap`. That wiring is
    /// pinned separately and deterministically — with no env var and no
    /// process globals — by `provider_registry.rs`'s own
    /// `replay_mode_never_constructs_the_real_provider`,
    /// `record_mode_still_constructs_and_guards_the_real_provider` and
    /// `no_cassette_constructs_the_real_provider_exactly_as_before`.
    ///
    /// **Process globals:** this test claims the process-global dispatch-hook
    /// slot (via [`replace_goal_dispatch_hook_for_test`], which restores the
    /// prior value on `Drop` — Lane T1), a seam several other tests in this
    /// binary also touch (see the note above `goal_advance_on_an_unknown_id_
    /// names_the_known_goal_card_ids`). It is `#[ignore]`d precisely so the
    /// documented run command gives it a process where nothing else is
    /// concurrently claiming that seam; a `--include-ignored` full-suite run
    /// can still make its dispatch assertions fail if another test's OWN use
    /// of the slot overlaps its lifetime (the guard fixes correctness of
    /// each test's own footprint, not mutual exclusion between tests run at
    /// the same time).
    ///
    /// **What this deliberately does NOT prove (documented, not silently
    /// skipped):** the worker actually editing code, `verify`, `review`, or
    /// landing a commit — no existing in-process test in this codebase
    /// drives that (`dispatch_goal_fn_dispatches_an_internal_worker_
    /// through_a_headless_policy_with_no_extension_manager` above stops at
    /// "dispatch returned a session id" for the same reason: the worker
    /// turn loop runs as a detached spawned task this test would have to
    /// poll with no real model to drive it). Extending replay coverage to
    /// the worker's own turns is the spec for Lane M12: once a REAL
    /// cassette is recorded (`PERMAGENT_PROVIDER_CASSETTE=record:<dir>`
    /// against a live paid run), its keys are correct by construction (the
    /// same "no guessing" argument this test makes locally) and can drive
    /// the worker leg too.
    ///
    /// Run: `cargo test -p permagent --lib -j1 -- --ignored replay_slice_smoke`
    /// — no network, no spend, seconds not minutes.
    #[serial_test::serial]
    #[tokio::test]
    #[ignore = "Lane R1 replay-slice mechanism smoke test — run explicitly, \
                see this test's own doc comment"]
    async fn replay_slice_smoke() {
        use crate::providers::cassette::CassetteProvider;

        // Deliberately nonexistent — see the doc comment above for why this
        // (not `tempfile::tempdir()`) is what makes the two legs' hashed
        // requests byte-identical.
        let nonexistent_working_dir =
            PathBuf::from("/nonexistent-permagent-replay-slice-smoke-fixture");

        let cassette_dir = tempfile::tempdir().unwrap();
        let cassette_dir_path = cassette_dir.path().to_path_buf();

        // ── Record leg: a REAL `handle_decompose_roadmap` call against a
        // real (local, deterministic) provider, wrapped so its traffic is
        // captured. `RoadmapMockProvider` never leaves this process — this
        // is "record a real run once," just against a fixture already
        // proven elsewhere in this file rather than a live paid model.
        // The record leg's own decision id is asserted on INSIDE the block
        // below, while its pool is still alive, so it is deliberately not
        // carried out (the two legs mint different ids from different DBs).
        let (_record_approval_decision_id, record_goals_json, record_proposal_hash) = {
            let tmp = tempfile::tempdir().unwrap();
            let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
            let session = sm
                .create_session(
                    nonexistent_working_dir.clone(),
                    "replay-slice-smoke-record".to_string(),
                    SessionType::Hidden,
                    GooseMode::Auto,
                )
                .await
                .unwrap();
            let pool = sm.pool_clone().await.unwrap();

            let inner: Arc<dyn Provider> = Arc::new(RoadmapMockProvider::new());
            let recording = CassetteProvider::wrap_for_record(inner, cassette_dir_path.clone())
                .expect("wrapping a real inner provider for record must succeed");
            let em = Arc::new(crate::agents::extension_manager::ExtensionManager::new(
                Arc::new(tokio::sync::Mutex::new(Some(recording))),
                sm.clone(),
                "test".to_string(),
                crate::agents::extension_manager::ExtensionManagerCapabilities { mcpui: false },
            ));
            let context = PlatformExtensionContext {
                extension_manager: Some(Arc::downgrade(&em)),
                session_manager: sm.clone(),
                session: Some(Arc::new(session.clone())),
            };
            let client = OrchestratorClient::new(context).unwrap();

            let (_decompose_result, approval_decision_id, goals_json, proposal_hash) =
                decompose_then_read_proof(&client, &pool, &session.id).await;

            // "Decision kinds" from this lane's brief, checked on the
            // record leg's own pool while it is still in scope.
            let record_decision = crate::decisions::get_decision(&pool, &approval_decision_id)
                .await
                .expect("looking up the record leg's own decision must succeed")
                .expect("the record leg's approval_decision_id must name a real decision row");
            assert_eq!(
                record_decision.kind, "choice",
                "the roadmap approval decision must be a real \"choice\" decision"
            );

            (approval_decision_id, goals_json, proposal_hash)
        };

        // The cassette must actually have been written, and record mode
        // must not have produced a miss (nothing to miss against yet).
        let cassette_file = cassette_dir_path.join("cassette.jsonl");
        let recorded = std::fs::read_to_string(&cassette_file)
            .expect("record leg must have written cassette.jsonl");
        assert!(
            !recorded.trim().is_empty(),
            "record leg must have appended at least one turn"
        );
        assert!(
            !cassette_dir_path.join("misses.jsonl").exists(),
            "record mode never writes misses.jsonl — that file name is replay-only"
        );

        // ── Replay leg: a FRESH tmp dir, FRESH SQLite DB, FRESH session and
        // client — and NO `RoadmapMockProvider` anywhere in this leg's code.
        // If replay reaches the real model instead of the cassette, this
        // leg has no working provider to reach at all: `for_replay` is the
        // ENTIRE provider.
        let tmp2 = tempfile::tempdir().unwrap();
        let sm2 = Arc::new(SessionManager::new(tmp2.path().to_path_buf()));
        let session2 = sm2
            .create_session(
                nonexistent_working_dir.clone(),
                "replay-slice-smoke-replay".to_string(),
                SessionType::Hidden,
                GooseMode::Auto,
            )
            .await
            .unwrap();
        let pool2 = sm2.pool_clone().await.unwrap();

        let replaying = CassetteProvider::for_replay(
            "mock-roadmap".to_string(),
            crate::model::ModelConfig::new("mock-roadmap-decomposer").unwrap(),
            cassette_dir_path.clone(),
        )
        .expect(
            "replay must construct from the just-recorded cassette with no real provider \
             and no credentials",
        );
        let em2 = Arc::new(crate::agents::extension_manager::ExtensionManager::new(
            Arc::new(tokio::sync::Mutex::new(Some(replaying))),
            sm2.clone(),
            "test".to_string(),
            crate::agents::extension_manager::ExtensionManagerCapabilities { mcpui: false },
        ));
        let context2 = PlatformExtensionContext {
            extension_manager: Some(Arc::downgrade(&em2)),
            session_manager: sm2.clone(),
            session: Some(Arc::new(session2.clone())),
        };
        let client2 = OrchestratorClient::new(context2).unwrap();

        let (
            _decompose_result2,
            replay_approval_decision_id,
            replay_goals_json,
            replay_proposal_hash,
        ) = decompose_then_read_proof(&client2, &pool2, &session2.id).await;

        // Decision-kind / content-hash mechanism: replay must reproduce the
        // EXACT same proposed goals and the EXACT same content hash the
        // record leg produced — this is the mechanism M7 found broken
        // (a rejected/mismatched approval payload never binding to what was
        // actually proposed).
        assert_eq!(
            replay_goals_json, record_goals_json,
            "replay must reproduce byte-identical proposed goals"
        );
        assert_eq!(
            replay_proposal_hash, record_proposal_hash,
            "replay must reproduce the identical roadmap content hash"
        );
        // The two approval_decision_ids are naturally DIFFERENT (fresh DB,
        // fresh Decision Inbox row per leg) — the record leg's own decision
        // was already checked (kind == "choice") inside its own scope
        // above, while its pool was still alive. Same check here for the
        // replay leg, on its own pool ("decision kinds" from this lane's
        // brief, proven on both legs).
        let replay_decision = crate::decisions::get_decision(&pool2, &replay_approval_decision_id)
            .await
            .expect("looking up the replay leg's own decision must succeed")
            .expect("the replay leg's approval_decision_id must name a real decision row");
        assert_eq!(
            replay_decision.kind, "choice",
            "the roadmap approval decision must be a real \"choice\" decision"
        );

        // ── Dispatch leg: install the SAME dispatch-hook test seam
        // `create_roadmap_dispatches_a_real_child_session_once_a_dispatch_
        // hook_is_installed` above uses (no live worker roster, network, or
        // subprocess — see that test's own doc comment for why this is the
        // established boundary in this codebase), then create the roadmap
        // on the REPLAY client — proving dispatch is reachable through a
        // cassette-replayed decomposition, not just a live one. Held until
        // the end of the function so `Drop` restores whatever was installed
        // before this test touched the slot.
        let hook_sm = sm2.clone();
        let parent_session_id = session2.id.clone();
        let _hook_guard =
            replace_goal_dispatch_hook_for_test(std::sync::Arc::new(move |_card_id: String| {
                let hook_sm = hook_sm.clone();
                let parent_session_id = parent_session_id.clone();
                Box::pin(async move {
                    test_dispatch_recorder::record(_card_id.clone());
                    let child = hook_sm
                        .create_session_with_parent(
                            Some(&parent_session_id),
                            std::env::temp_dir(),
                            "Dispatched goal (replay slice smoke)".to_string(),
                            SessionType::SubAgent,
                            GooseMode::Auto,
                        )
                        .await
                        .map_err(|e| e.to_string())?;
                    Ok(child.id)
                }) as GoalDispatchFuture
            }));

        let create_result = client2
            .handle_create_roadmap(Some(create_roadmap_args(
                &replay_goals_json,
                &replay_proposal_hash,
                &replay_approval_decision_id,
            )))
            .await
            .expect("roadmap creation against a replayed decomposition must succeed");
        let create_text = create_result.content[0].as_text().unwrap().text.clone();
        assert!(
            !create_text.contains("0 root goal(s) dispatched"),
            "the dispatch hook is installed — the root goal must be reported dispatched: \
             {create_text}"
        );

        // Real goal-state assertion: the dispatched card's column really
        // moved off Ready — this, plus the content-hash assertions above,
        // is "decision kinds / goal states" from this lane's brief; landing
        // is the documented, deliberate stopping point (see the doc
        // comment).
        let dispatched_children: Vec<(String,)> =
            sqlx::query_as("SELECT id FROM sessions WHERE parent_session_id = ?")
                .bind(&session2.id)
                .fetch_all(&pool2)
                .await
                .unwrap();
        assert!(
            !dispatched_children.is_empty(),
            "a worker session with parent_session_id set to the replay-leg coordinator \
             session must exist after create_roadmap"
        );
    }

    // Harness loop, Lane V (V3): `handle_create_roadmap`'s own git-init gate
    // (guarded on `current_headless_dispatch_policy(...).is_some()`, right
    // after `project` resolves) is deliberately NOT exercised end-to-end
    // here through the real `install_dispatch_hook_for_headless_session`
    // installer. That installer sets `HEADLESS_DISPATCH_POLICY_CONFIG` —
    // like `GOAL_DISPATCH_HOOK`, a process-global `OnceLock` that, once set
    // by ANY test, stays set for the rest of this binary's `cargo test`
    // invocation (no unsetter exists). A `create_roadmap_initialises_a_
    // missing_git_baseline_under_a_headless_auto_policy` test built exactly
    // that way was written and run while developing this lane: it passed in
    // isolation but, run as part of the FULL `orchestrator::` suite,
    // non-deterministically broke the pre-existing (Lane S)
    // `create_roadmap_dispatches_a_real_child_session_once_a_dispatch_hook_is_installed`
    // — whichever test's installer call happened to run first that pass won
    // the shared `OnceLock`s, and the other test's own "Phase 1: nothing
    // installed yet" assumption broke. That collision risk already exists
    // between two Lane-U-committed tests
    // (`dispatch_goal_to_and_resume_roadmap_consult_the_installed_headless_policy`
    // and the Lane-S test above) even without this lane's addition; adding a
    // THIRD installer-calling test only raised the odds of it firing. Rather
    // than add another test onto an already-cracked global, this lane
    // verifies the git-init gate two other ways: `ensure_headless_git_baseline`
    // itself is pinned directly above (fail-first, zero shared state); the
    // three-line gate in `handle_create_roadmap` that calls it is a thin,
    // already-reviewed composition of that function and
    // `current_headless_dispatch_policy` (Lane U's own primitive, already
    // covered by the test named above). A future lane that wants true
    // end-to-end coverage should first give every test touching
    // `HEADLESS_DISPATCH_POLICY_CONFIG`/`GOAL_DISPATCH_HOOK` a SHARED
    // `#[serial_test::serial("headless_policy_globals")]` key so they can
    // never interleave with a test that assumes a clean process.
    //
    // Lane T1 (harness loop, M21 bisect, 2026-09-14) update: the
    // `GOAL_DISPATCH_HOOK` half of this note is fixed — it is now a
    // `RwLock`-backed slot with a `#[cfg(test)]` override/restore seam
    // (`replace_goal_dispatch_hook_for_test` / `take_goal_dispatch_hook_for_test`),
    // used by both tests named above, so each one's own footprint on that
    // slot is fully reversible regardless of run order; `#[serial_test::serial]`
    // (the default key) still keeps them from running CONCURRENTLY.
    // `HEADLESS_DISPATCH_POLICY_CONFIG` itself is untouched by this lane and
    // remains a bare `OnceLock` with the same "stays set forever" hazard —
    // still a reason to avoid a fourth installer-calling test without first
    // giving it the same treatment.

    /// M3-1: `goal_advance`/`goal_status` on a fabricated or mistyped id used
    /// to silently no-op with a bare `"Card 'X' not found"` — no hint of a
    /// real id, so a model with no real id kept guessing (a tweaked hex digit
    /// off the proposal hash, or a bare literal integer, per Lane M3's
    /// transcripts). The error must now name the known goal card ids in the
    /// caller's own project.
    #[tokio::test]
    async fn goal_advance_on_an_unknown_id_names_the_known_goal_card_ids() {
        let (_tmp, sm, session, _em, client) = roadmap_handler_fixture(GooseMode::Auto, true).await;
        let pool = sm.pool_clone().await.unwrap();

        let (_decompose_result, approval_decision_id, goals_json, proposal_hash) =
            decompose_then_read_proof(&client, &pool, &session.id).await;
        client
            .handle_create_roadmap(Some(create_roadmap_args(
                &goals_json,
                &proposal_hash,
                &approval_decision_id,
            )))
            .await
            .expect("roadmap creation must succeed");
        let real_root_id: String = sqlx::query_scalar("SELECT id FROM cards WHERE title = ?")
            .bind("R2 fixture A")
            .fetch_one(&pool)
            .await
            .unwrap();

        let mut args = JsonObject::new();
        args.insert(
            "card_id".to_string(),
            serde_json::json!("01a08274-713c-73f1-8874-e28f98cf1a26"),
        );
        args.insert("action".to_string(), serde_json::json!("dispatch"));
        let err = client
            .handle_goal_advance(Some(args))
            .await
            .expect_err("a fabricated card id must never silently no-op");
        assert!(
            err.contains(&real_root_id),
            "the error must name a real known goal card id instead of just failing blind: {err}"
        );

        let mut status_args = JsonObject::new();
        status_args.insert(
            "card_id".to_string(),
            serde_json::json!("01a08274-713c-73f1-8874-e28f98cf1a26"),
        );
        let status_err = client
            .handle_goal_status(Some(status_args))
            .await
            .expect_err("a fabricated card id must never silently no-op");
        assert!(
            status_err.contains(&real_root_id),
            "goal_status's error must also name a real known goal card id: {status_err}"
        );
    }

    // ── R3: worker died with no error → one bounded retry before escalate
    // (harness loop, Lane D1, from Lane F8 forensics) ──

    /// A goal card in `in_progress` whose worker session died with NO error
    /// and NO landing — the exact shape fx04's coordinator read (via
    /// `goal_status`) right before reaching for `escalate`.
    /// `worker_session_id` names a REAL session row (so `handle_goal_status`
    /// can look it up) that is simply never registered as busy in
    /// `AgentManager` — indistinguishable, from this function's point of
    /// view, from a session whose process exited without a clean completion
    /// path. `worker_key` is `"permagent"` (`WorkerEngineKind::InternalSubagent`
    /// in every roster, default or user-configured — see
    /// `agent_identity::default_roster`), so the `engine_is_internal` gate
    /// passes deterministically in any test environment.
    ///
    /// `dispatched_secs_ago` (F1a, harness loop Lane F1 2026-09-10): R3 now
    /// refuses to treat a goal as dead until `r3_min_grace_secs()` has
    /// elapsed since `dispatched_at` — callers that mean to pin the
    /// GENUINELY-dead shape must backdate this past the grace window (the
    /// two existing pre-F1 callers below now pass 200, comfortably past the
    /// 180s default); callers pinning the grace period itself pass a small
    /// value instead.
    async fn dead_silent_worker_goal(
        pool: &sqlx::Pool<sqlx::Sqlite>,
        sm: &SessionManager,
        retry_count: Option<u64>,
        dispatched_secs_ago: i64,
    ) -> cards::Card {
        use crate::projects::PERSONAL_PROJECT_ID;
        cards::seed_goal_columns(pool, PERSONAL_PROJECT_ID)
            .await
            .unwrap();
        let col = cards::get_goal_column(pool, PERSONAL_PROJECT_ID, "in_progress")
            .await
            .unwrap()
            .unwrap();
        let dead_session = sm
            .create_session(
                std::env::temp_dir(),
                "R3 dead worker".to_string(),
                SessionType::SubAgent,
                GooseMode::Auto,
            )
            .await
            .unwrap();

        let dispatched_at = chrono::Utc::now() - chrono::Duration::seconds(dispatched_secs_ago);
        let mut meta = serde_json::json!({
            "attempt_count": 1,
            "goal_state": "in_progress",
            "worker_session_id": dead_session.id,
            "worker_key": "permagent",
            "dispatched_at": dispatched_at.to_rfc3339(),
        });
        if let Some(rc) = retry_count {
            meta["retry_count"] = serde_json::json!(rc);
        }

        cards::create_card(
            pool,
            cards::CreateCard {
                project_id: PERSONAL_PROJECT_ID.to_string(),
                title: "R3 dead-worker test goal".to_string(),
                description: Some("test".to_string()),
                card_type: Some("goal".to_string()),
                column_id: Some(col.id),
                created_by: None,
                metadata_json: Some(meta),
            },
        )
        .await
        .unwrap()
    }

    /// Pins the bookkeeping half of R3: the FIRST time `goal_status` sees a
    /// worker that died with no error and no landing, it must requeue the
    /// goal and stamp `retry_count: 1` — REGARDLESS of whether the follow-up
    /// redispatch attempt itself can succeed in this context (a bare
    /// `extension_manager: None` context, deliberately, so this test is
    /// deterministic without touching the shared `HEADLESS_DISPATCH_POLICY_CONFIG`
    /// `OnceLock` other tests in this file already flag as collision-prone —
    /// see `create_roadmap_dispatches_a_real_child_session_once_a_dispatch_hook_is_installed`'s
    /// own doc comment. A full live-redispatch success path is exercised by
    /// precedent, not duplicated here:
    /// `dispatch_goal_fn_dispatches_an_internal_worker_through_a_headless_policy_with_no_extension_manager`
    /// already proves the SAME `dispatch_goal_fn`/`InternalSubagentEngine`
    /// pipeline this retry calls into (via `dispatch_goal_to`) succeeds given
    /// a real git baseline and a resolvable provider.
    ///
    /// Pre-fix, `handle_goal_status` has no such interception at all: this
    /// test's `retry_count` assertion fails outright (the field is never
    /// written).
    #[tokio::test]
    async fn goal_status_requeues_and_stamps_retry_count_on_a_first_silent_worker_death() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        // No `escalate`-shaped decision must ever be created by this
        // function itself — the whole point is to avoid ever reaching it on
        // the first occurrence.
        let before_decisions: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM decisions")
            .fetch_one(&pool)
            .await
            .unwrap();

        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must succeed even when the follow-up redispatch cannot");

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .get("retry_count")
                .and_then(|v| v.as_u64()),
            Some(1),
            "the first silent death must stamp retry_count=1: {:?}",
            updated.metadata_json
        );

        let after_decisions: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM decisions")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(
            before_decisions, after_decisions,
            "a first silent death must never create an escalation decision itself"
        );

        // Still a well-formed tool result either way (dispatch failing here
        // — no extension manager, by construction — falls through to the
        // ordinary status report rather than propagating an error).
        assert!(!result.content.is_empty());
    }

    /// The other half of R3's pin: a SECOND occurrence of the identical
    /// shape (`retry_count` already 1) must NOT retry again — `goal_status`
    /// reports the dead state normally, exactly as it did before this fix,
    /// so the coordinator can still reach for `escalate` on this (now
    /// genuinely exhausted) goal. `record_escalation`'s own no-auto-answer
    /// rule (M6 Defect #3) is never touched by this lane.
    #[tokio::test]
    async fn goal_status_does_not_auto_retry_a_second_silent_worker_death() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, Some(1), 200).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must still report normally on a second occurrence");
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(
            !text.contains("Automatically retried"),
            "a second silent death must not auto-retry again: {text}"
        );
        let parsed: serde_json::Value =
            serde_json::from_str(&text).expect("the normal path returns the status JSON");
        assert_eq!(
            parsed.get("session_alive").and_then(|v| v.as_bool()),
            Some(false)
        );
        assert!(parsed.get("error").is_none_or(|v| v.is_null()));

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .get("retry_count")
                .and_then(|v| v.as_u64()),
            Some(1),
            "retry_count must stay at 1 — no second auto-retry"
        );
    }

    /// Y4b pin (harness loop, 2026-09-10, from Lane A12's M12 forensics): a
    /// goal whose worker is registered in `GOAL_WORKERS` — i.e. every goal
    /// with a live dispatched worker — must report `session_alive: true`, and
    /// R3 must therefore leave it alone.
    ///
    /// The card here is byte-for-byte the shape
    /// `goal_status_requeues_and_stamps_retry_count_on_a_first_silent_worker_death`
    /// uses (in_progress, no error, no retry yet, internal engine, well past
    /// the grace period); the ONLY difference is that a worker is registered
    /// for it. Pre-Y4b `session_alive` was `manager.is_session_busy(sid)` over
    /// `AgentManager`'s `cancel_tokens`, a registry a dispatched goal worker
    /// never enters, so this test fails twice against the old code: it reports
    /// `false` and R3 requeues a live worker (A12 measured exactly this in
    /// fx04/05/09/10 — fx09's coordinator read `session_alive:false` at
    /// 21:22:2x and that same worker committed `5f38917` at 21:23:35).
    // `GOAL_WORKERS` is process-global and the fixture's session ids are
    // sequential per fresh temp DB, so two of these tests in parallel hold the
    // SAME worker session id under different card ids and
    // `live_goal_worker_card_for_session` answers with the other test's card.
    // Serialized against each other, not against the whole suite.
    #[tokio::test]
    #[serial_test::serial(goal_workers)]
    async fn goal_status_reports_a_registered_goal_worker_as_alive_and_leaves_it_alone() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;
        let worker_session_id = card
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .expect("fixture stamps a worker session id")
            .to_string();

        // The one difference from the R3 fixture: this worker is alive, in the
        // registry dispatch actually puts it in.
        register_goal_worker(
            &card.id,
            &worker_session_id,
            goal_engine::GoalKill::None,
            None,
        );
        assert!(goal_worker_is_live(&card.id));
        assert_eq!(
            live_goal_worker_card_for_session(&worker_session_id),
            Some(card.id.clone()),
            "interrupt_agent must be able to reach the same answer from a session id"
        );

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();
        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must report a live worker normally");
        let text = result.content[0].as_text().unwrap().text.clone();
        // GOAL_WORKERS is process-global; drop this test's entry before any
        // assertion can unwind past it.
        take_goal_worker(&card.id);
        assert!(
            live_goal_worker_card_for_session(&worker_session_id).is_none(),
            "a worker whose handle has been taken is no longer live"
        );

        let parsed: serde_json::Value =
            serde_json::from_str(&text).expect("the normal path returns the status JSON");
        assert_eq!(
            parsed.get("session_alive").and_then(|v| v.as_bool()),
            Some(true),
            "a registered goal worker is alive: {text}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert!(
            updated.metadata_json.get("retry_count").is_none(),
            "R3's auto-requeue must never fire on a live worker: {:?}",
            updated.metadata_json
        );
    }

    // ── Y8b: send_message is not a way to drive a live goal worker ───────
    //
    // A14's M14 forensics, glm47/fx06: the coordinator's `send_message` text
    // landed in worker session `20260910_2` as message #26 at 23:30:26 while
    // the goal-engine dispatch was mid-tool-call in that SAME session (its
    // prompt was message #17, ten seconds earlier). Two reply loops, one
    // session; the coordinator never spoke again and the run died at the
    // driver's ceiling. `try_register_cancel_token` cannot catch this — goal
    // workers live in `GOAL_WORKERS`, not in `AgentManager`'s `cancel_tokens`,
    // the same registry split Y4b fixed for `goal_status`.

    /// The refusal, and the advice that makes it actionable. Same fixture
    /// shape as the Y4b pin: the ONLY thing that makes this session refuse is
    /// its `GOAL_WORKERS` entry.
    // `GOAL_WORKERS` is process-global and the fixture's session ids are
    // sequential per fresh temp DB, so two of these tests in parallel hold the
    // SAME worker session id under different card ids and
    // `live_goal_worker_card_for_session` answers with the other test's card.
    // Serialized against each other, not against the whole suite.
    #[tokio::test]
    #[serial_test::serial(goal_workers)]
    async fn send_message_refuses_a_live_goal_worker_and_says_what_can_be_done_instead() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;
        let worker_session_id = card
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .expect("fixture stamps a worker session id")
            .to_string();

        register_goal_worker(
            &card.id,
            &worker_session_id,
            goal_engine::GoalKill::None,
            None,
        );

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();
        let mut args = JsonObject::new();
        args.insert(
            "session_id".to_string(),
            serde_json::json!(worker_session_id),
        );
        args.insert(
            "message".to_string(),
            serde_json::json!("How is the fragile-package work going?"),
        );
        let cancel = CancellationToken::new();
        let err = client
            .handle_send_message("20260910_coordinator", &cancel, Some(args))
            .await
            .expect_err("a live goal worker must refuse send_message");

        // GOAL_WORKERS is process-global; drop this test's entry before any
        // assertion can unwind past it.
        take_goal_worker(&card.id);
        assert!(
            live_goal_worker_card_for_session(&worker_session_id).is_none(),
            "the guard is registry-driven: with the handle taken, this session \
             is no longer a live worker"
        );

        assert!(
            err.contains(&card.id),
            "the refusal must name the goal so the coordinator can act on it: {err}"
        );
        assert!(
            err.contains("goal_status"),
            "the refusal must point at the one reader that DOES answer for a live worker: {err}"
        );
        // G13 M3: under PERMAGENT_HEADLESS_WORKER=internal neither of the
        // original redirects works — `steer_goal` refuses an internal worker
        // outright and `message_goal` takes `from_goal`/`to_goal`, not a
        // `card_id`. Advice that cannot be followed is worse than none.
        assert!(
            !err.contains("steer_goal"),
            "an internal worker is not steerable; do not send the coordinator there: {err}"
        );
        assert!(
            !err.contains("message_goal"),
            "message_goal needs a card on BOTH sides, which a coordinator does not have: {err}"
        );
    }

    /// The inline drain's wall-clock budget: default, explicit, and disabled.
    /// A14 measured 500 s of unbounded drain on glm47/fx05 — 61 worker provider
    /// calls and $0.4732 of that fixture's $0.5042 — ending only when the eval
    /// driver killed the process.
    #[test]
    fn the_send_message_reply_budget_defaults_and_can_be_disabled() {
        {
            let _guard = env_lock::lock_env([(SEND_MESSAGE_MAX_SECS_ENV, None::<&str>)]);
            assert_eq!(
                send_message_reply_budget_from_env(),
                Some(std::time::Duration::from_secs(
                    SEND_MESSAGE_DEFAULT_MAX_SECS
                )),
                "an unset budget is 120s, not unlimited"
            );
        }
        {
            let _guard = env_lock::lock_env([(SEND_MESSAGE_MAX_SECS_ENV, Some("5"))]);
            assert_eq!(
                send_message_reply_budget_from_env(),
                Some(std::time::Duration::from_secs(5))
            );
        }
        {
            let _guard = env_lock::lock_env([(SEND_MESSAGE_MAX_SECS_ENV, Some("0"))]);
            assert_eq!(
                send_message_reply_budget_from_env(),
                None,
                "0 means unlimited — the pre-Y8b behaviour, opt-in"
            );
        }
        {
            // Garbage must not silently disable the bound.
            let _guard = env_lock::lock_env([(SEND_MESSAGE_MAX_SECS_ENV, Some("soon"))]);
            assert_eq!(
                send_message_reply_budget_from_env(),
                Some(std::time::Duration::from_secs(
                    SEND_MESSAGE_DEFAULT_MAX_SECS
                ))
            );
        }
    }

    // ── Y8d: a model-authored tag cannot veto dispatch ───────────────────
    //
    // A14's ranked mechanism 5, glm47/fx08: `decompose_roadmap` tagged the
    // card `["code_edit", "cli", "testing"]`. `cli` is an ADAPTER requirement
    // (`WorkerCapabilities::supports_cli_tools`); the internal `permagent`
    // persona does not declare it and external workers were off
    // (`PERMAGENT_HEADLESS_WORKER=internal`), so every candidate was marked
    // unavailable, `select_best_worker` returned `None`, `attempt_count`
    // stayed at 0, and the coordinator escalated twice into decisions nobody
    // can answer. DeepSeek tagged the same fixture
    // `["code_edit", "shell", "testing"]` and dispatched fine — the tags are
    // model-authored free text, and the roster is the authority.

    /// The `permagent` persona's real declared kinds, as A14 recorded them.
    fn permagent_roster() -> std::collections::BTreeSet<String> {
        tags(&["code_edit", "shell", "git", "search", "testing"])
    }

    #[test]
    fn fx08s_cli_tag_is_dropped_so_the_goal_stays_dispatchable() {
        let required = required_kinds_within_roster(
            vec![
                "code_edit".to_string(),
                "cli".to_string(),
                "testing".to_string(),
            ],
            &permagent_roster(),
        );
        assert_eq!(
            required,
            vec!["code_edit".to_string(), "testing".to_string()],
            "the two satisfiable tags survive; `cli` — which no worker declares — does not"
        );
    }

    /// Never an empty requirement set from a non-empty tag list:
    /// `select_best_worker` reads empty as "any available worker matches", so
    /// silently emptying a real requirement would route a goal on cost alone.
    #[test]
    fn a_goal_whose_every_tag_is_unknown_falls_back_to_the_base_kinds() {
        let required = required_kinds_within_roster(
            vec!["cli".to_string(), "telepathy".to_string()],
            &permagent_roster(),
        );
        assert_eq!(
            required,
            BASE_REQUIRED_KINDS
                .iter()
                .map(|k| k.to_string())
                .collect::<Vec<_>>()
        );
        assert!(!required.is_empty(), "never an empty requirement set");
    }

    /// Z1-3's contract is untouched: an explicitly EMPTY tag list means "no
    /// requirement", which `constrain_tags` produces on purpose at card
    /// creation so a fully-ungrounded goal is dispatchable rather than blocked.
    #[test]
    fn an_explicitly_empty_tag_list_still_means_no_requirement() {
        assert!(required_kinds_within_roster(vec![], &permagent_roster()).is_empty());
    }

    /// An unreadable/empty roster is "we do not know", not "nothing is
    /// supported" — filtering on it would drop every tag on every goal.
    #[test]
    fn an_empty_roster_filters_nothing() {
        let original = vec!["code_edit".to_string(), "cli".to_string()];
        assert_eq!(
            required_kinds_within_roster(original.clone(), &tags(&[])),
            original
        );
    }

    /// `supports_requirement` accepts several spellings per adapter capability
    /// while `configured_worker_capabilities` emits only the canonical one. A
    /// satisfiable tag must not be dropped over spelling.
    #[test]
    fn an_alias_spelling_of_a_declared_capability_survives() {
        let roster = tags(&["code_edit", "cancellation", "mcp"]);
        assert_eq!(
            required_kinds_within_roster(
                vec!["cancel".to_string(), "mcp_tools".to_string()],
                &roster
            ),
            vec!["cancel".to_string(), "mcp_tools".to_string()],
            "aliases are compared canonically and kept in their original spelling"
        );
    }

    /// The half of Y8d that makes it bite on fx08's actual configuration. That
    /// run had `PERMAGENT_HEADLESS_WORKER=internal`, so ranked dispatch could
    /// only ever pick `permagent` — but the roster still CONTAINS external
    /// CLIs, and the whole-roster union
    /// (`council::plan::configured_worker_capabilities`) therefore claims
    /// `cli`. Intersecting against that union would have kept fx08's `cli` tag
    /// and changed nothing. Run against the REAL default roster.
    #[test]
    fn the_internal_only_dispatch_pool_does_not_claim_an_external_clis_capabilities() {
        let config = default_config();

        let unrestricted = pool_capabilities(&dispatchable_personas(&config, false, None));
        let internal_only = pool_capabilities(&dispatchable_personas(&config, true, None));

        assert!(
            internal_only.contains("code_edit"),
            "the internal worker's own kinds survive: {internal_only:?}"
        );
        assert!(
            internal_only.len() < unrestricted.len(),
            "restricting the pool must narrow what it can satisfy: \
             {internal_only:?} vs {unrestricted:?}"
        );
        assert_eq!(
            required_kinds_within_roster(
                vec![
                    "code_edit".to_string(),
                    "cli".to_string(),
                    "testing".to_string()
                ],
                &internal_only,
            ),
            vec!["code_edit".to_string(), "testing".to_string()],
            "fx08's tag set, against fx08's actual dispatch pool"
        );
    }

    /// The real shipped roster. `..Default::default()` rather than naming every
    /// field, so a new field on `AgentConfig` cannot break these tests.
    fn default_config() -> agent_identity::AgentConfig {
        agent_identity::AgentConfig {
            workers: agent_identity::default_roster(),
            ..Default::default()
        }
    }

    fn kinds(list: &[&str]) -> Vec<String> {
        list.iter().map(|k| k.to_string()).collect()
    }

    /// G13 H3. The roster intersection is a UNION over the pool, but
    /// `select_best_worker` needs ONE worker to satisfy every kind. Under
    /// `PERMAGENT_HEADLESS_WORKER=internal` the pool is `permagent`
    /// (code_edit, shell, git, search, testing) and `reviewer` (review), so
    /// `["code_edit", "review"]` survived Y8d untouched and still deadlocked —
    /// the fx08 class, one union away from fixed. Both halves are asserted
    /// here: the narrowing, and the fact that the narrowed set is one
    /// `select_best_worker` actually accepts.
    #[test]
    fn a_tag_set_no_single_worker_satisfies_is_narrowed_rather_than_deadlocked() {
        let config = default_config();
        let dispatchable = dispatchable_personas(&config, true, None);

        let candidates: Vec<goal_state::WorkerCandidate> = config
            .workers
            .iter()
            .filter(|(_, persona)| persona.engine.is_dispatchable())
            .filter(|(_, persona)| worker_engine_allowed_for_ranked_dispatch(&persona.engine, true))
            .map(|(key, persona)| goal_state::WorkerCandidate {
                key: key.clone(),
                available: true,
                tool_kinds: persona.tool_kinds.clone(),
                cost_tier: persona.cost_tier.clone(),
                active_sessions: 0,
            })
            .collect();

        let asked = kinds(&["code_edit", "review"]);
        assert!(
            goal_state::select_best_worker(&candidates, &asked).is_err(),
            "precondition: no single internal worker does both, which is the deadlock"
        );

        let narrowed = satisfiable_by_one_worker(asked, &dispatchable);
        assert_eq!(
            narrowed,
            kinds(&["code_edit"]),
            "the job survives; the trailing tag no worker can pair with it does not"
        );
        assert_eq!(
            goal_state::select_best_worker(&candidates, &narrowed).unwrap(),
            "permagent",
            "and the narrowed set is one the selector answers"
        );
    }

    /// Never an empty requirement set out of this path either: empty means
    /// "any worker will do" to `select_best_worker`, which would route a real
    /// requirement on cost alone.
    #[test]
    fn a_requirement_no_worker_satisfies_at_all_falls_back_to_the_base_kinds() {
        let config = default_config();
        let dispatchable = dispatchable_personas(&config, true, None);
        assert_eq!(
            satisfiable_by_one_worker(kinds(&["telepathy", "finance"]), &dispatchable),
            kinds(&BASE_REQUIRED_KINDS),
        );
        assert!(
            satisfiable_by_one_worker(vec![], &dispatchable).is_empty(),
            "an explicitly empty requirement is still Z1-3's 'anyone may take this'"
        );
    }

    /// G13 M1. "Dispatchable" has to mean the same thing here as in the
    /// candidate list, which requires the availability probe. With the CLI
    /// binaries absent — the DEFAULT configuration on a machine without them —
    /// `cli` is not a capability this dispatch can satisfy, and keeping it
    /// would mark every remaining candidate unavailable: fx08, outside the one
    /// configuration Y8d tested. The cache is seeded so this test never shells
    /// out and never depends on what is installed.
    #[test]
    fn an_unavailable_workers_exclusive_capability_is_not_this_dispatchs_capability() {
        let config = default_config();
        let cache = ProbeCache::new();
        for key in config.workers.keys() {
            cache.set(key, key == "permagent", None);
        }

        let roster_only = pool_capabilities(&dispatchable_personas(&config, false, None));
        let really_available =
            pool_capabilities(&dispatchable_personas(&config, false, Some(&cache)));

        assert!(
            roster_only.contains("cli"),
            "precondition: an external CLI declares `cli` in the default roster: {roster_only:?}"
        );
        assert!(
            !really_available.contains("cli"),
            "a worker whose binary is missing cannot satisfy anything: {really_available:?}"
        );
        assert_eq!(
            required_kinds_within_roster(kinds(&["code_edit", "cli"]), &really_available),
            kinds(&["code_edit"]),
            "so the tag that would have vetoed dispatch is dropped"
        );
    }

    async fn goal_card_with_tags(pool: &sqlx::Pool<sqlx::Sqlite>, tags: &[&str]) -> cards::Card {
        use crate::projects::PERSONAL_PROJECT_ID;
        cards::seed_goal_columns(pool, PERSONAL_PROJECT_ID)
            .await
            .unwrap();
        let col = cards::get_goal_column(pool, PERSONAL_PROJECT_ID, "in_progress")
            .await
            .unwrap()
            .unwrap();
        cards::create_card(
            pool,
            cards::CreateCard {
                project_id: PERSONAL_PROJECT_ID.to_string(),
                title: "G13 explicit-request test goal".to_string(),
                description: Some("test".to_string()),
                card_type: Some("goal".to_string()),
                column_id: Some(col.id),
                created_by: None,
                metadata_json: Some(serde_json::json!({
                    "goal_state": "in_progress",
                    "tags": tags,
                })),
            },
        )
        .await
        .unwrap()
    }

    /// G13 M2. Y8d intersected the tags against the requested persona's OWN
    /// capabilities before the adapter guard read them, which dropped exactly
    /// the capability the guard exists to refuse — so explicitly requesting a
    /// worker that genuinely cannot do the job dispatched in silence. The
    /// guard now reads the raw tags. `permagent` is the in-process subagent:
    /// `supports_cli_tools` is false, and this goal asks for `cli`.
    #[tokio::test]
    async fn an_explicitly_requested_worker_that_cannot_do_the_job_is_still_refused() {
        let tmp = tempfile::tempdir().unwrap();
        // No agent.yaml under this root, so the roster is the default one.
        let _guard =
            env_lock::lock_env([("PERMAGENT_PATH_ROOT", Some(tmp.path().to_str().unwrap()))]);
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = goal_card_with_tags(&pool, &["code_edit", "cli"]).await;

        let err = select_requested_worker(&pool, &ProbeCache::new(), &card, "permagent", true)
            .await
            .expect_err("an in-process subagent cannot run CLI tools, and must say so");
        assert!(
            err.contains("cli"),
            "the refusal must name the capability it lacks: {err}"
        );

        // The control: the same request without the impossible tag goes through.
        let ok_card = goal_card_with_tags(&pool, &["code_edit", "testing"]).await;
        let selection =
            select_requested_worker(&pool, &ProbeCache::new(), &ok_card, "permagent", true)
                .await
                .expect("a satisfiable explicit request still dispatches");
        assert_eq!(selection.worker_key, "permagent");
    }

    // ── Y8c: every liveness reader tells the same story ──────────────────

    /// A14's ranked mechanism 3, pinned as the contradiction it actually was:
    /// fx04's coordinator read `goal_status → "session_alive": true` and
    /// `view_session → "Status: idle"` IN THE SAME TURN, kept polling
    /// `view_session` (offsets 19, 21, 23 were all `view_session`), and its
    /// very next model call was the 441-second runaway. Y4b routed
    /// `goal_status` through `GOAL_WORKERS`; `view_session` was left on
    /// `AgentManager::is_session_busy`, a map a dispatched goal worker never
    /// enters. This test fails on the second assertion against pre-Y8c code.
    // `GOAL_WORKERS` is process-global and the fixture's session ids are
    // sequential per fresh temp DB, so two of these tests in parallel hold the
    // SAME worker session id under different card ids and
    // `live_goal_worker_card_for_session` answers with the other test's card.
    // Serialized against each other, not against the whole suite.
    #[tokio::test]
    #[serial_test::serial(goal_workers)]
    async fn view_session_and_goal_status_agree_that_a_live_goal_worker_is_alive() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;
        let worker_session_id = card
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .expect("fixture stamps a worker session id")
            .to_string();

        register_goal_worker(
            &card.id,
            &worker_session_id,
            goal_engine::GoalKill::None,
            None,
        );

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut status_args = JsonObject::new();
        status_args.insert("card_id".to_string(), serde_json::json!(card.id));
        let status_text = client
            .handle_goal_status(Some(status_args))
            .await
            .expect("goal_status must report a live worker normally")
            .content[0]
            .as_text()
            .unwrap()
            .text
            .clone();

        let mut view_args = JsonObject::new();
        view_args.insert(
            "session_id".to_string(),
            serde_json::json!(worker_session_id),
        );
        let view_text = client
            .handle_view_session("20260910_coordinator", Some(view_args))
            .await
            .expect("view_session must read a live worker's session")
            .content[0]
            .as_text()
            .unwrap()
            .text
            .clone();

        // GOAL_WORKERS is process-global; drop this test's entry before any
        // assertion can unwind past it.
        take_goal_worker(&card.id);
        assert!(
            live_goal_worker_card_for_session(&worker_session_id).is_none(),
            "both readers are registry-driven"
        );

        let status: serde_json::Value =
            serde_json::from_str(&status_text).expect("the status JSON");
        assert_eq!(
            status.get("session_alive").and_then(|v| v.as_bool()),
            Some(true),
            "Y4b's half: {status_text}"
        );
        assert!(
            !view_text.contains("Status: idle"),
            "view_session must not call a live goal worker idle in the same turn \
             goal_status calls it alive: {view_text}"
        );
        assert!(
            view_text.contains("busy") && view_text.contains(&card.id),
            "view_session must say busy and name the goal: {view_text}"
        );
    }

    // ── F1a: R3 misfire guard — a minimum-elapsed grace period and an
    // execution-receipt cross-check (harness loop, Lane F1 2026-09-10, from
    // F10 forensics) ──

    /// Pins the exact misfire F10 traced: R3 must never treat a goal
    /// dispatched only seconds ago as "exited" — before this fix,
    /// `dispatched_at` was read but never used as a grace period, and this
    /// shape (10s elapsed, session not yet marked busy) auto-retried
    /// immediately, orphaning the real dispatch (fx01-M10's observed 5.5s
    /// misfire window and smaller). Pre-fix: this test's "no retry_count"
    /// assertion fails — the pre-F1 guard has no `min_grace_elapsed` term at
    /// all and would auto-retry here.
    #[tokio::test]
    async fn goal_status_does_not_treat_a_freshly_dispatched_goal_as_dead() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 10).await;

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must still succeed");
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(
            !text.contains("Automatically retried"),
            "a goal dispatched only 10s ago must never be treated as silently dead: {text}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .get("retry_count")
                .and_then(|v| v.as_u64()),
            None,
            "no retry_count must be stamped before the grace period elapses"
        );
    }

    /// Past the grace period, a goal whose own `execution_receipt` still
    /// reports a LIVE, current-lifecycle, recently-heartbeated attempt must
    /// also never be treated as dead — this is the second of F1a's two new
    /// guard terms, independent of the grace period. Pre-fix: `receipt_not_
    /// live` does not exist at all and this call auto-retries.
    #[tokio::test]
    async fn goal_status_does_not_treat_a_goal_as_dead_when_its_execution_receipt_is_live() {
        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();
        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;
        let dead_session_id = card
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .unwrap()
            .to_string();

        let receipt = ExecutionReceipt::new(
            "permagent",
            dead_session_id,
            serde_json::json!({}),
            daemon_lifecycle_id().to_string(),
            chrono::Utc::now().to_rfc3339(),
            1,
        );
        cards::merge_card_metadata(
            &pool,
            &card.id,
            serde_json::json!({ "execution_receipt": receipt }),
            false,
        )
        .await
        .unwrap();

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must still succeed");
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(
            !text.contains("Automatically retried"),
            "a live execution_receipt must block R3's redispatch even past the grace period: \
             {text}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .get("retry_count")
                .and_then(|v| v.as_u64()),
            None,
            "no auto-retry must happen while the execution_receipt still reads live"
        );
    }

    /// F1c: past the grace period, with the execution_receipt genuinely dead
    /// (none recorded here at all — the "nothing to contradict" case), a
    /// worktree holding a real commit beyond baseline must route to review
    /// instead of being silently redispatched over — the exact fx05 shape
    /// F10 traced (a correct, committed fix from the abandoned session the
    /// goal's own bookkeeping never rediscovered). Pre-fix: R3 has no
    /// worktree inspection at all and would redispatch straight over this
    /// commit.
    #[tokio::test]
    async fn goal_status_routes_to_review_instead_of_redispatch_when_abandoned_work_exists() {
        use crate::projects::PERSONAL_PROJECT_ID;

        let tmp = tempfile::tempdir().unwrap();
        let sm = Arc::new(SessionManager::new(tmp.path().to_path_buf()));
        let pool = sm.pool_clone().await.unwrap();

        let repo = tmp.path().join("proj");
        init_git_repo_for_dispatch_test(&repo);
        let baseline = String::from_utf8(
            std::process::Command::new("git")
                .arg("-C")
                .arg(&repo)
                .args(["rev-parse", "HEAD"])
                .output()
                .unwrap()
                .stdout,
        )
        .unwrap()
        .trim()
        .to_string();
        sqlx::query("UPDATE projects SET root_path = ? WHERE id = ?")
            .bind(repo.to_str().unwrap())
            .bind(PERSONAL_PROJECT_ID)
            .execute(&pool)
            .await
            .unwrap();

        let card = dead_silent_worker_goal(&pool, &sm, None, 200).await;
        let dead_session_id = card
            .metadata_json
            .get("worker_session_id")
            .and_then(|v| v.as_str())
            .unwrap()
            .to_string();
        cards::merge_card_metadata(
            &pool,
            &card.id,
            serde_json::json!({ "baseline_commit": baseline }),
            false,
        )
        .await
        .unwrap();

        // The abandoned session's own worktree at the exact conventional
        // path, with a real commit beyond baseline.
        let worktree = repo
            .parent()
            .unwrap()
            .join(goal_engine::GOAL_WORKTREES_DIR)
            .join(&dead_session_id);
        let git_repo = |args: &[&str]| {
            let out = std::process::Command::new("git")
                .arg("-C")
                .arg(&repo)
                .args(args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "git {:?} (in repo) failed: {}",
                args,
                String::from_utf8_lossy(&out.stderr)
            );
        };
        git_repo(&[
            "worktree",
            "add",
            "-q",
            "-b",
            "abandoned-fix",
            worktree.to_str().unwrap(),
            &baseline,
        ]);
        let git_worktree = |args: &[&str]| {
            let out = std::process::Command::new("git")
                .arg("-C")
                .arg(&worktree)
                .args(args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "git {:?} (in worktree) failed: {}",
                args,
                String::from_utf8_lossy(&out.stderr)
            );
        };
        git_worktree(&["config", "user.email", "t@t.t"]);
        git_worktree(&["config", "user.name", "t"]);
        git_worktree(&["config", "commit.gpgsign", "false"]);
        std::fs::write(worktree.join("fix.txt"), "the real fix\n").unwrap();
        git_worktree(&["add", "."]);
        git_worktree(&["commit", "-q", "-m", "the real fix"]);
        let head = String::from_utf8(
            std::process::Command::new("git")
                .arg("-C")
                .arg(&worktree)
                .args(["rev-parse", "HEAD"])
                .output()
                .unwrap()
                .stdout,
        )
        .unwrap()
        .trim()
        .to_string();

        let context = PlatformExtensionContext {
            extension_manager: None,
            session_manager: sm.clone(),
            session: None,
        };
        let client = OrchestratorClient::new(context).unwrap();

        let mut args = JsonObject::new();
        args.insert("card_id".to_string(), serde_json::json!(card.id));
        let result = client
            .handle_goal_status(Some(args))
            .await
            .expect("goal_status must still succeed");
        let text = result.content[0].as_text().unwrap().text.clone();
        assert!(
            !text.contains("Automatically retried"),
            "work present in the abandoned worktree must never be redispatched over: {text}"
        );
        assert!(
            text.contains(&head),
            "the status message must name the abandoned commit: {text}"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        assert_eq!(
            updated
                .metadata_json
                .get("retry_count")
                .and_then(|v| v.as_u64()),
            None,
            "no auto-retry must have happened"
        );
        let annotation = updated
            .metadata_json
            .get("abandoned_work")
            .and_then(|v| v.as_str())
            .expect("abandoned_work must be recorded on the card (F1c)");
        assert!(
            annotation.contains(&head) && annotation.contains(worktree.to_str().unwrap()),
            "abandoned_work must name both the worktree and the sha: {annotation}"
        );
        assert_eq!(
            updated
                .metadata_json
                .get("needs_human_attention")
                .and_then(|v| v.as_bool()),
            Some(true),
            "found abandoned work must route to review via needs_human_attention"
        );

        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            col.state_binding.as_deref(),
            Some("in_progress"),
            "the card must stay in_progress — never bounced back to Ready over real work"
        );
    }

    // ── Lane R1 (harness improvement loop): replay slice mechanism smoke ──
    //
    // The `replay_slice_smoke` test itself lives above, next to the other
    // roadmap-handler tests. A SECOND, differently-shaped `replay_slice_
    // smoke` was drafted here (real `install_dispatch_hook_for_headless_
    // session` + `PERMAGENT_PROVIDER_CASSETTE` env var + an asserted
    // `misses.jsonl` line from the dispatched worker) and deliberately NOT
    // kept — see `HARNESS_LOOP_LOG.md` `## Lane R1` for the three reasons:
    // a duplicate fn name in one module is a hard compile error; it would be
    // the THIRD test to call a `GOAL_DISPATCH_HOOK` installer, which the
    // note above `goal_advance_on_an_unknown_id_names_the_known_goal_card_
    // ids` explicitly asks a future lane NOT to add before that OnceLock is
    // given a shared serial key; and its central assertion races
    // `std::env::remove_var` against the worker's own detached
    // `tokio::spawn`, so the var could be gone before the worker constructs
    // its provider. The factory choke point it was trying to prove is
    // instead pinned deterministically, with no globals and no env var, by
    // `provider_registry.rs`'s own `replay_mode_never_constructs_the_real_
    // provider` / `record_mode_still_constructs_and_guards_the_real_
    // provider`.

    // ── Lane R26b (A25 analysis): a Ready goal refused re-dispatch by the
    // attempt cap is salvaged, never stranded ──────────────────────────────
    //
    // Mechanism: R18g's headless unblock (`maybe_headless_unblock_verify_
    // gap`) resumes a Held goal by flipping it straight to Ready — it never
    // redispatches the goal itself. The drain's own re-dispatch sweep
    // (`redispatch_ready_goals`) picks Ready goals up separately, and by
    // then the goal's attempt cap is often already spent (three real
    // dispatch/hold cycles got it to R18g's resume in the first place). Before
    // this lane, a `dispatch(...)` refusal in that sweep fell straight
    // through to a bare `tracing::debug!` — no audit row, no salvage
    // attempt — and `handle_goal_timeout` (the OTHER backstop, the cap-
    // expiry sweep) only ever acted on `in_progress` cards, so nothing in
    // the whole drain could ever act on a Ready card again. The goal sat
    // Ready forever with a committed, unlanded, genuinely verifiable fix on
    // its branch and zero trace in `decision_audit` explaining why.

    /// The exact A25 shape (mechanism above), reproduced as directly as
    /// `handle_refused_redispatch` allows: a Ready goal at the attempt cap
    /// with a genuinely committed, verifiable fix on its branch. Must leave
    /// a `redispatch_refused:attempt_cap_exhausted` audit row AND salvage
    /// the committed work — claim it (Ready → InProgress, Tier-0, no
    /// proof needed) and run it through the SAME verify → Review pipeline
    /// any other salvage site uses — instead of leaving it to lose this
    /// exact race on every future sweep.
    #[tokio::test]
    async fn ready_goal_refused_redispatch_salvages_committed_work() {
        let pool = test_pool().await;
        let (dir, baseline, head) = r20b_worktree_with_committed_fix("r26b-redispatch-salvage");
        let card = setup_goal_in_state(&pool, "ready", 3).await; // attempt_count == DEFAULT_ATTEMPT_CAP
        cards::set_goal_dispatch_evidence(
            &pool,
            &card.id,
            serde_json::json!({
                "worktree_path": dir.path().to_string_lossy(),
                "head_commit": head,
                "commits": [],
                "baseline_commit": baseline,
                "files_changed": 1,
                "insertions": 1,
                "deletions": 0,
            }),
        )
        .await
        .unwrap();
        let session_id = format!("r26b-worker-{}", uuid::Uuid::new_v4());
        sqlx::query("INSERT INTO sessions (id, working_dir) VALUES (?, ?)")
            .bind(&session_id)
            .bind(dir.path().to_string_lossy().as_ref())
            .execute(&pool)
            .await
            .unwrap();
        persist_card_meta(&pool, &card.id, |m| {
            m.insert(
                "worker_session_id".to_string(),
                serde_json::json!(session_id),
            );
            // Item 3: R18g's own resume already stamped this before this
            // sweep ran — present here purely as a realistic fixture detail,
            // not itself asserted on (the sort it drives is a scheduling
            // concern of `redispatch_ready_goals`, exercised separately).
            m.insert(
                "resumed_by_headless_unblock_at".to_string(),
                serde_json::json!(chrono::Utc::now().to_rfc3339()),
            );
        })
        .await
        .unwrap();

        handle_refused_redispatch(
            &pool,
            &card.id,
            "budget exhausted: attempt cap reached (simulated dispatch refusal)",
            None,
        )
        .await;

        let audited: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM decision_audit WHERE goal_id = ? AND outcome = ?",
        )
        .bind(&card.id)
        .bind("redispatch_refused:attempt_cap_exhausted")
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(
            audited, 1,
            "the refusal itself must leave an audit row naming the gate"
        );

        let updated = cards::get_card(&pool, &card.id).await.unwrap().unwrap();
        let col = cards::get_column(&pool, &updated.column_id)
            .await
            .unwrap()
            .unwrap();
        assert_ne!(
            col.state_binding.as_deref(),
            Some("ready"),
            "a Ready goal refused re-dispatch by its own budget must never be left Ready — \
             the A25 defect this lane fixes"
        );
        let receipt = updated
            .metadata_json
            .get("salvaged_on_park")
            .expect("the committed, unlanded fix must be salvaged instead of stranded");
        assert_eq!(
            receipt.get("commits_ahead").and_then(|v| v.as_u64()),
            Some(1)
        );
    }

    /// The complementary A25 shape: a Ready goal refused re-dispatch by the
    /// same attempt cap, but with NOTHING committed past the dispatch
    /// baseline. Must still audit the refusal itself, AND leave salvage's
    /// own honest `salvage_skipped_no_commits` row — never silently drop
    /// the refusal, and never invent committed work that was never there —
    /// then park for a human exactly as an ordinary attempt-cap exhaustion
    /// always has.
    #[tokio::test]
